(371888,41321,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gözetleme kulesine vardığında, tüm tırmanış boyunca temposunu ...'::text,'korumuştu'::text,'korudu'::text,'koruyor'::text,'Gözetleme kulesine vardığında, tüm tırmanış boyunca temposunu korumuştu.'::text),
