(371896,41322,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вона триматиме цей темп, вона ... до сторожової вежі за десять хвилин.'::text,'добіжить'::text,'добігла б'::text,'добігла'::text,'Якщо вона триматиме цей темп, вона добіжить до сторожової вежі за десять хвилин.'::text),
