(371897,41322,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu tempoyu korursa, gözetleme kulesine on dakikada ...'::text,'ulaşacak'::text,'ulaşırdı'::text,'ulaştı'::text,'Bu tempoyu korursa, gözetleme kulesine on dakikada ulaşacak.'::text),
