(371950,41328,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона сказала, що її темп сьогодні ... трохи повільний. Звісно, вона злетіла на Велику китайську стіну.'::text,'був'::text,'є'::text,'має'::text,'Вона сказала, що її темп сьогодні був трохи повільний. Звісно, вона злетіла на Велику китайську стіну.'::text),
(371949,41328,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijo que su ritmo ... un poco lento hoy. Claro, subió volando la Gran Muralla.'::text,'era'::text,'está siendo'::text,'tiene'::text,'Dijo que su ritmo era un poco lento hoy. Claro, subió volando la Gran Muralla.'::text),
