(371951,41328,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bugün temposunun biraz yavaş ... söyledi. Tabii ki, Çin Seddi''ne uçarak çıktı.'::text,'olduğunu'::text,'olmakta olduğunu'::text,'sahip olduğunu'::text,'Bugün temposunun biraz yavaş olduğunu söyledi. Tabii ki, Çin Seddi''ne uçarak çıktı.'::text),
