(371959,41329,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... бігати в швидкому темпі. Очевидно, ті часи минули.'::text,'раніше ненавиділа'::text,'раніше ненавиділа'::text,'звикла ненавидіти'::text,'Вона раніше ненавиділа бігати в швидкому темпі. Очевидно, ті часи минули.'::text),
