(337247,37472,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte kuşlar muhtemelen kafeslerde oturmak yerine şehrin üzerinde ...'::text,'uçuyor olacak'::text,'uçacak'::text,'uçuyor'::text,'Yarın bu saatte kuşlar muhtemelen kafeslerde oturmak yerine şehrin üzerinde uçuyor olacak.'::text),
(337248,37472,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ebben az órában a madarak feltehetően a város fölött ..., nem kalitkákban ülnek.'::text,'repkednek majd'::text,'repülni fognak'::text,'repülnek'::text,'Holnap ebben az órában a madarak feltehetően a város fölött repkednek majd, nem kalitkákban ülnek.'::text),
(337251,37473,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn eine Käfigtür ..., verschwinden die Vögel für immer!'::text,'aufgeht'::text,'aufging'::text,'aufgehen wird'::text,'Wenn eine Käfigtür aufgeht, verschwinden die Vögel für immer!'::text),
(337255,37473,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо дверцята клітки ..., птахи зникають назавжди!'::text,'відчиняються'::text,'відчинилися'::text,'відчиняться'::text,'Якщо дверцята клітки відчиняються, птахи зникають назавжди!'::text),
(337254,37473,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si la puerta de una jaula se ..., los pájaros desaparecen para siempre!'::text,'abre'::text,'abrió'::text,'abrirá'::text,'¡Si la puerta de una jaula se abre, los pájaros desaparecen para siempre!'::text),
(337253,37473,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la porte d''une cage ..., les oiseaux disparaissent pour toujours !'::text,'s''ouvre'::text,'s''est ouverte'::text,'s''ouvrira'::text,'Si la porte d''une cage s''ouvre, les oiseaux disparaissent pour toujours !'::text),
(337256,37473,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir kafes kapısı ..., kuşlar sonsuza dek kaybolur!'::text,'açılırsa'::text,'açıldıysa'::text,'açılacaksa'::text,'Bir kafes kapısı açılırsa, kuşlar sonsuza dek kaybolur!'::text),
(337257,37473,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy kalitka ajtaja ..., a madarak örökre eltűnnek!'::text,'kinyílik'::text,'kinyílt'::text,'ki fog nyílni'::text,'Ha egy kalitka ajtaja kinyílik, a madarak örökre eltűnnek!'::text),
(337260,37474,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er noch einen Käfig öffnet, ... der Himmel in totalem Chaos!'::text,'explodiert'::text,'explodierte'::text,'explodierte'::text,'Wenn er noch einen Käfig öffnet, explodiert der Himmel in totalem Chaos!'::text),
(337264,37474,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він відчинить ще одну клітку, небо ... у повний хаос!'::text,'вибухне'::text,'вибухнуло б'::text,'вибухнуло'::text,'Якщо він відчинить ще одну клітку, небо вибухне у повний хаос!'::text),
(337263,37474,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si abre una jaula más, el cielo ... en un caos total!'::text,'estallará'::text,'estallaría'::text,'estalló'::text,'¡Si abre una jaula más, el cielo estallará en un caos total!'::text),
(337262,37474,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il ouvre encore une cage, le ciel ... en un chaos total !'::text,'explosera'::text,'exploserait'::text,'a explosé'::text,'S''il ouvre encore une cage, le ciel explosera en un chaos total !'::text),
(337265,37474,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir kafes daha açarsa, gökyüzü tam bir kaosla ...!'::text,'patlayacak'::text,'patlardı'::text,'patladı'::text,'Bir kafes daha açarsa, gökyüzü tam bir kaosla patlayacak!'::text),
(337266,37474,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha kinyit még egy kalitkát, az ég teljes káoszba ...!'::text,'robban'::text,'robbanna'::text,'robbant'::text,'Ha kinyit még egy kalitkát, az ég teljes káoszba robban!'::text),
(337269,37475,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn diese Käfige für immer verschlossen blieben, ... die Vögel den Himmel nie wieder!'::text,'sähen'::text,'sehen'::text,'sahen'::text,'Wenn diese Käfige für immer verschlossen blieben, sähen die Vögel den Himmel nie wieder!'::text),
(337273,37475,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби ці клітки залишилися замкненими назавжди, птахи ... неба!'::text,'ніколи б більше не побачили'::text,'ніколи більше не побачать'::text,'ніколи більше не бачили'::text,'Якби ці клітки залишилися замкненими назавжди, птахи ніколи б більше не побачили неба!'::text),
(337272,37475,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si esas jaulas se quedaran cerradas para siempre, los pájaros ... el cielo!'::text,'nunca volverían a ver'::text,'nunca volverán a ver'::text,'nunca volvieron a ver'::text,'¡Si esas jaulas se quedaran cerradas para siempre, los pájaros nunca volverían a ver el cielo!'::text),
(337271,37475,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ces cages restaient fermées pour toujours, les oiseaux ... le ciel !'::text,'ne reverraient jamais'::text,'ne reverront jamais'::text,'n''ont jamais revu'::text,'Si ces cages restaient fermées pour toujours, les oiseaux ne reverraient jamais le ciel !'::text),
(337274,37475,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O kafesler sonsuza dek kilitli kalsaydı, kuşlar gökyüzünü bir daha asla ...!'::text,'görmezdi'::text,'görmeyecek'::text,'görmedi'::text,'O kafesler sonsuza dek kilitli kalsaydı, kuşlar gökyüzünü bir daha asla görmezdi!'::text),
(337275,37475,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha azok a kalitkák örökre zárva maradnának, a madarak soha többé ... az eget!'::text,'nem látnák'::text,'nem fogják látni'::text,'nem látták'::text,'Ha azok a kalitkák örökre zárva maradnának, a madarak soha többé nem látnák az eget!'::text),
(337278,37476,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, angeblich ... diese Käfige von seinem Opa gebaut.'::text,'wurden'::text,'werden'::text,'bauten'::text,'Bestie, angeblich wurden diese Käfige von seinem Opa gebaut.'::text),
(337282,37476,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, ці клітки ... його дідусем.'::text,'були збудовані'::text,'будуються'::text,'збудували'::text,'Подруго, кажуть, ці клітки були збудовані його дідусем.'::text),
(337281,37476,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer esas jaulas ... por su abuelo.'::text,'fueron construidas'::text,'son construidas'::text,'construyeron'::text,'Amiga, al parecer esas jaulas fueron construidas por su abuelo.'::text),
(337280,37476,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment ces cages ... par son grand-père.'::text,'ont été construites'::text,'sont construites'::text,'ont construit'::text,'Ma belle, apparemment ces cages ont été construites par son grand-père.'::text),
(337283,37476,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duyduğuma göre o kafesler dedesi tarafından ...'::text,'yapılmış'::text,'yapılıyor'::text,'yaptı'::text,'Kanka, duyduğuma göre o kafesler dedesi tarafından yapılmış.'::text),
(337284,37476,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag azokat a kalitkákat a nagyapja ...'::text,'építette'::text,'építi'::text,'építették'::text,'Csajszi, állítólag azokat a kalitkákat a nagyapja építette.'::text),
(337287,37477,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, ich hab gehört, er ... jeden einzelnen Käfig vor Sonnenaufgang.'::text,'öffnete'::text,'wurde geöffnet'::text,'öffnend'::text,'Mädel, ich hab gehört, er öffnete jeden einzelnen Käfig vor Sonnenaufgang.'::text),
(337291,37477,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що він ... кожну клітку ще до світанку.'::text,'відчинив'::text,'був відчинений'::text,'відчиняючи'::text,'Подруго, я чула, що він відчинив кожну клітку ще до світанку.'::text),
(337290,37477,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me dijeron que ... todas y cada una de las jaulas antes del amanecer.'::text,'abrió'::text,'fue abierto'::text,'abriendo'::text,'Tía, me dijeron que abrió todas y cada una de las jaulas antes del amanecer.'::text),
(337289,37477,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il paraît qu''il ... chaque cage avant le lever du soleil.'::text,'a ouvert'::text,'a été ouvert'::text,'ouvrant'::text,'Meuf, il paraît qu''il a ouvert chaque cage avant le lever du soleil.'::text),
(337292,37477,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duydum ki gün doğmadan her bir kafesi ...'::text,'açmış'::text,'açılmış'::text,'açarak'::text,'Kızım, duydum ki gün doğmadan her bir kafesi açmış.'::text),
(337293,37477,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy napkelte előtt minden egyes kalitkát ...'::text,'kinyitott'::text,'ki lett nyitva'::text,'kinyitva'::text,'Csajszi, azt hallottam, hogy napkelte előtt minden egyes kalitkát kinyitott.'::text),
(337296,37478,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, er meinte, die Käfige ... bis heute Abend leer sein, aber er ist nicht sicher.'::text,'könnten'::text,'müssten'::text,'können nicht'::text,'Hör mal, er meinte, die Käfige könnten bis heute Abend leer sein, aber er ist nicht sicher.'::text),
(337300,37478,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він сказав, що клітки ... бути порожніми до вечора, але він не впевнений.'::text,'можуть'::text,'мусять'::text,'не можуть'::text,'Слухай, він сказав, що клітки можуть бути порожніми до вечора, але він не впевнений.'::text),
(337299,37478,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, dijo que las jaulas ... estar vacías para esta noche, pero no está seguro.'::text,'podrían'::text,'deben de'::text,'no pueden'::text,'Oye, dijo que las jaulas podrían estar vacías para esta noche, pero no está seguro.'::text),
(337298,37478,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il a dit que les cages ... être vides d''ici ce soir, mais il n''est pas sûr.'::text,'pourraient'::text,'doivent'::text,'ne peuvent pas'::text,'Écoute, il a dit que les cages pourraient être vides d''ici ce soir, mais il n''est pas sûr.'::text),
(337301,37478,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, kafeslerin bu akşama kadar boş ... söyledi ama emin değil.'::text,'olabileceğini'::text,'olması gerektiğini'::text,'olamayacağını'::text,'Dinle, kafeslerin bu akşama kadar boş olabileceğini söyledi ama emin değil.'::text),
(337302,37478,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy a kalitkák estére ... üresek lesznek, de nem biztos benne.'::text,'talán'::text,'biztosan'::text,'semmiképp sem'::text,'Figyelj, azt mondta, hogy a kalitkák estére talán üresek lesznek, de nem biztos benne.'::text),
(337305,37479,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du bist der Mann, ... bei Sonnenaufgang jeden Käfig geöffnet hat, ehrlich ikonisch.'::text,'der'::text,'das'::text,'dessen'::text,'Du bist der Mann, der bei Sonnenaufgang jeden Käfig geöffnet hat, ehrlich ikonisch.'::text),
(337309,37479,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти той чоловік, ... на світанку відчинив кожну клітку, чесно, культово.'::text,'який'::text,'яке'::text,'чий'::text,'Ти той чоловік, який на світанку відчинив кожну клітку, чесно, культово.'::text),
(337308,37479,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eres el hombre ... abrió todas las jaulas al amanecer, en serio, icónico.'::text,'que'::text,'lo cual'::text,'cuyo'::text,'Eres el hombre que abrió todas las jaulas al amanecer, en serio, icónico.'::text),
(337307,37479,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'T''es l''homme ... a ouvert chaque cage au lever du soleil, franchement iconique.'::text,'qui'::text,'lequel'::text,'dont'::text,'T''es l''homme qui a ouvert chaque cage au lever du soleil, franchement iconique.'::text),
(337310,37479,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün doğarken her kafesi ... adam sensin, açıkçası efsane.'::text,'açan'::text,'açtığı'::text,'açtığının'::text,'Gün doğarken her kafesi açan adam sensin, açıkçası efsane.'::text),
(337311,37479,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te vagy az a férfi, ... napkeltekor minden kalitkát kinyitott, őszintén ikonikus.'::text,'aki'::text,'ami'::text,'akinek'::text,'Te vagy az a férfi, aki napkeltekor minden kalitkát kinyitott, őszintén ikonikus.'::text),
(337314,37480,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der alte Mann sagte, er ... die Vögel jahrelang in diesen Käfigen gehalten.'::text,'habe'::text,'hat'::text,'hält'::text,'Der alte Mann sagte, er habe die Vögel jahrelang in diesen Käfigen gehalten.'::text),
(337318,37480,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Старий сказав, що він роками ... птахів у тих клітках.'::text,'тримав'::text,'тримав'::text,'тримає'::text,'Старий сказав, що він роками тримав птахів у тих клітках.'::text),
(337317,37480,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El anciano dijo que ... a los pájaros en esas jaulas durante años.'::text,'había tenido'::text,'ha tenido'::text,'tiene'::text,'El anciano dijo que había tenido a los pájaros en esas jaulas durante años.'::text),
(337316,37480,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le vieil homme a dit qu''il ... les oiseaux dans ces cages pendant des années.'::text,'avait gardé'::text,'a gardé'::text,'garde'::text,'Le vieil homme a dit qu''il avait gardé les oiseaux dans ces cages pendant des années.'::text),
(337319,37480,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yaşlı adam kuşları yıllardır o kafeslerde ... söyledi.'::text,'tuttuğunu'::text,'tuttuğunu'::text,'tuttuğunu'::text,'Yaşlı adam kuşları yıllardır o kafeslerde tuttuğunu söyledi.'::text),
(337320,37480,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az idős férfi azt mondta, hogy évekig azokban a kalitkákban ... a madarakat.'::text,'tartotta'::text,'tartotta'::text,'tartja'::text,'Az idős férfi azt mondta, hogy évekig azokban a kalitkákban tartotta a madarakat.'::text),
(331221,36803,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Großeltern ... früher genau so einen Sessel.'::text,'hatten'::text,'hätten'::text,'waren gewohnt an'::text,'Ihre Großeltern hatten früher genau so einen Sessel.'::text),
(331225,36803,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її бабуся й дідусь ... крісло точнісінько як це.'::text,'колись мали'::text,'мали б'::text,'звикли мати'::text,'Її бабуся й дідусь колись мали крісло точнісінько як це.'::text),
(331224,36803,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sus abuelos ... un sillón igualito a este.'::text,'tenían'::text,'tendrían'::text,'estaban acostumbrados a tener'::text,'Sus abuelos tenían un sillón igualito a este.'::text),
(331223,36803,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ses grands-parents ... un fauteuil exactement comme celui-ci.'::text,'avaient'::text,'auraient'::text,'avaient l''habitude d''avoir'::text,'Ses grands-parents avaient un fauteuil exactement comme celui-ci.'::text),
(331226,36803,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Büyükannesiyle büyükbabasının eskiden tam da bunun gibi bir koltuğu ...'::text,'vardı'::text,'olurdu'::text,'olmaya alışkındı'::text,'Büyükannesiyle büyükbabasının eskiden tam da bunun gibi bir koltuğu vardı.'::text),
(331227,36803,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nagyszüleinek régen pont ilyen fotelje ...'::text,'volt'::text,'lett volna'::text,'szokott lenni'::text,'A nagyszüleinek régen pont ilyen fotelje volt.'::text),
(331230,36804,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie weigert sich absolut, diesen gelben Sessel auf dem Markt ...!'::text,'zurückzulassen'::text,'zurücklassen'::text,'zurücklassen'::text,'Sie weigert sich absolut, diesen gelben Sessel auf dem Markt zurückzulassen!'::text),
(331234,36804,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона категорично відмовляється ... те жовте крісло на ринку!'::text,'залишати'::text,'залишаючи'::text,'залишити'::text,'Вона категорично відмовляється залишати те жовте крісло на ринку!'::text),
(331233,36804,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Se niega rotundamente a ... ese sillón amarillo en el mercadillo!'::text,'dejar'::text,'dejando'::text,'dejar'::text,'¡Se niega rotundamente a dejar ese sillón amarillo en el mercadillo!'::text),
(331232,36804,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle refuse catégoriquement de ... ce fauteuil jaune au marché !'::text,'laisser'::text,'laissant'::text,'laisse'::text,'Elle refuse catégoriquement de laisser ce fauteuil jaune au marché !'::text),
(331235,36804,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O sarı koltuğu pazarda ... kesinlikle reddediyor!'::text,'bırakmayı'::text,'bırakmak'::text,'bırak'::text,'O sarı koltuğu pazarda bırakmayı kesinlikle reddediyor!'::text),
(331236,36804,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kategorikusan megtagadja, hogy ... azt a sárga fotelt a piacon!'::text,'otthagyja'::text,'otthagyva'::text,'otthagy'::text,'Kategorikusan megtagadja, hogy otthagyja azt a sárga fotelt a piacon!'::text),
(331239,36805,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieser Sessel zerquetscht die armen Platten total, ...'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Dieser Sessel zerquetscht die armen Platten total, oder?'::text),
(331243,36805,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Це крісло просто розчавлює бідні платівки, ...'::text,'так?'::text,'так?'::text,'так?'::text,'Це крісло просто розчавлює бідні платівки, так?'::text),
(331242,36805,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ese sillón está aplastando por completo los pobres vinilos, ¿...'::text,'verdad?'::text,'verdad?'::text,'verdad?'::text,'Ese sillón está aplastando por completo los pobres vinilos, ¿verdad?'::text),
(331241,36805,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce fauteuil est carrément en train d''écraser les pauvres vinyles, ...'::text,'pas vrai ?'::text,'pas vrai ?'::text,'pas vrai ?'::text,'Ce fauteuil est carrément en train d''écraser les pauvres vinyles, pas vrai ?'::text),
(331244,36805,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O koltuk zavallı plakları resmen eziyor, ...'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'O koltuk zavallı plakları resmen eziyor, değil mi?'::text),
(331245,36805,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az a fotel teljesen összenyomja a szegény lemezeket, ...'::text,'ugye?'::text,'ugye?'::text,'ugye?'::text,'Az a fotel teljesen összenyomja a szegény lemezeket, ugye?'::text),
(331257,36807,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, angeblich ... sie den ganzen Vormittag nach dem Sessel gesucht, bevor sie ihn fand.'::text,'hatte'::text,'hat'::text,'sucht'::text,'Mädel, angeblich hatte sie den ganzen Vormittag nach dem Sessel gesucht, bevor sie ihn fand.'::text),
(331261,36807,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, вона ... те крісло весь ранок, поки не знайшла.'::text,'шукала'::text,'шукає'::text,'шукає'::text,'Подруго, кажуть, вона шукала те крісло весь ранок, поки не знайшла.'::text),
(331260,36807,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer ... ese sillón toda la mañana antes de encontrarlo.'::text,'había estado buscando'::text,'ha estado buscando'::text,'está buscando'::text,'Tía, al parecer había estado buscando ese sillón toda la mañana antes de encontrarlo.'::text),
(331259,36807,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment elle ... ce fauteuil toute la matinée avant de le trouver.'::text,'avait cherché'::text,'a cherché'::text,'cherche'::text,'Meuf, apparemment elle avait cherché ce fauteuil toute la matinée avant de le trouver.'::text),
(331262,36807,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre o koltuğu bulmadan önce bütün sabah ...'::text,'aramıştı'::text,'aradı'::text,'arıyor'::text,'Kızım, duyduğuma göre o koltuğu bulmadan önce bütün sabah aramıştı.'::text),
(331263,36807,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag egész délelőtt ... azt a fotelt, mielőtt megtalálta.'::text,'kereste'::text,'keresi'::text,'keresi'::text,'Csajszi, állítólag egész délelőtt kereste azt a fotelt, mielőtt megtalálta.'::text),
(331266,36808,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, sie schwört, dass sie den Sessel bis Mittag nach Hause ...'::text,'gebracht haben wird'::text,'bringen wird'::text,'gerade bringen wird'::text,'Bestie, sie schwört, dass sie den Sessel bis Mittag nach Hause gebracht haben wird.'::text),
(331270,36808,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона клянеться, що ... те крісло додому до обіду.'::text,'відвезе'::text,'відвезе'::text,'везтиме'::text,'Подруго, вона клянеться, що відвезе те крісло додому до обіду.'::text),
(331269,36808,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, jura que para el mediodía ... ese sillón a casa.'::text,'habrá llevado'::text,'llevará'::text,'estará llevando'::text,'Amiga, jura que para el mediodía habrá llevado ese sillón a casa.'::text),
(331268,36808,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, elle jure qu''elle ... ce fauteuil chez elle d''ici midi.'::text,'aura ramené'::text,'ramènera'::text,'sera en train de ramener'::text,'Ma belle, elle jure qu''elle aura ramené ce fauteuil chez elle d''ici midi.'::text),
(331271,36808,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o koltuğu öğlene kadar eve ... yemin ediyor.'::text,'götürmüş olacağına'::text,'götüreceğine'::text,'götürüyor olacağına'::text,'Kanka, o koltuğu öğlene kadar eve götürmüş olacağına yemin ediyor.'::text),
(331272,36808,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, esküszik, hogy délre ... azt a fotelt.'::text,'hazaviszi'::text,'hazaviszi'::text,'épp viszi haza'::text,'Csajszi, esküszik, hogy délre hazaviszi azt a fotelt.'::text),
(331275,36809,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, ich hab gehört, dass sie bis Juni ein ganzes Jahr in diesem Sessel ...'::text,'gesessen haben wird'::text,'sitzen wird'::text,'sitzen wird'::text,'Hör mal, ich hab gehört, dass sie bis Juni ein ganzes Jahr in diesem Sessel gesessen haben wird.'::text),
(331279,36809,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що до червня вона ... в тому кріслі цілий рік.'::text,'сидітиме'::text,'сяде'::text,'сидітиме'::text,'Слухай, я чула, що до червня вона сидітиме в тому кріслі цілий рік.'::text),
(331278,36809,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me dijeron que para junio ... sentada en ese sillón un año entero.'::text,'habrá estado'::text,'estará'::text,'estará'::text,'Oye, me dijeron que para junio habrá estado sentada en ese sillón un año entero.'::text),
(331277,36809,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il paraît que d''ici juin, elle ... dans ce fauteuil pendant une année entière.'::text,'aura été assise'::text,'s''assiéra'::text,'sera assise'::text,'Écoute, il paraît que d''ici juin, elle aura été assise dans ce fauteuil pendant une année entière.'::text),
(331280,36809,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duydum ki haziran gelince o koltukta tam bir yıldır ...'::text,'oturuyor olacak'::text,'oturacak'::text,'oturuyor olacak'::text,'Dinle, duydum ki haziran gelince o koltukta tam bir yıldır oturuyor olacak.'::text),
(331281,36809,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy júniusra már egy egész éve ... abban a fotelben.'::text,'fog ülni'::text,'ül majd'::text,'fog ülni'::text,'Figyelj, azt hallottam, hogy júniusra már egy egész éve fog ülni abban a fotelben.'::text),
(331284,36810,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn du diesen Sessel nicht gefunden hättest, ... dieses Rad nicht so ikonisch ausgesehen, ehrlich.'::text,'hätte'::text,'wird'::text,'hat'::text,'Wenn du diesen Sessel nicht gefunden hättest, hätte dieses Rad nicht so ikonisch ausgesehen, ehrlich.'::text),
(331288,36810,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби ти не знайшла те крісло, цей велосипед ... так культово, чесно.'::text,'не виглядав би'::text,'не виглядатиме'::text,'не виглядав'::text,'Якби ти не знайшла те крісло, цей велосипед не виглядав би так культово, чесно.'::text),
(331287,36810,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no hubieras encontrado ese sillón, esta bici ... tan icónica, en serio.'::text,'no habría quedado'::text,'no quedará'::text,'no quedó'::text,'Si no hubieras encontrado ese sillón, esta bici no habría quedado tan icónica, en serio.'::text),
(331286,36810,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tu n''avais pas trouvé ce fauteuil, ce vélo ... aussi iconique, franchement.'::text,'n''aurait pas eu l''air'::text,'n''aura pas l''air'::text,'n''a pas eu l''air'::text,'Si tu n''avais pas trouvé ce fauteuil, ce vélo n''aurait pas eu l''air aussi iconique, franchement.'::text),
(331289,36810,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O koltuğu bulmasaydın, bu bisiklet bu kadar ikonik ..., açıkçası.'::text,'görünmezdi'::text,'görünmeyecek'::text,'görünmedi'::text,'O koltuğu bulmasaydın, bu bisiklet bu kadar ikonik görünmezdi, açıkçası.'::text),
(331290,36810,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem találtad volna meg azt a fotelt, ez a bicikli ... ilyen ikonikus, őszintén.'::text,'nem nézett volna ki'::text,'nem fog kinézni'::text,'nem nézett ki'::text,'Ha nem találtad volna meg azt a fotelt, ez a bicikli nem nézett volna ki ilyen ikonikus, őszintén.'::text),
(331293,36811,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn du den Sessel stehen gelassen hättest, ... du jetzt mit leeren Händen nach Hause. Respekt.'::text,'führst'::text,'wärst gefahren'::text,'fährst'::text,'Wenn du den Sessel stehen gelassen hättest, führst du jetzt mit leeren Händen nach Hause. Respekt.'::text),
(331297,36811,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби ти залишила те крісло, ти зараз ... додому з порожніми руками. Повага.'::text,'їхала б'::text,'поїхала б'::text,'поїдеш'::text,'Якби ти залишила те крісло, ти зараз їхала б додому з порожніми руками. Повага.'::text),
(331296,36811,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si hubieras dejado ese sillón, ahora mismo ... a casa con las manos vacías. Respeto.'::text,'irías'::text,'habrías ido'::text,'irás'::text,'Si hubieras dejado ese sillón, ahora mismo irías a casa con las manos vacías. Respeto.'::text),
(331295,36811,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tu avais laissé ce fauteuil, tu ... à la maison les mains vides en ce moment. Respect.'::text,'rentrerais'::text,'serais rentrée'::text,'rentreras'::text,'Si tu avais laissé ce fauteuil, tu rentrerais à la maison les mains vides en ce moment. Respect.'::text),
(331298,36811,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Helal olsun: o koltuğu bıraksaydın, şu an eve eli boş ...'::text,'dönüyor olurdun'::text,'dönmüş olurdun'::text,'döneceksin'::text,'Helal olsun: o koltuğu bıraksaydın, şu an eve eli boş dönüyor olurdun.'::text),
(331299,36811,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha otthagytad volna azt a fotelt, most üres kézzel ... haza. Respekt.'::text,'tekernél'::text,'tekertél volna'::text,'tekersz'::text,'Ha otthagytad volna azt a fotelt, most üres kézzel tekernél haza. Respekt.'::text),
(331302,36812,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Sessel soll vor etwa fünfzig Jahren ... worden sein.'::text,'hergestellt'::text,'herstellen'::text,'herstellend'::text,'Der Sessel soll vor etwa fünfzig Jahren hergestellt worden sein.'::text),
(331306,36812,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вважається, що крісло ... приблизно п''ятдесят років тому.'::text,'було зроблене'::text,'зробити'::text,'роблячи'::text,'Вважається, що крісло було зроблене приблизно п''ятдесят років тому.'::text),
(331305,36812,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se cree que el sillón ... hace unos cincuenta años.'::text,'fue fabricado'::text,'fabricar'::text,'fabricando'::text,'Se cree que el sillón fue fabricado hace unos cincuenta años.'::text),
(331304,36812,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On pense que le fauteuil ... il y a une cinquantaine d''années.'::text,'a été fabriqué'::text,'fabriquer'::text,'fabriquant'::text,'On pense que le fauteuil a été fabriqué il y a une cinquantaine d''années.'::text),
(331307,36812,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Koltuğun yaklaşık elli yıl önce ... düşünülüyor.'::text,'yapıldığı'::text,'yapmak'::text,'yaparak'::text,'Koltuğun yaklaşık elli yıl önce yapıldığı düşünülüyor.'::text),
(331308,36812,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy tartják, hogy a fotelt körülbelül ötven éve ...'::text,'készítették'::text,'készíteni'::text,'készítve'::text,'Úgy tartják, hogy a fotelt körülbelül ötven éve készítették.'::text),
(372225,41359,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, angeblich ... sie morgen um diese Zeit gerade auf schmerzenden Beinen die Treppe runter.'::text,'kriechen'::text,'kriechen'::text,'kriechen'::text,'Mädel, angeblich kriechen sie morgen um diese Zeit gerade auf schmerzenden Beinen die Treppe runter.'::text),
(372229,41359,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, завтра в цей час вони ... сходами вниз на хворих ногах.'::text,'повзтимуть'::text,'поповзуть'::text,'повзуть'::text,'Подруго, кажуть, завтра в цей час вони повзтимуть сходами вниз на хворих ногах.'::text),
(372228,41359,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer mañana a esta hora ... escaleras abajo con las piernas doloridas.'::text,'estarán arrastrándose'::text,'se arrastrarán'::text,'se arrastran'::text,'Tía, al parecer mañana a esta hora estarán arrastrándose escaleras abajo con las piernas doloridas.'::text),
(372227,41359,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment demain à cette heure-ci, ils ... dans l''escalier avec les jambes en compote.'::text,'seront en train de ramper'::text,'ramperont'::text,'rampent'::text,'Meuf, apparemment demain à cette heure-ci, ils seront en train de ramper dans l''escalier avec les jambes en compote.'::text),
(372230,41359,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre yarın bu saatte ağrıyan bacaklarla merdivenlerden aşağı ...'::text,'sürünüyor olacaklar'::text,'sürünecekler'::text,'sürünüyorlar'::text,'Kızım, duyduğuma göre yarın bu saatte ağrıyan bacaklarla merdivenlerden aşağı sürünüyor olacaklar.'::text),
(372231,41359,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag holnap ilyenkor fájó lábakkal ... le a lépcsőn.'::text,'fognak mászni'::text,'másznak majd'::text,'másznak'::text,'Csajszi, állítólag holnap ilyenkor fájó lábakkal fognak mászni le a lépcsőn.'::text),
(372243,41361,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn man nach dem Leg Day das Dehnen auslässt, ... sich die Treppen am nächsten Tag immer schmerzhaft an.'::text,'fühlen'::text,'fühlten'::text,'würden anfühlen'::text,'Wenn man nach dem Leg Day das Dehnen auslässt, fühlen sich die Treppen am nächsten Tag immer schmerzhaft an.'::text),
(372247,41361,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо люди пропускають розтяжку після дня ніг, сходи наступного дня завжди ... болісними.'::text,'здаються'::text,'здавалися'::text,'здавалися б'::text,'Якщо люди пропускають розтяжку після дня ніг, сходи наступного дня завжди здаються болісними.'::text),
(372246,41361,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la gente se salta los estiramientos después del día de pierna, las escaleras siempre ... dolorosas al día siguiente.'::text,'se sienten'::text,'se sintieron'::text,'se sentirían'::text,'Si la gente se salta los estiramientos después del día de pierna, las escaleras siempre se sienten dolorosas al día siguiente.'::text),
(372245,41361,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si on saute les étirements après le leg day, les escaliers ... toujours douloureux le lendemain.'::text,'semblent'::text,'semblaient'::text,'sembleraient'::text,'Si on saute les étirements après le leg day, les escaliers semblent toujours douloureux le lendemain.'::text),
(372248,41361,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İnsanlar bacak gününden sonra esnemeyi atlarsa, ertesi gün merdivenler hep ağrılı ...'::text,'gelir'::text,'geldi'::text,'gelirdi'::text,'İnsanlar bacak gününden sonra esnemeyi atlarsa, ertesi gün merdivenler hep ağrılı gelir.'::text),
(372249,41361,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az emberek lábnap után kihagyják a nyújtást, másnap a lépcső mindig fájdalmasnak ...'::text,'tűnik'::text,'tűnt'::text,'tűnne'::text,'Ha az emberek lábnap után kihagyják a nyújtást, másnap a lépcső mindig fájdalmasnak tűnik.'::text),
(372252,41362,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, dir macht es nichts aus, nach dem Gym einen schmerzhaften Heimweg ...'::text,'anzutreten'::text,'anzutreten'::text,'antreten'::text,'Ehrlich, dir macht es nichts aus, nach dem Gym einen schmerzhaften Heimweg anzutreten.'::text),
(372256,41362,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти зовсім не проти ... болісну дорогу додому після спортзалу.'::text,'долати'::text,'долати'::text,'долати'::text,'Чесно, ти зовсім не проти долати болісну дорогу додому після спортзалу.'::text),
(372255,41362,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En serio, no te importa ... un camino doloroso a casa después del gym.'::text,'afrontar'::text,'afrontar'::text,'afrontar'::text,'En serio, no te importa afrontar un camino doloroso a casa después del gym.'::text),
(372254,41362,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, ça ne te gêne pas ... un retour douloureux après la salle.'::text,'d''affronter'::text,'d''affronter'::text,'affronter'::text,'Franchement, ça ne te gêne pas d''affronter un retour douloureux après la salle.'::text),
(372257,41362,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, spordan sonra eve acılı bir yürüyüşe ... hiç dert etmiyorsun.'::text,'katlanmayı'::text,'katlanmak'::text,'katlan'::text,'Açıkçası, spordan sonra eve acılı bir yürüyüşe katlanmayı hiç dert etmiyorsun.'::text),
(372258,41362,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, egyáltalán nem zavar, hogy edzés után fájdalmas hazaúttal ...'::text,'nézel szembe'::text,'szembenézni'::text,'szembenéz'::text,'Őszintén, egyáltalán nem zavar, hogy edzés után fájdalmas hazaúttal nézel szembe.'::text),
(372261,41363,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt: Das Training war schmerzhaft, aber du bist trotzdem aus dem Gym gekommen, ...'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Respekt: Das Training war schmerzhaft, aber du bist trotzdem aus dem Gym gekommen, oder?'::text),
(372265,41363,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Повага: тренування було болісним, але ти все одно вийшов зі спортзалу, ...'::text,'так?'::text,'так?'::text,'так?'::text,'Повага: тренування було болісним, але ти все одно вийшов зі спортзалу, так?'::text),
(372264,41363,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respeto: el entreno fue doloroso, pero aun así saliste del gym, ¿...'::text,'verdad?'::text,'verdad?'::text,'verdad?'::text,'Respeto: el entreno fue doloroso, pero aun así saliste del gym, ¿verdad?'::text),
(372263,41363,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect : la séance était douloureuse, mais t''es quand même sorti de la salle, ...'::text,'pas vrai ?'::text,'pas vrai ?'::text,'pas vrai ?'::text,'Respect : la séance était douloureuse, mais t''es quand même sorti de la salle, pas vrai ?'::text),
(372266,41363,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Helal: antrenman acı vericiydi ama yine de spor salonundan çıktın, ...'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'Helal: antrenman acı vericiydi ama yine de spor salonundan çıktın, değil mi?'::text),
(372267,41363,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt: fájdalmas volt az edzés, de azért kijöttél a teremből, ...'::text,'ugye?'::text,'ugye?'::text,'ugye?'::text,'Respekt: fájdalmas volt az edzés, de azért kijöttél a teremből, ugye?'::text),
(372270,41364,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super gemacht, Team. Ihr Weg aus dem Gym ist schmerzhaft, und ...'::text,'seiner auch.'::text,'seiner auch.'::text,'seiner nicht.'::text,'Super gemacht, Team. Ihr Weg aus dem Gym ist schmerzhaft, und seiner auch.'::text),
(372274,41364,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудова робота, команда. Її вихід зі спортзалу болісний, і ...'::text,'його теж.'::text,'його теж.'::text,'його ні.'::text,'Чудова робота, команда. Її вихід зі спортзалу болісний, і його теж.'::text),
(372273,41364,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buen trabajo, equipo. Su salida del gym es dolorosa, y ...'::text,'la de él también.'::text,'la de él también.'::text,'la de él tampoco.'::text,'Buen trabajo, equipo. Su salida del gym es dolorosa, y la de él también.'::text),
(372272,41364,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bravo, l''équipe. Sa sortie de la salle est douloureuse, et ...'::text,'la sienne aussi.'::text,'la sienne aussi.'::text,'la sienne non plus.'::text,'Bravo, l''équipe. Sa sortie de la salle est douloureuse, et la sienne aussi.'::text),
(372275,41364,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika iş, ekip. Kızın spor salonundan çıkışı acılı, ...'::text,'oğlanınki de öyle.'::text,'oğlanınki de öyle.'::text,'oğlanınki de değil.'::text,'Harika iş, ekip. Kızın spor salonundan çıkışı acılı, oğlanınki de öyle.'::text),
(372276,41364,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szép munka, csapat. A lány fájdalmasan jön ki az edzőteremből, és ...'::text,'a srác is.'::text,'a srác is.'::text,'a srác sem.'::text,'Szép munka, csapat. A lány fájdalmasan jön ki az edzőteremből, és a srác is.'::text),
(372288,41366,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie sich nach dem Training gedehnt hätten, ... der Heimweg nicht so schmerzhaft gewesen.'::text,'wäre'::text,'wird'::text,'war'::text,'Wenn sie sich nach dem Training gedehnt hätten, wäre der Heimweg nicht so schmerzhaft gewesen.'::text),
(372292,41366,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вони розтяглися після тренування, дорога додому ... такою болісною.'::text,'не була б'::text,'не буде'::text,'не була'::text,'Якби вони розтяглися після тренування, дорога додому не була б такою болісною.'::text),
(372291,41366,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si se hubieran estirado después del entreno, el camino a casa ... tan doloroso.'::text,'no habría sido'::text,'no será'::text,'no fue'::text,'Si se hubieran estirado después del entreno, el camino a casa no habría sido tan doloroso.'::text),
(372290,41366,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''ils s''étaient étirés après la séance, le retour ... aussi douloureux.'::text,'n''aurait pas été'::text,'ne sera pas'::text,'n''a pas été'::text,'S''ils s''étaient étirés après la séance, le retour n''aurait pas été aussi douloureux.'::text),
(372293,41366,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antrenmandan sonra esneselerdi, eve dönüş bu kadar acılı ...'::text,'olmazdı'::text,'olmayacak'::text,'değildi'::text,'Antrenmandan sonra esneselerdi, eve dönüş bu kadar acılı olmazdı.'::text),
(372294,41366,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha edzés után nyújtottak volna, a hazaút ... ilyen fájdalmas.'::text,'nem lett volna'::text,'nem lesz'::text,'nem volt'::text,'Ha edzés után nyújtottak volna, a hazaút nem lett volna ilyen fájdalmas.'::text),
(372297,41367,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau auf der Bank beschwerte sich, nach dem Leg Day so schmerzende Beine zu ...'::text,'haben'::text,'haben'::text,'hatte'::text,'Die Frau auf der Bank beschwerte sich, nach dem Leg Day so schmerzende Beine zu haben.'::text),
(372301,41367,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка на лавці скаржилася, що ... такі хворі ноги після дня ніг.'::text,'має'::text,'мати'::text,'мала'::text,'Жінка на лавці скаржилася, що має такі хворі ноги після дня ніг.'::text),
(372300,41367,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer del banco se quejaba de ... las piernas tan doloridas después del día de pierna.'::text,'tener'::text,'tener'::text,'tenía'::text,'La mujer del banco se quejaba de tener las piernas tan doloridas después del día de pierna.'::text),
(372299,41367,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme sur le banc se plaignait ... des jambes aussi douloureuses après le leg day.'::text,'d''avoir'::text,'d''avoir'::text,'qu''elle avait'::text,'La femme sur le banc se plaignait d''avoir des jambes aussi douloureuses après le leg day.'::text),
(372302,41367,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Banktaki kadın bacak gününden sonra bacaklarının bu kadar ağrılı ... şikâyet etti.'::text,'olmasından'::text,'olmaktan'::text,'oldu'::text,'Banktaki kadın bacak gününden sonra bacaklarının bu kadar ağrılı olmasından şikâyet etti.'::text),
(372303,41367,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A padon ülő nő panaszkodott, hogy lábnap után ennyire ... a lába.'::text,'fáj'::text,'fájni'::text,'fájt'::text,'A padon ülő nő panaszkodott, hogy lábnap után ennyire fáj a lába.'::text),
(372306,41368,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... die Gruppe langsam die Straße hinunter, weil jeder Schritt wehtut.'::text,'geht'::text,'geht'::text,'ist gegangen'::text,'Gerade geht die Gruppe langsam die Straße hinunter, weil jeder Schritt wehtut.'::text),
(372310,41368,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Саме зараз група повільно ... вулицею, бо кожен крок болючий.'::text,'іде'::text,'ходить'::text,'пройшла'::text,'Саме зараз група повільно іде вулицею, бо кожен крок болючий.'::text),
(372309,41368,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo el grupo ... despacio calle abajo porque cada paso duele.'::text,'está caminando'::text,'camina'::text,'ha caminado'::text,'Ahora mismo el grupo está caminando despacio calle abajo porque cada paso duele.'::text),
(372308,41368,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, le groupe ... lentement dans la rue parce que chaque pas fait mal.'::text,'marche'::text,'marche'::text,'a marché'::text,'En ce moment, le groupe marche lentement dans la rue parce que chaque pas fait mal.'::text),
(372311,41368,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda grup caddede yavaşça ..., çünkü her adım acı veriyor.'::text,'yürüyor'::text,'yürür'::text,'yürüdü'::text,'Şu anda grup caddede yavaşça yürüyor, çünkü her adım acı veriyor.'::text),
(372312,41368,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Most épp lassan ... le az utcán a csoport, mert minden lépés fáj.'::text,'megy'::text,'megy'::text,'ment'::text,'Most épp lassan megy le az utcán a csoport, mert minden lépés fáj.'::text),
(372315,41369,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jeder Schritt tat weh! Der schlimmste Moment kam, als sie gerade aus der Tür des Gyms ...!'::text,'traten'::text,'getreten waren'::text,'getreten sind'::text,'Jeder Schritt tat weh! Der schlimmste Moment kam, als sie gerade aus der Tür des Gyms traten!'::text),
(372319,41369,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кожен крок був болісним! Найгірша мить настала, коли вони ... з дверей спортзалу!'::text,'виходили'::text,'вийшли'::text,'вийшли'::text,'Кожен крок був болісним! Найгірша мить настала, коли вони виходили з дверей спортзалу!'::text),
(372318,41369,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Cada paso dolía! ¡El peor momento llegó mientras ... por la puerta del gym!'::text,'salían'::text,'habían salido'::text,'han salido'::text,'¡Cada paso dolía! ¡El peor momento llegó mientras salían por la puerta del gym!'::text),
(372317,41369,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque pas faisait mal ! Le pire moment est arrivé pendant qu''ils ... par la porte de la salle !'::text,'sortaient'::text,'étaient sortis'::text,'sont sortis'::text,'Chaque pas faisait mal ! Le pire moment est arrivé pendant qu''ils sortaient par la porte de la salle !'::text),
(372320,41369,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her adım acı vericiydi! En kötü an, spor salonunun kapısından ... geldi!'::text,'çıkarlarken'::text,'çıkmışlarken'::text,'çıkmışken'::text,'Her adım acı vericiydi! En kötü an, spor salonunun kapısından çıkarlarken geldi!'::text),
(372321,41369,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden lépés fájt! A legrosszabb pillanat akkor jött, amikor ... az edzőterem ajtaján!'::text,'épp kiléptek'::text,'már kiléptek'::text,'kiléptek'::text,'Minden lépés fájt! A legrosszabb pillanat akkor jött, amikor épp kiléptek az edzőterem ajtaján!'::text),
(386598,42956,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, während du den Schlüssel ..., blieben die Türen zu wie ein Tresor.'::text,'drehtest'::text,'drehtest'::text,'gedreht hast'::text,'Ehrlich, während du den Schlüssel drehtest, blieben die Türen zu wie ein Tresor.'::text),
(386602,42956,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, поки ти ... ключ, ці двері стояли зачинені, як сейф.'::text,'повертала'::text,'повернула'::text,'повернула'::text,'Чесно, поки ти повертала ключ, ці двері стояли зачинені, як сейф.'::text),
(386601,42956,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En serio, mientras ... la llave, esas puertas seguían cerradas como una caja fuerte.'::text,'girabas'::text,'giraste'::text,'has girado'::text,'En serio, mientras girabas la llave, esas puertas seguían cerradas como una caja fuerte.'::text),
(386600,42956,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, pendant que tu ... la clé, ces portes sont restées fermées comme un coffre-fort.'::text,'tournais'::text,'as tourné'::text,'as tourné'::text,'Franchement, pendant que tu tournais la clé, ces portes sont restées fermées comme un coffre-fort.'::text),
(386603,42956,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, sen anahtarı ... o kapılar kasa gibi kapalı kaldı.'::text,'çevirirken'::text,'çevirdiğinde'::text,'çevirmişken'::text,'Açıkçası, sen anahtarı çevirirken o kapılar kasa gibi kapalı kaldı.'::text),
(386604,42956,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, amíg ... a kulcsot, azok az ajtók zárva maradtak, mint egy széf.'::text,'forgattad'::text,'elfordítottad'::text,'elfordítottad'::text,'Őszintén, amíg forgattad a kulcsot, azok az ajtók zárva maradtak, mint egy széf.'::text),
(386607,42957,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... seit Minuten den Schlüssel im Vorhängeschloss, aber die Türen sind immer noch zu.'::text,'dreht'::text,'dreht'::text,'dreht'::text,'Sie dreht seit Minuten den Schlüssel im Vorhängeschloss, aber die Türen sind immer noch zu.'::text),
(386611,42957,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона вже кілька хвилин ... ключ у навісному замку, але двері досі зачинені.'::text,'повертає'::text,'повертає'::text,'повертає'::text,'Вона вже кілька хвилин повертає ключ у навісному замку, але двері досі зачинені.'::text),
(386610,42957,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... la llave en el candado, pero las puertas siguen cerradas.'::text,'lleva minutos girando'::text,'está girando'::text,'gira'::text,'Ella lleva minutos girando la llave en el candado, pero las puertas siguen cerradas.'::text),
(386609,42957,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... la clé dans le cadenas depuis des minutes, mais les portes sont toujours fermées.'::text,'tourne'::text,'tourne'::text,'tourne'::text,'Elle tourne la clé dans le cadenas depuis des minutes, mais les portes sont toujours fermées.'::text),
(386612,42957,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dakikalardır asma kilitteki anahtarı ... ama kapılar hâlâ kapalı.'::text,'çeviriyor'::text,'çeviriyor'::text,'çevirir'::text,'Dakikalardır asma kilitteki anahtarı çeviriyor ama kapılar hâlâ kapalı.'::text),
(386613,42957,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már percek óta ... a kulcsot a lakatban, de az ajtók még mindig zárva vannak.'::text,'forgatja'::text,'forgatja'::text,'forgatja'::text,'Már percek óta forgatja a kulcsot a lakatban, de az ajtók még mindig zárva vannak.'::text),
(386616,42958,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie griff nach dem Vorhängeschloss, ... den Schlüssel und prüfte, ob die Türen zu waren.'::text,'drehte'::text,'drehte gerade'::text,'hat gedreht'::text,'Sie griff nach dem Vorhängeschloss, drehte den Schlüssel und prüfte, ob die Türen zu waren.'::text),
(386620,42958,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона взялася за навісний замок, ... ключ і перевірила, чи зачинені двері.'::text,'повернула'::text,'повертала'::text,'повернула'::text,'Вона взялася за навісний замок, повернула ключ і перевірила, чи зачинені двері.'::text),
(386619,42958,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Agarró el candado, ... la llave y comprobó que las puertas estaban cerradas.'::text,'giró'::text,'estaba girando'::text,'ha girado'::text,'Agarró el candado, giró la llave y comprobó que las puertas estaban cerradas.'::text),
(386618,42958,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a saisi le cadenas, ... la clé, puis a vérifié que les portes étaient fermées.'::text,'a tourné'::text,'tournait'::text,'a tourné'::text,'Elle a saisi le cadenas, a tourné la clé, puis a vérifié que les portes étaient fermées.'::text),
(386621,42958,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Asma kilidi tuttu, anahtarı ... ve kapıların kapalı olduğunu kontrol etti.'::text,'çevirdi'::text,'çeviriyordu'::text,'çevirmiş'::text,'Asma kilidi tuttu, anahtarı çevirdi ve kapıların kapalı olduğunu kontrol etti.'::text),
(386622,42958,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megfogta a lakatot, ... a kulcsot, és ellenőrizte, hogy zárva vannak-e az ajtók.'::text,'elfordította'::text,'forgatta'::text,'elfordította'::text,'Megfogta a lakatot, elfordította a kulcsot, és ellenőrizte, hogy zárva vannak-e az ajtók.'::text),
(386625,42959,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... heute zweimal das Vorhängeschloss geprüft, und die Türen sind immer noch zu.'::text,'hat'::text,'hat'::text,'prüft'::text,'Sie hat heute zweimal das Vorhängeschloss geprüft, und die Türen sind immer noch zu.'::text),
(386629,42959,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сьогодні вона двічі ... навісний замок, а двері досі зачинені.'::text,'перевірила'::text,'перевіряє'::text,'перевіряє'::text,'Сьогодні вона двічі перевірила навісний замок, а двері досі зачинені.'::text),
(386628,42959,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hoy ... el candado dos veces y las puertas siguen cerradas.'::text,'ha revisado'::text,'ha estado revisando'::text,'está revisando'::text,'Hoy ha revisado el candado dos veces y las puertas siguen cerradas.'::text),
(386627,42959,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... le cadenas deux fois aujourd''hui, et les portes sont toujours fermées.'::text,'a vérifié'::text,'a vérifié'::text,'vérifie'::text,'Elle a vérifié le cadenas deux fois aujourd''hui, et les portes sont toujours fermées.'::text),
(386630,42959,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bugün asma kilidi iki kez ... ve kapılar hâlâ kapalı.'::text,'kontrol etti'::text,'kontrol ediyor'::text,'kontrol ediyor'::text,'Bugün asma kilidi iki kez kontrol etti ve kapılar hâlâ kapalı.'::text),
(386631,42959,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma kétszer ... a lakatot, és az ajtók még mindig zárva vannak.'::text,'ellenőrizte'::text,'ellenőrizgette'::text,'ellenőrzi'::text,'Ma kétszer ellenőrizte a lakatot, és az ajtók még mindig zárva vannak.'::text),
(386634,42960,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, angeblich ... sie die Türen lange bevor jemand kam mit der Kette verschlossen.'::text,'hatte'::text,'hat'::text,'verschließt'::text,'Hör mal, angeblich hatte sie die Türen lange bevor jemand kam mit der Kette verschlossen.'::text),
(386638,42960,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, вона ... двері на ланцюг задовго до того, як хтось прийшов.'::text,'замкнула'::text,'замкнула'::text,'замикає'::text,'Слухай, кажуть, вона замкнула двері на ланцюг задовго до того, як хтось прийшов.'::text),
(386637,42960,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer ... las puertas con cadena mucho antes de que llegara nadie.'::text,'había cerrado'::text,'ha cerrado'::text,'cierra'::text,'Oye, al parecer había cerrado las puertas con cadena mucho antes de que llegara nadie.'::text),
(386636,42960,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment elle ... les portes avec la chaîne bien avant que quelqu''un arrive.'::text,'avait fermé'::text,'a fermé'::text,'ferme'::text,'Écoute, apparemment elle avait fermé les portes avec la chaîne bien avant que quelqu''un arrive.'::text),
(386639,42960,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duyduğuma göre kimse gelmeden çok önce kapıları zincirle ...'::text,'kilitlemişti'::text,'kilitledi'::text,'kilitliyor'::text,'Dinle, duyduğuma göre kimse gelmeden çok önce kapıları zincirle kilitlemişti.'::text),
(386640,42960,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag már jóval azelőtt ... az ajtókat, hogy bárki odaért volna.'::text,'leláncolta'::text,'leláncolta'::text,'leláncolja'::text,'Figyelj, állítólag már jóval azelőtt leláncolta az ajtókat, hogy bárki odaért volna.'::text),
(386643,42961,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie das Vorhängeschloss richtig abschließt, ... die Türen die ganze Nacht zu.'::text,'bleiben'::text,'blieben'::text,'blieben'::text,'Wenn sie das Vorhängeschloss richtig abschließt, bleiben die Türen die ganze Nacht zu.'::text),
(386647,42961,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вона як слід замкне навісний замок, двері ... зачиненими всю ніч.'::text,'залишаться'::text,'залишилися б'::text,'залишилися'::text,'Якщо вона як слід замкне навісний замок, двері залишаться зачиненими всю ніч.'::text),
(386646,42961,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si cierra bien el candado, las puertas ... cerradas toda la noche.'::text,'seguirán'::text,'seguirían'::text,'siguieron'::text,'Si cierra bien el candado, las puertas seguirán cerradas toda la noche.'::text),
(386645,42961,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle ferme bien le cadenas, les portes ... fermées toute la nuit.'::text,'resteront'::text,'resteraient'::text,'sont restées'::text,'Si elle ferme bien le cadenas, les portes resteront fermées toute la nuit.'::text),
(386648,42961,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Asma kilidi düzgünce kilitlerse, kapılar bütün gece kapalı ...'::text,'kalacak'::text,'kalırdı'::text,'kaldı'::text,'Asma kilidi düzgünce kilitlerse, kapılar bütün gece kapalı kalacak.'::text),
(386649,42961,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha rendesen bezárja a lakatot, az ajtók egész éjjel zárva ...'::text,'maradnak'::text,'maradnának'::text,'maradtak'::text,'Ha rendesen bezárja a lakatot, az ajtók egész éjjel zárva maradnak.'::text),
(386652,42962,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, wenn ich so viele Schlüssel ..., würde keine Tür zu bleiben, echt jetzt.'::text,'hätte'::text,'habe'::text,'haben würde'::text,'Nee, wenn ich so viele Schlüssel hätte, würde keine Tür zu bleiben, echt jetzt.'::text),
(386656,42962,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, якби в мене ... стільки ключів, жодні двері не лишилися б зачиненими, реально.'::text,'було'::text,'є'::text,'було б'::text,'Не, якби в мене було стільки ключів, жодні двері не лишилися б зачиненими, реально.'::text),
(386655,42962,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, si yo ... tantas llaves, ninguna puerta se quedaría cerrada, de verdad.'::text,'tuviera'::text,'tengo'::text,'tendría'::text,'Qué va, si yo tuviera tantas llaves, ninguna puerta se quedaría cerrada, de verdad.'::text),
(386654,42962,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan, si ... autant de clés, aucune porte ne resterait fermée, sérieux.'::text,'j''avais'::text,'j''ai'::text,'j''aurais'::text,'Nan, si j''avais autant de clés, aucune porte ne resterait fermée, sérieux.'::text),
(386657,42962,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok, bende o kadar anahtar ..., hiçbir kapı kapalı kalmazdı, cidden.'::text,'olsaydı'::text,'var'::text,'olurdu'::text,'Yok, bende o kadar anahtar olsaydı, hiçbir kapı kapalı kalmazdı, cidden.'::text),
(386658,42962,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, ha nekem ... ennyi kulcsom, egy ajtó se maradna zárva, komolyan.'::text,'lenne'::text,'van'::text,'lenne'::text,'Á, ha nekem lenne ennyi kulcsom, egy ajtó se maradna zárva, komolyan.'::text),
(386670,42964,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Laut Sicherheitsprotokoll ... die Türen von einem 2-Kilo-Vorhängeschloss verschlossen gehalten.'::text,'werden'::text,'halten'::text,'haltend'::text,'Laut Sicherheitsprotokoll werden die Türen von einem 2-Kilo-Vorhängeschloss verschlossen gehalten.'::text),
(386674,42964,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Згідно з протоколом безпеки, двері ... зачиненими 2-кілограмовим навісним замком.'::text,'утримуються'::text,'утримують'::text,'утримуючи'::text,'Згідно з протоколом безпеки, двері утримуються зачиненими 2-кілограмовим навісним замком.'::text),
(386673,42964,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Según el protocolo de seguridad, las puertas ... cerradas con un candado de 2 kilos.'::text,'son mantenidas'::text,'mantienen'::text,'manteniendo'::text,'Según el protocolo de seguridad, las puertas son mantenidas cerradas con un candado de 2 kilos.'::text),
(386672,42964,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Conformément au protocole de sécurité, les portes ... fermées par un cadenas de 2 kilos.'::text,'sont maintenues'::text,'maintiennent'::text,'maintenant'::text,'Conformément au protocole de sécurité, les portes sont maintenues fermées par un cadenas de 2 kilos.'::text),
(386675,42964,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güvenlik protokolü gereği kapılar 2 kiloluk bir asma kilitle kapalı ...'::text,'tutuluyor'::text,'tutuyor'::text,'tutarak'::text,'Güvenlik protokolü gereği kapılar 2 kiloluk bir asma kilitle kapalı tutuluyor.'::text),
(386676,42964,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A biztonsági protokoll szerint az ajtókat egy 2 kilós lakat ... zárva.'::text,'tartja'::text,'tartják'::text,'tartva'::text,'A biztonsági protokoll szerint az ajtókat egy 2 kilós lakat tartja zárva.'::text),
(386679,42965,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Türen sind zu und mit einer Kette gesichert, also ... das Gebäude heute geschlossen sein.'::text,'muss'::text,'kann nicht'::text,'darf nicht'::text,'Die Türen sind zu und mit einer Kette gesichert, also muss das Gebäude heute geschlossen sein.'::text),
(386683,42965,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Двері зачинені й на ланцюгу, тож будівля ... бути зачиненою на сьогодні.'::text,'має'::text,'не може'::text,'не повинна'::text,'Двері зачинені й на ланцюгу, тож будівля має бути зачиненою на сьогодні.'::text),
(386682,42965,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las puertas están cerradas y encadenadas, así que el edificio ... estar cerrado por hoy.'::text,'debe de'::text,'no puede'::text,'no debe'::text,'Las puertas están cerradas y encadenadas, así que el edificio debe de estar cerrado por hoy.'::text),
(386681,42965,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les portes sont fermées et enchaînées, donc le bâtiment ... être fermé pour la journée.'::text,'doit'::text,'ne peut pas'::text,'ne doit pas'::text,'Les portes sont fermées et enchaînées, donc le bâtiment doit être fermé pour la journée.'::text),
(386684,42965,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kapılar kapalı ve zincirli, yani bina bugünlük kapalı ...'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Kapılar kapalı ve zincirli, yani bina bugünlük kapalı olmalı.'::text),
(386685,42965,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ajtók zárva vannak és le vannak láncolva, szóval az épület mára ... bezárt.'::text,'biztosan'::text,'nem lehet, hogy'::text,'nem szabad, hogy'::text,'Az ajtók zárva vannak és le vannak láncolva, szóval az épület mára biztosan bezárt.'::text),
(386688,42966,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wie beobachtet, sind die Türen, ... geschlossen bleiben, mit einem eisernen Vorhängeschloss gesichert.'::text,'die'::text,'die'::text,'deren'::text,'Wie beobachtet, sind die Türen, die geschlossen bleiben, mit einem eisernen Vorhängeschloss gesichert.'::text),
(386692,42966,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Як спостерігалося, двері, ... залишаються зачиненими, захищені залізним навісним замком.'::text,'які'::text,'хто'::text,'чиї'::text,'Як спостерігалося, двері, які залишаються зачиненими, захищені залізним навісним замком.'::text),
(386691,42966,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Según lo observado, las puertas ... permanecen cerradas están aseguradas con un candado de hierro.'::text,'que'::text,'quienes'::text,'cuyas'::text,'Según lo observado, las puertas que permanecen cerradas están aseguradas con un candado de hierro.'::text),
(386690,42966,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Comme observé, les portes ... restent fermées sont sécurisées par un cadenas en fer.'::text,'qui'::text,'qui'::text,'dont'::text,'Comme observé, les portes qui restent fermées sont sécurisées par un cadenas en fer.'::text),
(386693,42966,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gözlemlendiği üzere, kapalı ... kapılar demir bir asma kilitle emniyete alınmış.'::text,'kalan'::text,'kalan'::text,'kalanların'::text,'Gözlemlendiği üzere, kapalı kalan kapılar demir bir asma kilitle emniyete alınmış.'::text),
(386694,42966,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A megfigyelés szerint azok az ajtók, ... zárva maradnak, egy vaslakattal vannak biztosítva.'::text,'amelyek'::text,'akik'::text,'amelyeknek'::text,'A megfigyelés szerint azok az ajtók, amelyek zárva maradnak, egy vaslakattal vannak biztosítva.'::text),
(366330,40704,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... seit zwei Jahren Wahlkampf für diese Wahl, und jetzt hat er sie verloren.'::text,'macht'::text,'macht'::text,'macht'::text,'Er macht seit zwei Jahren Wahlkampf für diese Wahl, und jetzt hat er sie verloren.'::text),
(366334,40704,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... до цих виборів уже два роки, а тепер програв їх.'::text,'веде кампанію'::text,'веде кампанію'::text,'веде кампанію'::text,'Він веде кампанію до цих виборів уже два роки, а тепер програв їх.'::text),
(366333,40704,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... para estas elecciones desde hace dos años, y ahora las ha perdido.'::text,'hace campaña'::text,'está haciendo campaña'::text,'hace campaña'::text,'Él hace campaña para estas elecciones desde hace dos años, y ahora las ha perdido.'::text),
(366332,40704,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... pour cette élection depuis deux ans, et maintenant il l''a perdue.'::text,'fait campagne'::text,'fait campagne'::text,'fait campagne'::text,'Il fait campagne pour cette élection depuis deux ans, et maintenant il l''a perdue.'::text),
(366335,40704,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki yıldır bu seçim için kampanya ... ve şimdi kaybetti.'::text,'yürütüyor'::text,'yürütüyor'::text,'yürütür'::text,'İki yıldır bu seçim için kampanya yürütüyor ve şimdi kaybetti.'::text),
(366336,40704,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Két éve ... erre a választásra, és most elvesztette.'::text,'kampányol'::text,'kampányol'::text,'kampányol'::text,'Két éve kampányol erre a választásra, és most elvesztette.'::text),
(366339,40705,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, in der Sekunde, als er sah, dass er verloren hat, ... die Gäste raus, kein Witz.'::text,'gingen'::text,'gingen gerade'::text,'sind gegangen'::text,'Bro, in der Sekunde, als er sah, dass er verloren hat, gingen die Gäste raus, kein Witz.'::text),
(366343,40705,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, щойно він побачив, що програв, гості ..., без жартів.'::text,'пішли'::text,'йшли'::text,'пішли'::text,'Бро, щойно він побачив, що програв, гості пішли, без жартів.'::text),
(366342,40705,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, en cuanto vio que había perdido, los invitados ..., sin mentir.'::text,'se fueron'::text,'se estaban yendo'::text,'se han ido'::text,'Bro, en cuanto vio que había perdido, los invitados se fueron, sin mentir.'::text),
(366341,40705,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, dès qu''il a vu qu''il avait perdu, les invités ..., sans mentir.'::text,'sont partis'::text,'partaient'::text,'sont partis'::text,'Frérot, dès qu''il a vu qu''il avait perdu, les invités sont partis, sans mentir.'::text),
(366344,40705,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, kaybettiğini gördüğü an misafirler ..., yemin ederim.'::text,'çıkıp gitti'::text,'çıkıp gidiyordu'::text,'çıkıp gitmiş'::text,'Kanka, kaybettiğini gördüğü an misafirler çıkıp gitti, yemin ederim.'::text),
(366345,40705,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, abban a pillanatban, hogy látta, hogy vesztett, a vendégek ..., komolyan.'::text,'kisétáltak'::text,'épp kisétáltak'::text,'kisétáltak'::text,'Tesó, abban a pillanatban, hogy látta, hogy vesztett, a vendégek kisétáltak, komolyan.'::text),
(366348,40706,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Typ wird ''ne Weile traurig sein, er ... jetzt schon drei Wahlen in Folge verloren.'::text,'hat'::text,'hat'::text,'hat'::text,'Der Typ wird ''ne Weile traurig sein, er hat jetzt schon drei Wahlen in Folge verloren.'::text),
(366352,40706,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак ще довго сумуватиме, він уже ... три вибори поспіль.'::text,'програв'::text,'програє'::text,'програв'::text,'Чувак ще довго сумуватиме, він уже програв три вибори поспіль.'::text),
(366351,40706,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El tío va a estar triste un rato, ya ... tres elecciones seguidas.'::text,'ha perdido'::text,'ha estado perdiendo'::text,'perdió'::text,'El tío va a estar triste un rato, ya ha perdido tres elecciones seguidas.'::text),
(366350,40706,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le mec va être triste un moment, il ... trois élections d''affilée maintenant.'::text,'a perdu'::text,'a perdu'::text,'a perdu'::text,'Le mec va être triste un moment, il a perdu trois élections d''affilée maintenant.'::text),
(366353,40706,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam bir süre üzgün olacak, üst üste üç seçimi ...'::text,'kaybetti'::text,'kaybediyor'::text,'kaybetti'::text,'Adam bir süre üzgün olacak, üst üste üç seçimi kaybetti.'::text),
(366354,40706,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csávó egy darabig szomorú lesz, már sorban három választást ...'::text,'vesztett el'::text,'veszít'::text,'vesztett el'::text,'A csávó egy darabig szomorú lesz, már sorban három választást vesztett el.'::text),
(366357,40707,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis das Ergebnisdiagramm um 21 Uhr erschien, ... er alle seine Stakeholder verloren.'::text,'hatte'::text,'hat'::text,'verlor'::text,'Bis das Ergebnisdiagramm um 21 Uhr erschien, hatte er alle seine Stakeholder verloren.'::text),
(366361,40707,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки о 21:00 з''явився графік результатів, він уже ... всіх своїх стейкхолдерів.'::text,'втратив'::text,'втратив'::text,'втрачав'::text,'Поки о 21:00 з''явився графік результатів, він уже втратив всіх своїх стейкхолдерів.'::text),
(366360,40707,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando apareció el gráfico de resultados a las 21:00, ya ... a todos sus stakeholders.'::text,'había perdido'::text,'ha perdido'::text,'estaba perdiendo'::text,'Para cuando apareció el gráfico de resultados a las 21:00, ya había perdido a todos sus stakeholders.'::text),
(366359,40707,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand le graphique des résultats est apparu à 21 h, il ... toutes ses parties prenantes.'::text,'avait perdu'::text,'a perdu'::text,'perdait'::text,'Quand le graphique des résultats est apparu à 21 h, il avait perdu toutes ses parties prenantes.'::text),
(366362,40707,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saat 21:00''de sonuç grafiği çıktığında, tüm paydaşlarını çoktan ...'::text,'kaybetmişti'::text,'kaybetti'::text,'kaybediyordu'::text,'Saat 21:00''de sonuç grafiği çıktığında, tüm paydaşlarını çoktan kaybetmişti.'::text),
(366363,40707,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire este 9-kor megjelent az eredménygrafikon, már az összes stakeholderét ...'::text,'elvesztette'::text,'elvesztette'::text,'vesztette'::text,'Mire este 9-kor megjelent az eredménygrafikon, már az összes stakeholderét elvesztette.'::text),
(366366,40708,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er weniger Stimmen bekommt, ... er die Wahl, weil weniger nicht mehr ist.'::text,'verliert'::text,'verlöre'::text,'verlor'::text,'Wenn er weniger Stimmen bekommt, verliert er die Wahl, weil weniger nicht mehr ist.'::text),
(366370,40708,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він отримає менше голосів, він ... вибори, бо менше — це не більше.'::text,'програє'::text,'програв би'::text,'програв'::text,'Якщо він отримає менше голосів, він програє вибори, бо менше — це не більше.'::text),
(366369,40708,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si consigue menos votos, ... las elecciones, porque menos no es más.'::text,'perderá'::text,'perdería'::text,'perdió'::text,'Si consigue menos votos, perderá las elecciones, porque menos no es más.'::text),
(366368,40708,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il obtient moins de voix, il ... l''élection, parce que moins, ce n''est pas plus.'::text,'perdra'::text,'perdrait'::text,'a perdu'::text,'S''il obtient moins de voix, il perdra l''élection, parce que moins, ce n''est pas plus.'::text),
(366371,40708,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Daha az oy alırsa seçimi ..., çünkü daha az, daha fazla değildir.'::text,'kaybedecek'::text,'kaybederdi'::text,'kaybetti'::text,'Daha az oy alırsa seçimi kaybedecek, çünkü daha az, daha fazla değildir.'::text),
(366372,40708,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha kevesebb szavazatot kap, ... a választást, mert a kevesebb nem több.'::text,'elveszíti'::text,'elveszítené'::text,'elveszítette'::text,'Ha kevesebb szavazatot kap, elveszíti a választást, mert a kevesebb nem több.'::text),
(366375,40709,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Diagramm zeigt, dass der Kandidat nicht verlieren würde, wenn er mehr Stimmen ...'::text,'bekäme'::text,'bekommt'::text,'bekommen würde'::text,'Das Diagramm zeigt, dass der Kandidat nicht verlieren würde, wenn er mehr Stimmen bekäme.'::text),
(366379,40709,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Графік показує, що якби кандидат ... більше голосів, він би не програв.'::text,'отримав'::text,'отримує'::text,'отримав би'::text,'Графік показує, що якби кандидат отримав більше голосів, він би не програв.'::text),
(366378,40709,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El gráfico indica que, si el candidato ... más votos, no perdería.'::text,'recibiera'::text,'recibe'::text,'recibiría'::text,'El gráfico indica que, si el candidato recibiera más votos, no perdería.'::text),
(366377,40709,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le graphique indique que si le candidat ... plus de voix, il ne perdrait pas.'::text,'recevait'::text,'reçoit'::text,'recevrait'::text,'Le graphique indique que si le candidat recevait plus de voix, il ne perdrait pas.'::text),
(366380,40709,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Grafik, aday daha fazla oy ... kaybetmeyeceğini gösteriyor.'::text,'alsaydı'::text,'alıyor'::text,'alırdı'::text,'Grafik, aday daha fazla oy alsaydı kaybetmeyeceğini gösteriyor.'::text),
(366381,40709,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A grafikon azt mutatja, hogy ha a jelölt több szavazatot ..., nem veszítene.'::text,'kapna'::text,'kap'::text,'kapna'::text,'A grafikon azt mutatja, hogy ha a jelölt több szavazatot kapna, nem veszítene.'::text),
(366384,40710,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wünscht, er ... diese demütigende Wahl nicht verloren! Totale Katastrophe!'::text,'hätte'::text,'würde'::text,'wird'::text,'Er wünscht, er hätte diese demütigende Wahl nicht verloren! Totale Katastrophe!'::text),
(366388,40710,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Як же він шкодує, що ... ці принизливі вибори! Повна катастрофа!'::text,'програв'::text,'програвав'::text,'програє'::text,'Як же він шкодує, що програв ці принизливі вибори! Повна катастрофа!'::text),
(366387,40710,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Cómo desearía no ... estas humillantes elecciones! ¡Desastre total!'::text,'haber perdido'::text,'perder'::text,'perder'::text,'¡Cómo desearía no haber perdido estas humillantes elecciones! ¡Desastre total!'::text),
(366386,40710,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il aimerait ne pas ... cette élection humiliante ! Un désastre total !'::text,'avoir perdu'::text,'perdre'::text,'perdre'::text,'Il aimerait ne pas avoir perdu cette élection humiliante ! Un désastre total !'::text),
(366389,40710,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke bu aşağılayıcı seçimi ... diye düşünüyor! Tam bir felaket!'::text,'kaybetmeseydi'::text,'kaybetmese'::text,'kaybetmeyecek'::text,'Keşke bu aşağılayıcı seçimi kaybetmeseydi diye düşünüyor! Tam bir felaket!'::text),
(366390,40710,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt kívánja, bárcsak ne ... ezt a megalázó választást! Totális katasztrófa!'::text,'vesztette volna el'::text,'vesztené el'::text,'fogja elveszíteni'::text,'Azt kívánja, bárcsak ne vesztette volna el ezt a megalázó választást! Totális katasztrófa!'::text),
(366393,40711,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Saal, ... die Gäste eine Stunde zuvor gejubelt hatten, verstummte, als er verlor. Katastrophe!'::text,'in dem'::text,'der'::text,'dessen'::text,'Der Saal, in dem die Gäste eine Stunde zuvor gejubelt hatten, verstummte, als er verlor. Katastrophe!'::text),
(366397,40711,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зала, ... гості годину тому раділи, затихла, коли він програв. Катастрофа!'::text,'де'::text,'яка'::text,'чия'::text,'Зала, де гості годину тому раділи, затихла, коли він програв. Катастрофа!'::text),
(366396,40711,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La sala, ... los invitados habían vitoreado una hora antes, enmudeció cuando perdió. ¡Desastre!'::text,'donde'::text,'que'::text,'cuya'::text,'La sala, donde los invitados habían vitoreado una hora antes, enmudeció cuando perdió. ¡Desastre!'::text),
(366395,40711,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La salle, ... les invités avaient applaudi une heure plus tôt, est devenue silencieuse quand il a perdu. Désastre !'::text,'où'::text,'qui'::text,'dont'::text,'La salle, où les invités avaient applaudi une heure plus tôt, est devenue silencieuse quand il a perdu. Désastre !'::text),
(366398,40711,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Misafirlerin bir saat önce tezahürat ... salon, o kaybedince sessizliğe gömüldü. Felaket!'::text,'yaptığı'::text,'yapan'::text,'yaptığının'::text,'Misafirlerin bir saat önce tezahürat yaptığı salon, o kaybedince sessizliğe gömüldü. Felaket!'::text),
(366399,40711,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A terem, ... a vendégek egy órával korábban még ujjongtak, elnémult, amikor vesztett. Katasztrófa!'::text,'ahol'::text,'amely'::text,'amelynek'::text,'A terem, ahol a vendégek egy órával korábban még ujjongtak, elnémult, amikor vesztett. Katasztrófa!'::text),
(366402,40712,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... all der Luftballons und Banner hat er die Wahl komplett verloren! Aus!'::text,'Trotz'::text,'Obwohl'::text,'Wegen'::text,'Trotz all der Luftballons und Banner hat er die Wahl komplett verloren! Aus!'::text),
(366406,40712,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... усі кульки й банери, він повністю програв вибори! Кінець!'::text,'Попри'::text,'Хоча'::text,'Через'::text,'Попри усі кульки й банери, він повністю програв вибори! Кінець!'::text),
(366405,40712,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... todos los globos y pancartas, perdió las elecciones por completo! ¡Fin!'::text,'A pesar de'::text,'Aunque'::text,'Por'::text,'¡A pesar de todos los globos y pancartas, perdió las elecciones por completo! ¡Fin!'::text),
(366404,40712,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... tous les ballons et banderoles, il a complètement perdu l''élection ! Fin !'::text,'Malgré'::text,'Bien que'::text,'À cause de'::text,'Malgré tous les ballons et banderoles, il a complètement perdu l''élection ! Fin !'::text),
(366407,40712,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tüm balonlara ve pankartlara ..., seçimi tamamen kaybetti! Son!'::text,'rağmen'::text,'olsa da'::text,'yüzünden'::text,'Tüm balonlara ve pankartlara rağmen, seçimi tamamen kaybetti! Son!'::text),
(366408,40712,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az összes lufi és transzparens ..., teljesen elvesztette a választást! Vége!'::text,'ellenére'::text,'bár'::text,'miatt'::text,'Az összes lufi és transzparens ellenére, teljesen elvesztette a választást! Vége!'::text),
(366438,40716,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... gerade in ihren Klamotten, als sie merkte, dass sie ihren Pass verloren hatte.'::text,'wühlte'::text,'wühlte'::text,'hat gewühlt'::text,'Sie wühlte gerade in ihren Klamotten, als sie merkte, dass sie ihren Pass verloren hatte.'::text),
(366442,40716,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... у своєму одязі, коли зрозуміла, що загубила паспорт.'::text,'порпалася'::text,'перерила'::text,'перерила'::text,'Вона порпалася у своєму одязі, коли зрозуміла, що загубила паспорт.'::text),
(366441,40716,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... entre su ropa cuando se dio cuenta de que había perdido el pasaporte.'::text,'estaba rebuscando'::text,'rebuscó'::text,'ha rebuscado'::text,'Ella estaba rebuscando entre su ropa cuando se dio cuenta de que había perdido el pasaporte.'::text),
(366440,40716,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... dans ses vêtements quand elle a réalisé qu''elle avait perdu son passeport.'::text,'fouillait'::text,'a fouillé'::text,'a fouillé'::text,'Elle fouillait dans ses vêtements quand elle a réalisé qu''elle avait perdu son passeport.'::text),
(366443,40716,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pasaportunu kaybettiğini fark ettiğinde kıyafetlerini ...'::text,'karıştırıyordu'::text,'karıştırdı'::text,'karıştırmış'::text,'Pasaportunu kaybettiğini fark ettiğinde kıyafetlerini karıştırıyordu.'::text),
(366444,40716,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp a ruhái között ..., amikor rájött, hogy elvesztette az útlevelét.'::text,'turkált'::text,'turkált'::text,'turkált'::text,'Épp a ruhái között turkált, amikor rájött, hogy elvesztette az útlevelét.'::text),
(366447,40717,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie ... seit einer Stunde in dem Rucksack, weil sie ihre Schlüssel verloren hat.'::text,'wühlt'::text,'wühlt'::text,'wühlt'::text,'Bro, sie wühlt seit einer Stunde in dem Rucksack, weil sie ihre Schlüssel verloren hat.'::text),
(366451,40717,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона вже годину ... в тому рюкзаку, бо загубила ключі.'::text,'порпається'::text,'порпається'::text,'порпається'::text,'Бро, вона вже годину порпається в тому рюкзаку, бо загубила ключі.'::text),
(366450,40717,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ella ... en esa mochila desde hace una hora porque perdió las llaves.'::text,'rebusca'::text,'está rebuscando'::text,'rebusca'::text,'Bro, ella rebusca en esa mochila desde hace una hora porque perdió las llaves.'::text),
(366449,40717,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elle ... dans ce sac à dos depuis une heure parce qu''elle a perdu ses clés.'::text,'fouille'::text,'fouille'::text,'fouille'::text,'Frérot, elle fouille dans ce sac à dos depuis une heure parce qu''elle a perdu ses clés.'::text),
(366452,40717,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, anahtarlarını kaybettiği için bir saattir o sırt çantasını ...'::text,'karıştırıyor'::text,'karıştırıyor'::text,'karıştırır'::text,'Kanka, anahtarlarını kaybettiği için bir saattir o sırt çantasını karıştırıyor.'::text),
(366453,40717,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, egy órája ... abban a hátizsákban, mert elhagyta a kulcsait.'::text,'turkál'::text,'turkál'::text,'turkál'::text,'Tesó, egy órája turkál abban a hátizsákban, mert elhagyta a kulcsait.'::text),
(366465,40719,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... ihren Pass verloren, also ist ihr Pass jetzt verloren.'::text,'hat'::text,'ist'::text,'wurde'::text,'Sie hat ihren Pass verloren, also ist ihr Pass jetzt verloren.'::text),
(366469,40719,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... паспорт, тож тепер її паспорт загублений.'::text,'загубила'::text,'була загублена'::text,'була загублена'::text,'Вона загубила паспорт, тож тепер її паспорт загублений.'::text),
(366468,40719,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... su pasaporte, así que ahora su pasaporte está perdido.'::text,'ha perdido'::text,'ha sido perdida'::text,'fue perdida'::text,'Ella ha perdido su pasaporte, así que ahora su pasaporte está perdido.'::text),
(366467,40719,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... son passeport, donc maintenant son passeport est perdu.'::text,'a perdu'::text,'a été perdue'::text,'a été perdue'::text,'Elle a perdu son passeport, donc maintenant son passeport est perdu.'::text),
(366470,40719,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pasaportunu ..., yani artık pasaportu kayıp.'::text,'kaybetti'::text,'kaybedildi'::text,'kaybedildi'::text,'Pasaportunu kaybetti, yani artık pasaportu kayıp.'::text),
(366471,40719,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... az útlevelét, szóval most az útlevele elveszett.'::text,'Elvesztette'::text,'Elveszett'::text,'Elveszett'::text,'Elvesztette az útlevelét, szóval most az útlevele elveszett.'::text),
(366474,40720,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieses Verhalten deutet darauf hin, dass der Gegenstand irgendwo außerhalb der Tasche verloren gegangen sein ...'::text,'muss'::text,'kann nicht'::text,'darf nicht'::text,'Dieses Verhalten deutet darauf hin, dass der Gegenstand irgendwo außerhalb der Tasche verloren gegangen sein muss.'::text),
(366478,40720,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Така поведінка вказує на те, що предмет ... бути загублений десь поза сумкою.'::text,'має'::text,'не може'::text,'не повинен'::text,'Така поведінка вказує на те, що предмет має бути загублений десь поза сумкою.'::text),
(366477,40720,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Este comportamiento indica que el objeto ... estar perdido en algún lugar fuera de la mochila.'::text,'debe de'::text,'no puede'::text,'no debe'::text,'Este comportamiento indica que el objeto debe de estar perdido en algún lugar fuera de la mochila.'::text),
(366476,40720,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce comportement indique que l''objet ... être perdu quelque part hors du sac.'::text,'doit'::text,'ne peut pas'::text,'ne doit pas'::text,'Ce comportement indique que l''objet doit être perdu quelque part hors du sac.'::text),
(366479,40720,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu davranış, eşyanın çantanın dışında bir yerde kaybolmuş ... gösteriyor.'::text,'olması gerektiğini'::text,'olamayacağını'::text,'olmaması gerektiğini'::text,'Bu davranış, eşyanın çantanın dışında bir yerde kaybolmuş olması gerektiğini gösteriyor.'::text),
(366480,40720,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a viselkedés arra utal, hogy a tárgy ... valahol a táskán kívül veszett el.'::text,'biztosan'::text,'nem lehet, hogy'::text,'nem szabad, hogy'::text,'Ez a viselkedés arra utal, hogy a tárgy biztosan valahol a táskán kívül veszett el.'::text),
(366483,40721,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt: Du bist eine Reisende, ... nicht aufgibt, wenn etwas verloren geht.'::text,'die'::text,'die'::text,'deren'::text,'Respekt: Du bist eine Reisende, die nicht aufgibt, wenn etwas verloren geht.'::text),
(366487,40721,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Повага: ти мандрівниця, ... не здається, коли щось губиться.'::text,'яка'::text,'яке'::text,'чия'::text,'Повага: ти мандрівниця, яка не здається, коли щось губиться.'::text),
(366486,40721,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respeto: eres una viajera ... no se rinde cuando algo se pierde.'::text,'que'::text,'la cual'::text,'cuya'::text,'Respeto: eres una viajera que no se rinde cuando algo se pierde.'::text),
(366485,40721,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect : t''es une voyageuse ... n''abandonne pas quand quelque chose est perdu.'::text,'qui'::text,'laquelle'::text,'dont'::text,'Respect : t''es une voyageuse qui n''abandonne pas quand quelque chose est perdu.'::text),
(366488,40721,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saygı: sen bir şey kaybolduğunda pes ... bir gezginsin.'::text,'etmeyen'::text,'etmediği'::text,'etmeyenin'::text,'Saygı: sen bir şey kaybolduğunda pes etmeyen bir gezginsin.'::text),
(366489,40721,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt: olyan utazó vagy, ... nem adja fel, ha valami elveszik.'::text,'aki'::text,'ami'::text,'akinek'::text,'Respekt: olyan utazó vagy, aki nem adja fel, ha valami elveszik.'::text),
(366492,40722,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich hab dich gefragt, was du ..., und die Suche unterm Etagenbett war smooth.'::text,'verloren hattest'::text,'hast du verloren'::text,'hast du verloren'::text,'Ich hab dich gefragt, was du verloren hattest, und die Suche unterm Etagenbett war smooth.'::text),
(366496,40722,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Я спитав, що ти ..., і той пошук під ліжком був дуже вправний.'::text,'загубила'::text,'загубила'::text,'загубила'::text,'Я спитав, що ти загубила, і той пошук під ліжком був дуже вправний.'::text),
(366495,40722,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te pregunté qué ..., y esa búsqueda bajo la litera fue impecable.'::text,'habías perdido'::text,'has perdido'::text,'perdiste'::text,'Te pregunté qué habías perdido, y esa búsqueda bajo la litera fue impecable.'::text),
(366494,40722,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je t''ai demandé ce que tu ..., et cette recherche sous le lit superposé était trop stylée.'::text,'avais perdu'::text,'as perdu'::text,'as perdu'::text,'Je t''ai demandé ce que tu avais perdu, et cette recherche sous le lit superposé était trop stylée.'::text),
(366497,40722,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sana neyi ... sordum, ranzanın altındaki o arama da çok havalıydı.'::text,'kaybettiğini'::text,'kaybettin'::text,'kaybettin mi'::text,'Sana neyi kaybettiğini sordum, ranzanın altındaki o arama da çok havalıydı.'::text),
(366498,40722,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megkérdeztem, mit ..., és az a keresés az emeletes ágy alatt nagyon laza volt.'::text,'vesztettél el'::text,'vesztettél el'::text,'vesztettél el'::text,'Megkérdeztem, mit vesztettél el, és az a keresés az emeletes ágy alatt nagyon laza volt.'::text),
(366501,40723,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als Kind hast du ... Sachen verloren, oder? Die Suche unterm Etagenbett war smooth.'::text,'oft'::text,'gewohnheitsmäßig'::text,'oft'::text,'Als Kind hast du oft Sachen verloren, oder? Die Suche unterm Etagenbett war smooth.'::text),
(366505,40723,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У дитинстві ти ... речі, так? Той пошук під ліжком був дуже вправний.'::text,'часто губила'::text,'звикла губити'::text,'часто губила'::text,'У дитинстві ти часто губила речі, так? Той пошук під ліжком був дуже вправний.'::text),
(366504,40723,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De pequeña ... cosas, ¿verdad? Esa búsqueda bajo la litera fue impecable.'::text,'solías perder'::text,'estabas acostumbrada a perder'::text,'solías perder'::text,'De pequeña solías perder cosas, ¿verdad? Esa búsqueda bajo la litera fue impecable.'::text),
(366503,40723,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Petite, tu ... des trucs, pas vrai ? Cette recherche sous le lit superposé était trop stylée.'::text,'perdais'::text,'avais l''habitude de perdre'::text,'perdais'::text,'Petite, tu perdais des trucs, pas vrai ? Cette recherche sous le lit superposé était trop stylée.'::text),
(366506,40723,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocukken eşyalarını ..., değil mi? Ranzanın altındaki o arama çok havalıydı.'::text,'kaybederdin'::text,'kaybetmeye alışkındın'::text,'kaybederdin'::text,'Çocukken eşyalarını kaybederdin, değil mi? Ranzanın altındaki o arama çok havalıydı.'::text),
(366507,40723,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gyerekként sokszor ... a dolgaidat, ugye? Az a keresés az emeletes ágy alatt nagyon laza volt.'::text,'elhagytad'::text,'hozzá voltál szokva, hogy elhagyd'::text,'elhagytad'::text,'Gyerekként sokszor elhagytad a dolgaidat, ugye? Az a keresés az emeletes ágy alatt nagyon laza volt.'::text),
(366510,40724,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Offensichtlich macht ihr das ... von Sachen in Hostels Spaß. Makellose Reiseskills.'::text,'Verlieren'::text,'Verlieren'::text,'Verlieren'::text,'Offensichtlich macht ihr das Verlieren von Sachen in Hostels Spaß. Makellose Reiseskills.'::text),
(366514,40724,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Їй явно подобається ... речі в хостелах. Бездоганні навички подорожей.'::text,'губити'::text,'губити'::text,'губити'::text,'Їй явно подобається губити речі в хостелах. Бездоганні навички подорожей.'::text),
(366513,40724,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Está claro que disfruta ... cosas en los albergues. Habilidades viajeras impecables.'::text,'perdiendo'::text,'perder'::text,'perder'::text,'Está claro que disfruta perdiendo cosas en los albergues. Habilidades viajeras impecables.'::text),
(366512,40724,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle adore visiblement ... des trucs dans les auberges de jeunesse. Talents de voyageuse impeccables.'::text,'perdre'::text,'perdre'::text,'perdre'::text,'Elle adore visiblement perdre des trucs dans les auberges de jeunesse. Talents de voyageuse impeccables.'::text),
(366515,40724,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hostellerde bir şeyler ... belli ki bayılıyor. Kusursuz seyahat becerileri.'::text,'kaybetmeye'::text,'kaybetmek'::text,'kaybet'::text,'Hostellerde bir şeyler kaybetmeye belli ki bayılıyor. Kusursuz seyahat becerileri.'::text),
(366516,40724,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Láthatóan imád ... dolgokat a hosztelekben. Hibátlan utazási skillek.'::text,'elhagyni'::text,'elhagyni'::text,'elhagy'::text,'Láthatóan imád elhagyni dolgokat a hosztelekben. Hibátlan utazási skillek.'::text),
(366519,40725,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Im Moment ... sie unter dem Etagenbett, weil sie etwas verloren hat.'::text,'sucht'::text,'sucht'::text,'hat gesucht'::text,'Im Moment sucht sie unter dem Etagenbett, weil sie etwas verloren hat.'::text),
(366523,40725,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зараз вона ... під ліжком, бо щось загубила.'::text,'шукає'::text,'шукає'::text,'шукала'::text,'Зараз вона шукає під ліжком, бо щось загубила.'::text),
(366522,40725,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En este momento ... debajo de la litera porque ha perdido algo.'::text,'está buscando'::text,'busca'::text,'ha buscado'::text,'En este momento está buscando debajo de la litera porque ha perdido algo.'::text),
(366521,40725,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, elle ... sous le lit superposé parce qu''elle a perdu quelque chose.'::text,'cherche'::text,'cherche'::text,'a cherché'::text,'En ce moment, elle cherche sous le lit superposé parce qu''elle a perdu quelque chose.'::text),
(366524,40725,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda ranzanın altında ..., çünkü bir şey kaybetti.'::text,'arıyor'::text,'arar'::text,'aradı'::text,'Şu anda ranzanın altında arıyor, çünkü bir şey kaybetti.'::text),
(366525,40725,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most az emeletes ágy alatt ..., mert elvesztett valamit.'::text,'keres'::text,'keres'::text,'keresett'::text,'Épp most az emeletes ágy alatt keres, mert elvesztett valamit.'::text),
(363711,40413,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... schon drei Anhänger an den Koffer gemacht, und ehrlich, das ist schlau.'::text,'hast'::text,'hast'::text,'machst'::text,'Du hast schon drei Anhänger an den Koffer gemacht, und ehrlich, das ist schlau.'::text),
(363715,40413,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти вже ... три бірки на ту валізу, і чесно, це розумно.'::text,'почепила'::text,'чіпляла'::text,'чіпляєш'::text,'Ти вже почепила три бірки на ту валізу, і чесно, це розумно.'::text),
(363714,40413,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ya ... tres etiquetas en esa maleta y, en serio, es muy listo.'::text,'has puesto'::text,'has estado poniendo'::text,'estás poniendo'::text,'Ya has puesto tres etiquetas en esa maleta y, en serio, es muy listo.'::text),
(363713,40413,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... déjà trois étiquettes sur cette valise, et franchement, c''est malin.'::text,'as mis'::text,'as mis'::text,'mets'::text,'Tu as mis déjà trois étiquettes sur cette valise, et franchement, c''est malin.'::text),
(363716,40413,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O valize şimdiden üç etiket ... ve açıkçası, bu çok akıllıca.'::text,'taktın'::text,'takıyorsun'::text,'takıyorsun'::text,'O valize şimdiden üç etiket taktın ve açıkçası, bu çok akıllıca.'::text),
(363717,40413,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már három címkét ... arra a bőröndre, és őszintén, ez okos.'::text,'tettél'::text,'raktál'::text,'teszel'::text,'Már három címkét tettél arra a bőröndre, és őszintén, ez okos.'::text),
(363720,40414,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis du am Gepäckband warst, ... du schon einen pinken Anhänger an deinen Koffer gemacht. Smooth.'::text,'hattest'::text,'hast'::text,'machtest'::text,'Bis du am Gepäckband warst, hattest du schon einen pinken Anhänger an deinen Koffer gemacht. Smooth.'::text),
(363724,40414,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки ти дійшла до стрічки, ти вже ... рожеву бірку на валізу. Вправно.'::text,'почепила'::text,'почепила'::text,'чіпляєш'::text,'Поки ти дійшла до стрічки, ти вже почепила рожеву бірку на валізу. Вправно.'::text),
(363723,40414,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando llegaste a la cinta, ya ... una etiqueta rosa en tu maleta. Qué estilo.'::text,'habías puesto'::text,'has puesto'::text,'pusiste'::text,'Para cuando llegaste a la cinta, ya habías puesto una etiqueta rosa en tu maleta. Qué estilo.'::text),
(363722,40414,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand t''es arrivée au tapis, tu ... une étiquette rose sur ta valise. Stylé.'::text,'avais déjà mis'::text,'as mis'::text,'as mis'::text,'Quand t''es arrivée au tapis, tu avais déjà mis une étiquette rose sur ta valise. Stylé.'::text),
(363725,40414,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bagaj bandına vardığında pembe bir etiketi çoktan ... valizine. Şık hareket.'::text,'takmıştın'::text,'taktın'::text,'taktın'::text,'Bagaj bandına vardığında pembe bir etiketi çoktan takmıştın valizine. Şık hareket.'::text),
(363726,40414,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a futószalaghoz értél, már ... egy rózsaszín címkét a bőröndödre. Laza.'::text,'tettél'::text,'tettél'::text,'tettél'::text,'Mire a futószalaghoz értél, már tettél egy rózsaszín címkét a bőröndödre. Laza.'::text),
(363729,40415,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... du gerade deinen Koffer am Anhänger vom Band, irgendwie ikonisch.'::text,'ziehst'::text,'ziehst'::text,'ziehst'::text,'Morgen um diese Zeit ziehst du gerade deinen Koffer am Anhänger vom Band, irgendwie ikonisch.'::text),
(363733,40415,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час ти ... валізу зі стрічки за бірку, трохи культово.'::text,'стягуватимеш'::text,'стягнеш'::text,'стягуєш'::text,'Завтра в цей час ти стягуватимеш валізу зі стрічки за бірку, трохи культово.'::text),
(363732,40415,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora ... tu maleta de la cinta por la etiqueta, bastante icónico.'::text,'estarás sacando'::text,'sacarás'::text,'sacas'::text,'Mañana a esta hora estarás sacando tu maleta de la cinta por la etiqueta, bastante icónico.'::text),
(363731,40415,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à cette heure-ci, tu ... ta valise du tapis grâce à son étiquette, un peu iconique.'::text,'seras en train de tirer'::text,'tireras'::text,'tires'::text,'Demain à cette heure-ci, tu seras en train de tirer ta valise du tapis grâce à son étiquette, un peu iconique.'::text),
(363734,40415,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte valizini etiketinden tanıyıp banttan ..., biraz ikonik.'::text,'çekiyor olacaksın'::text,'çekeceksin'::text,'çekiyorsun'::text,'Yarın bu saatte valizini etiketinden tanıyıp banttan çekiyor olacaksın, biraz ikonik.'::text),
(363735,40415,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor épp ... le a bőröndödet a szalagról a címkéje alapján, kicsit ikonikus.'::text,'húzod'::text,'fogod húzni'::text,'húzod'::text,'Holnap ilyenkor épp húzod le a bőröndödet a szalagról a címkéje alapján, kicsit ikonikus.'::text),
(363738,40416,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Makelloses System, offensichtlich: Morgen Mittag ... sie gerade auf den Koffer mit dem Anhänger.'::text,'wartet'::text,'wartet'::text,'wartet'::text,'Makelloses System, offensichtlich: Morgen Mittag wartet sie gerade auf den Koffer mit dem Anhänger.'::text),
(363742,40416,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бездоганна система, очевидно: завтра опівдні вона ... на ту валізу з біркою.'::text,'чекатиме'::text,'почекає'::text,'чекає'::text,'Бездоганна система, очевидно: завтра опівдні вона чекатиме на ту валізу з біркою.'::text),
(363741,40416,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sistema impecable, obviamente: mañana a mediodía ... esa maleta etiquetada.'::text,'estará esperando'::text,'esperará'::text,'espera'::text,'Sistema impecable, obviamente: mañana a mediodía estará esperando esa maleta etiquetada.'::text),
(363740,40416,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Système impeccable, évidemment : demain midi, elle ... cette valise étiquetée.'::text,'sera en train d''attendre'::text,'attendra'::text,'attend'::text,'Système impeccable, évidemment : demain midi, elle sera en train d''attendre cette valise étiquetée.'::text),
(363743,40416,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kusursuz sistem, belli ki: yarın öğlen o etiketli valizi ...'::text,'bekliyor olacak'::text,'bekleyecek'::text,'bekliyor'::text,'Kusursuz sistem, belli ki: yarın öğlen o etiketli valizi bekliyor olacak.'::text),
(363744,40416,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hibátlan rendszer, nyilván: holnap délben ... arra a címkés bőröndre.'::text,'épp várni fog'::text,'várni fog'::text,'vár'::text,'Hibátlan rendszer, nyilván: holnap délben épp várni fog arra a címkés bőröndre.'::text),
(363747,40417,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Klar, wenn ein Koffer einen knalligen Anhänger ..., nimmt ihn niemand sonst aus Versehen.'::text,'hat'::text,'hatte'::text,'haben wird'::text,'Klar, wenn ein Koffer einen knalligen Anhänger hat, nimmt ihn niemand sonst aus Versehen.'::text),
(363751,40417,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звісно, якщо на валізі ... яскрава бірка, ніхто інший не візьме її помилково.'::text,'є'::text,'була'::text,'буде'::text,'Звісно, якщо на валізі є яскрава бірка, ніхто інший не візьме її помилково.'::text),
(363750,40417,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Claro, si una maleta ... una etiqueta llamativa, nadie más se la lleva por error.'::text,'tiene'::text,'tenía'::text,'tendrá'::text,'Claro, si una maleta tiene una etiqueta llamativa, nadie más se la lleva por error.'::text),
(363749,40417,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bien sûr, si une valise ... une étiquette voyante, personne d''autre ne la prend par erreur.'::text,'a'::text,'avait'::text,'aura'::text,'Bien sûr, si une valise a une étiquette voyante, personne d''autre ne la prend par erreur.'::text),
(363752,40417,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tabii ki, bir valizin göz alıcı bir etiketi ..., başka kimse onu yanlışlıkla almaz.'::text,'varsa'::text,'vardıysa'::text,'olacaksa'::text,'Tabii ki, bir valizin göz alıcı bir etiketi varsa, başka kimse onu yanlışlıkla almaz.'::text),
(363753,40417,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Persze, ha egy bőröndön feltűnő címke ..., senki más nem viszi el tévedésből.'::text,'van'::text,'volt'::text,'lesz'::text,'Persze, ha egy bőröndön feltűnő címke van, senki más nem viszi el tévedésből.'::text),
(363756,40418,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ganz klar ein echter Profi: Wenn der Anhänger abfällt, ... sie ihren Koffer trotzdem in Sekunden.'::text,'findet'::text,'fände'::text,'fand'::text,'Ganz klar ein echter Profi: Wenn der Anhänger abfällt, findet sie ihren Koffer trotzdem in Sekunden.'::text),
(363760,40418,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Явно справжня професіоналка: якщо бірка відпаде, вона все одно ... валізу за секунди.'::text,'знайде'::text,'знайшла б'::text,'знайшла'::text,'Явно справжня професіоналка: якщо бірка відпаде, вона все одно знайде валізу за секунди.'::text),
(363759,40418,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Claramente una auténtica profesional: si se cae la etiqueta, ... su maleta en segundos de todos modos.'::text,'encontrará'::text,'encontraría'::text,'encontró'::text,'Claramente una auténtica profesional: si se cae la etiqueta, encontrará su maleta en segundos de todos modos.'::text),
(363758,40418,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Clairement une vraie pro : si l''étiquette tombe, elle ... sa valise en quelques secondes de toute façon.'::text,'retrouvera'::text,'retrouverait'::text,'a retrouvé'::text,'Clairement une vraie pro : si l''étiquette tombe, elle retrouvera sa valise en quelques secondes de toute façon.'::text),
(363761,40418,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki gerçek bir profesyonel: etiket düşerse, valizini yine de saniyeler içinde ...'::text,'bulacak'::text,'bulurdu'::text,'buldu'::text,'Belli ki gerçek bir profesyonel: etiket düşerse, valizini yine de saniyeler içinde bulacak.'::text),
(363762,40418,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egyértelműen igazi profi: ha leesik a címke, akkor is másodpercek alatt ... a bőröndjét.'::text,'megtalálja'::text,'megtalálná'::text,'megtalálta'::text,'Egyértelműen igazi profi: ha leesik a címke, akkor is másodpercek alatt megtalálja a bőröndjét.'::text),
(363765,40419,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ihr Koffer keinen Anhänger hätte, ... sie ihn zwischen den anderen schwarzen Koffern nicht erkennen.'::text,'würde'::text,'wird'::text,'erkannte'::text,'Wenn ihr Koffer keinen Anhänger hätte, würde sie ihn zwischen den anderen schwarzen Koffern nicht erkennen.'::text),
(363769,40419,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби на її валізі не було бірки, вона ... її серед інших чорних валіз.'::text,'не впізнала б'::text,'не впізнає'::text,'не впізнала'::text,'Якби на її валізі не було бірки, вона не впізнала б її серед інших чорних валіз.'::text),
(363768,40419,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si su maleta no tuviera etiqueta, no la ... entre las otras maletas negras.'::text,'reconocería'::text,'reconocerá'::text,'reconoció'::text,'Si su maleta no tuviera etiqueta, no la reconocería entre las otras maletas negras.'::text),
(363767,40419,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si sa valise n''avait pas d''étiquette, elle ne la ... pas parmi les autres valises noires.'::text,'reconnaîtrait'::text,'reconnaîtra'::text,'reconnaissait'::text,'Si sa valise n''avait pas d''étiquette, elle ne la reconnaîtrait pas parmi les autres valises noires.'::text),
(363770,40419,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Valizinin etiketi olmasaydı, onu diğer siyah valizlerin arasında ...'::text,'tanımazdı'::text,'tanımayacak'::text,'tanımadı'::text,'Valizinin etiketi olmasaydı, onu diğer siyah valizlerin arasında tanımazdı.'::text),
(363771,40419,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a bőröndjén nem lenne címke, ... a többi fekete bőrönd között.'::text,'nem ismerné fel'::text,'nem fogja felismerni'::text,'nem ismerte fel'::text,'Ha a bőröndjén nem lenne címke, nem ismerné fel a többi fekete bőrönd között.'::text),
(363774,40420,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Anhänger ... vor der Reise am Koffergriff befestigt.'::text,'wurde'::text,'befestigte'::text,'befestigt gerade'::text,'Der Anhänger wurde vor der Reise am Koffergriff befestigt.'::text),
(363778,40420,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бірку ... до ручки валізи перед поїздкою.'::text,'було прикріплено'::text,'прикріпила'::text,'прикріплює'::text,'Бірку було прикріплено до ручки валізи перед поїздкою.'::text),
(363777,40420,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La etiqueta ... al asa de la maleta antes del viaje.'::text,'fue sujetada'::text,'sujetó'::text,'está sujetando'::text,'La etiqueta fue sujetada al asa de la maleta antes del viaje.'::text),
(363776,40420,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''étiquette ... à la poignée de la valise avant le voyage.'::text,'a été attachée'::text,'a attaché'::text,'est en train d''attacher'::text,'L''étiquette a été attachée à la poignée de la valise avant le voyage.'::text),
(363779,40420,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Etiket seyahatten önce valizin sapına ...'::text,'takıldı'::text,'taktı'::text,'takıyor'::text,'Etiket seyahatten önce valizin sapına takıldı.'::text),
(363780,40420,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A címkét az utazás előtt ... a bőrönd fogantyújára.'::text,'rögzítették'::text,'rögzítette'::text,'rögzíti'::text,'A címkét az utazás előtt rögzítették a bőrönd fogantyújára.'::text),
(363783,40421,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... in der Küche einen durchsichtigen Plastikanhänger am Griff.'::text,'befestigte'::text,'wurde befestigt'::text,'befestigend'::text,'Sie befestigte in der Küche einen durchsichtigen Plastikanhänger am Griff.'::text),
(363787,40421,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... на кухні прозору пластикову бірку до ручки.'::text,'прикріпила'::text,'була прикріплена'::text,'прикріплюючи'::text,'Вона прикріпила на кухні прозору пластикову бірку до ручки.'::text),
(363786,40421,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En la cocina, ... una etiqueta de plástico transparente al asa.'::text,'sujetó'::text,'fue sujetada'::text,'sujetando'::text,'En la cocina, sujetó una etiqueta de plástico transparente al asa.'::text),
(363785,40421,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dans la cuisine, elle ... une étiquette en plastique transparent à la poignée.'::text,'a attaché'::text,'a été attachée'::text,'attachant'::text,'Dans la cuisine, elle a attaché une étiquette en plastique transparent à la poignée.'::text),
(363788,40421,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mutfakta sapa şeffaf plastik bir etiket ...'::text,'taktı'::text,'takıldı'::text,'takarak'::text,'Mutfakta sapa şeffaf plastik bir etiket taktı.'::text),
(363789,40421,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A konyhában egy átlátszó műanyag címkét ... a fogantyúra.'::text,'rögzített'::text,'rögzítve lett'::text,'rögzítve'::text,'A konyhában egy átlátszó műanyag címkét rögzített a fogantyúra.'::text),
(365511,40613,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... ein Pack-Profi sein; du hast jeden Koffer in den Van gehoben.'::text,'musst'::text,'kannst kein'::text,'bist vielleicht kein'::text,'Ehrlich, du musst ein Pack-Profi sein; du hast jeden Koffer in den Van gehoben.'::text),
(365515,40613,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... бути профі в пакуванні: ти підняв кожну валізу в той фургон.'::text,'маєш'::text,'не можеш'::text,'можеш і не'::text,'Чесно, ти маєш бути профі в пакуванні: ти підняв кожну валізу в той фургон.'::text),
(365514,40613,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En serio, ... ser un pro empacando; subiste cada maleta a esa furgoneta.'::text,'debes de'::text,'no puedes'::text,'puede que no'::text,'En serio, debes de ser un pro empacando; subiste cada maleta a esa furgoneta.'::text),
(365513,40613,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... être un pro du rangement ; t''as soulevé chaque valise dans ce van.'::text,'dois'::text,'ne peux pas'::text,'pourrais ne pas'::text,'Franchement, tu dois être un pro du rangement ; t''as soulevé chaque valise dans ce van.'::text),
(365516,40613,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, sen profesyonel bir paketçi ...; her valizi o minibüse sen kaldırdın.'::text,'olmalısın'::text,'olamazsın'::text,'olmayabilirsin'::text,'Açıkçası, sen profesyonel bir paketçi olmalısın; her valizi o minibüse sen kaldırdın.'::text),
(365517,40613,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ... profi pakoló vagy; minden bőröndöt te emeltél be abba a furgonba.'::text,'biztos'::text,'kizárt, hogy'::text,'lehet, hogy nem'::text,'Őszintén, biztos profi pakoló vagy; minden bőröndöt te emeltél be abba a furgonba.'::text),
(365520,40614,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du bist die Art Reisender, ... jede Tasche allein hebt, Respekt.'::text,'der'::text,'das'::text,'dessen'::text,'Du bist die Art Reisender, der jede Tasche allein hebt, Respekt.'::text),
(365524,40614,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти з тих мандрівників, ... піднімають кожну сумку самі, повага.'::text,'які'::text,'що'::text,'чиї'::text,'Ти з тих мандрівників, які піднімають кожну сумку самі, повага.'::text),
(365523,40614,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eres el tipo de viajero ... levanta cada bolsa solo, respeto.'::text,'que'::text,'el cual'::text,'cuyo'::text,'Eres el tipo de viajero que levanta cada bolsa solo, respeto.'::text),
(365522,40614,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'T''es le genre de voyageur ... soulève chaque sac tout seul, respect.'::text,'qui'::text,'lequel'::text,'dont'::text,'T''es le genre de voyageur qui soulève chaque sac tout seul, respect.'::text),
(365525,40614,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her çantayı tek başına ... türden bir gezginsin, saygı.'::text,'kaldıran'::text,'kaldırdığı'::text,'kaldıranın'::text,'Her çantayı tek başına kaldıran türden bir gezginsin, saygı.'::text),
(365526,40614,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az a fajta utazó vagy, ... minden táskát egyedül emel fel, respekt.'::text,'aki'::text,'ami'::text,'akinek'::text,'Az a fajta utazó vagy, aki minden táskát egyedül emel fel, respekt.'::text),
(365529,40615,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hat versprochen, er ... nur eine Tasche heben. Super gemacht, er hat alle gehoben.'::text,'würde'::text,'wird'::text,'ist'::text,'Er hat versprochen, er würde nur eine Tasche heben. Super gemacht, er hat alle gehoben.'::text),
(365533,40615,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він пообіцяв, що ... лише одну сумку. Чудова робота, він підняв усі.'::text,'підніме'::text,'підніме'::text,'є'::text,'Він пообіцяв, що підніме лише одну сумку. Чудова робота, він підняв усі.'::text),
(365532,40615,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Prometió que solo ... una bolsa. Genial, las levantó todas.'::text,'levantaría'::text,'levantará'::text,'está'::text,'Prometió que solo levantaría una bolsa. Genial, las levantó todas.'::text),
(365531,40615,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a promis qu''il ne ... qu''un seul sac. Bravo, il les a tous soulevés.'::text,'soulèverait'::text,'soulèvera'::text,'est'::text,'Il a promis qu''il ne soulèverait qu''un seul sac. Bravo, il les a tous soulevés.'::text),
(365534,40615,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sadece bir çanta ... söz verdi. Harika iş, hepsini kaldırdı.'::text,'kaldıracağına'::text,'kaldıracağına'::text,'kaldırdığına'::text,'Sadece bir çanta kaldıracağına söz verdi. Harika iş, hepsini kaldırdı.'::text),
(365535,40615,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megígérte, hogy csak egy táskát ... fel. Szép munka, mindet felemelte.'::text,'emel'::text,'fog'::text,NULL::text,'Megígérte, hogy csak egy táskát emel fel. Szép munka, mindet felemelte.'::text),
(365538,40616,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Offensichtlich ... er im Urlaub früher nur eine kleine Tasche; jetzt hebt er den ganzen Wagen.'::text,'hob'::text,'war es gewohnt zu heben'::text,'hob'::text,'Offensichtlich hob er im Urlaub früher nur eine kleine Tasche; jetzt hebt er den ganzen Wagen.'::text),
(365542,40616,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Очевидно, раніше у відпустці він ... одну маленьку сумку; тепер він піднімає весь візок.'::text,'піднімав'::text,'звик піднімати'::text,'піднімав'::text,'Очевидно, раніше у відпустці він піднімав одну маленьку сумку; тепер він піднімає весь візок.'::text),
(365541,40616,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Obviamente, en vacaciones ... una sola bolsa pequeña; ahora levanta el carrito entero.'::text,'solía levantar'::text,'estaba acostumbrado a levantar'::text,'solía levantar'::text,'Obviamente, en vacaciones solía levantar una sola bolsa pequeña; ahora levanta el carrito entero.'::text),
(365540,40616,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Évidemment, en vacances, il ... un seul petit sac ; maintenant il soulève tout le chariot.'::text,'soulevait'::text,'avait l''habitude de soulever'::text,'soulevait'::text,'Évidemment, en vacances, il soulevait un seul petit sac ; maintenant il soulève tout le chariot.'::text),
(365543,40616,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki tatilde eskiden tek bir küçük çanta ...; şimdi bütün arabayı kaldırıyor.'::text,'kaldırırdı'::text,'kaldırmaya alışkındı'::text,'kaldırırdı'::text,'Belli ki tatilde eskiden tek bir küçük çanta kaldırırdı; şimdi bütün arabayı kaldırıyor.'::text),
(365544,40616,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván régen a nyaraláson csak egy kis táskát ... fel; most az egész kocsit felemeli.'::text,'emelt'::text,'szokott emelni'::text,'emelt'::text,'Nyilván régen a nyaraláson csak egy kis táskát emelt fel; most az egész kocsit felemeli.'::text),
(365547,40617,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Um das ... jedes schweren Koffers kommt er offensichtlich nicht herum. Ein echter Profi.'::text,'Heben'::text,'Heben'::text,'Heben'::text,'Um das Heben jedes schweren Koffers kommt er offensichtlich nicht herum. Ein echter Profi.'::text),
(365551,40617,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він явно не може не ... кожну важку валізу сам. Справжній профі.'::text,'піднімати'::text,'піднімати'::text,'піднімати'::text,'Він явно не може не піднімати кожну важку валізу сам. Справжній профі.'::text),
(365550,40617,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Está claro que no puede evitar ... cada maleta pesada él mismo. Todo un profesional.'::text,'levantar'::text,'levantar'::text,'levantar'::text,'Está claro que no puede evitar levantar cada maleta pesada él mismo. Todo un profesional.'::text),
(365549,40617,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ne peut visiblement pas s''empêcher de ... chaque valise lourde lui-même. Un vrai pro.'::text,'soulever'::text,'soulever'::text,'soulever'::text,'Il ne peut visiblement pas s''empêcher de soulever chaque valise lourde lui-même. Un vrai pro.'::text),
(365552,40617,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki her ağır valizi kendisi ... kaçınamıyor. Gerçek bir profesyonel.'::text,'kaldırmaktan'::text,'kaldırmak'::text,'kaldır'::text,'Belli ki her ağır valizi kendisi kaldırmaktan kaçınamıyor. Gerçek bir profesyonel.'::text),
(365553,40617,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Láthatóan nem tudja elkerülni, hogy ... minden nehéz bőröndöt. Igazi profi.'::text,'maga emelje fel'::text,'felemelni'::text,'felemel'::text,'Láthatóan nem tudja elkerülni, hogy maga emelje fel minden nehéz bőröndöt. Igazi profi.'::text),
(365565,40619,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann hob drei Koffer in den Van, und ... sein Freund hinter der Kamera.'::text,'ebenso'::text,'ebenso'::text,'auch nicht'::text,'Der Mann hob drei Koffer in den Van, und ebenso sein Freund hinter der Kamera.'::text),
(365569,40619,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік підняв три валізи у фургон, і ... його друг за камерою.'::text,'так само'::text,'так само'::text,'ні'::text,'Чоловік підняв три валізи у фургон, і так само його друг за камерою.'::text),
(365568,40619,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre subió tres maletas a la furgoneta, y ... su amigo detrás de la cámara.'::text,'también'::text,'también'::text,'tampoco'::text,'El hombre subió tres maletas a la furgoneta, y también su amigo detrás de la cámara.'::text),
(365567,40619,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme a soulevé trois valises dans le van, ... son ami derrière la caméra.'::text,'tout comme'::text,'tout comme'::text,'pas plus que'::text,'L''homme a soulevé trois valises dans le van, tout comme son ami derrière la caméra.'::text),
(365570,40619,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam üç valizi minibüse kaldırdı, kameranın arkasındaki arkadaşı ...'::text,'da öyle yaptı'::text,'da öyleydi'::text,'da yapmadı'::text,'Adam üç valizi minibüse kaldırdı, kameranın arkasındaki arkadaşı da öyle yaptı.'::text),
(365571,40619,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi három bőröndöt emelt be a furgonba, és a kamera mögött álló barátja ...'::text,'is'::text,'is'::text,'sem'::text,'A férfi három bőröndöt emelt be a furgonba, és a kamera mögött álló barátja is.'::text),
(365574,40620,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... zehn Minuten lang schwere Koffer gehoben, bevor der Kofferraum endlich voll war.'::text,'hatte'::text,'hat'::text,'wurde'::text,'Er hatte zehn Minuten lang schwere Koffer gehoben, bevor der Kofferraum endlich voll war.'::text),
(365578,40620,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... важкі валізи десять хвилин, поки багажник нарешті не заповнився.'::text,'піднімав'::text,'піднімає'::text,'був піднятий'::text,'Він піднімав важкі валізи десять хвилин, поки багажник нарешті не заповнився.'::text),
(365577,40620,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... maletas pesadas durante diez minutos antes de que el maletero por fin estuviera lleno.'::text,'había estado levantando'::text,'ha estado levantando'::text,'fue levantado'::text,'Él había estado levantando maletas pesadas durante diez minutos antes de que el maletero por fin estuviera lleno.'::text),
(365576,40620,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... des valises lourdes pendant dix minutes avant que le coffre soit enfin plein.'::text,'avait soulevé'::text,'a soulevé'::text,'a été soulevé'::text,'Il avait soulevé des valises lourdes pendant dix minutes avant que le coffre soit enfin plein.'::text),
(365579,40620,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bagaj sonunda dolmadan önce on dakika boyunca ağır valizler ...'::text,'kaldırıyordu'::text,'kaldırıyor'::text,'kaldırıldı'::text,'Bagaj sonunda dolmadan önce on dakika boyunca ağır valizler kaldırıyordu.'::text),
(365580,40620,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tíz percig ... a nehéz bőröndöket, mire végre megtelt a csomagtartó.'::text,'emelgette'::text,'emelgeti'::text,'emelve lett'::text,'Tíz percig emelgette a nehéz bőröndöket, mire végre megtelt a csomagtartó.'::text),
(365583,40621,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis seine Familie rauskommt, ... er jeden Koffer in den Van gehoben.'::text,'hat'::text,'wird'::text,'hebt'::text,'Bis seine Familie rauskommt, hat er jeden Koffer in den Van gehoben.'::text),
(365587,40621,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки його родина вийде, він ... кожну валізу у фургон.'::text,'підніме'::text,'підніме'::text,'піднімає'::text,'Поки його родина вийде, він підніме кожну валізу у фургон.'::text),
