(365585,40621,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici à ce que sa famille sorte, il ... chaque valise dans le van.'::text,'aura soulevé'::text,'soulèvera'::text,'soulève'::text,'D''ici à ce que sa famille sorte, il aura soulevé chaque valise dans le van.'::text),
(365588,40621,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ailesi dışarı çıkana kadar her valizi minibüse ...'::text,'kaldırmış olacak'::text,'kaldıracak'::text,'kaldırıyor'::text,'Ailesi dışarı çıkana kadar her valizi minibüse kaldırmış olacak.'::text),
(365589,40621,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a családja kijön, minden bőröndöt ... a furgonba.'::text,'be fog emelni'::text,'beemel majd'::text,'beemel'::text,'Mire a családja kijön, minden bőröndöt be fog emelni a furgonba.'::text),
(365601,40623,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn du die Koffer nicht so schnell gehoben hättest, ... der Van nicht rechtzeitig gepackt gewesen. Respekt.'::text,'wäre'::text,'wird'::text,'war'::text,'Wenn du die Koffer nicht so schnell gehoben hättest, wäre der Van nicht rechtzeitig gepackt gewesen. Respekt.'::text),
(365605,40623,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби ти не підняв ті валізи так швидко, фургон ... вчасно зібраний. Повага.'::text,'не був би'::text,'не буде'::text,'не був'::text,'Якби ти не підняв ті валізи так швидко, фургон не був би вчасно зібраний. Повага.'::text),
(365604,40623,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no hubieras subido esas maletas tan rápido, la furgoneta ... cargada a tiempo. Respeto.'::text,'no habría estado'::text,'no estará'::text,'no estaba'::text,'Si no hubieras subido esas maletas tan rápido, la furgoneta no habría estado cargada a tiempo. Respeto.'::text),
