(365606,40623,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Helal olsun: o valizleri bu kadar hızlı kaldırmasaydın, minibüs zamanında dolmuş ...'::text,'olmazdı'::text,'olmayacak'::text,'değildi'::text,'Helal olsun: o valizleri bu kadar hızlı kaldırmasaydın, minibüs zamanında dolmuş olmazdı.'::text),
(365607,40623,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem emelted volna be ilyen gyorsan azokat a bőröndöket, a furgon ... időben bepakolva. Respekt.'::text,'nem lett volna'::text,'nem lesz'::text,'nem volt'::text,'Ha nem emelted volna be ilyen gyorsan azokat a bőröndöket, a furgon nem lett volna időben bepakolva. Respekt.'::text),
(371703,41301,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Raucher wünschte, er ... besser auf seine Lunge aufgepasst, das Organ, das er vor Jahren geschädigt hat.'::text,'hätte'::text,'passte'::text,'würde'::text,'Der Raucher wünschte, er hätte besser auf seine Lunge aufgepasst, das Organ, das er vor Jahren geschädigt hat.'::text),
