(371706,41301,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El fumador desearía ... mejor de sus pulmones, el órgano que dañó hace años.'::text,'haber cuidado'::text,'cuidar'::text,'cuidar'::text,'El fumador desearía haber cuidado mejor de sus pulmones, el órgano que dañó hace años.'::text),
(371705,41301,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le fumeur aimerait ... mieux soin de ses poumons, l''organe qu''il a abîmé il y a des années.'::text,'avoir pris'::text,'prendre'::text,'prendre'::text,'Le fumeur aimerait avoir pris mieux soin de ses poumons, l''organe qu''il a abîmé il y a des années.'::text),
(371708,41301,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sigara içen adam, yıllar önce zarar verdiği organı olan ciğerlerine keşke daha iyi ... diye düşünüyor.'::text,'baksaydı'::text,'baksa'::text,'bakacak'::text,'Sigara içen adam, yıllar önce zarar verdiği organı olan ciğerlerine keşke daha iyi baksaydı diye düşünüyor.'::text),
