(367083,40787,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván, ha a szobalány nem hajtogatta volna meg azt a hattyút, a szoba most ... ilyen elegáns.'::text,'nem lenne'::text,'nem lett volna'::text,'nem lesz'::text,'Nyilván, ha a szobalány nem hajtogatta volna meg azt a hattyút, a szoba most nem lenne ilyen elegáns.'::text),
(367086,40788,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Handtuchschwan soll vom Zimmermädchen in dreißig Sekunden ... worden sein! Absolut unglaublich!'::text,'gefaltet'::text,'falten'::text,'faltend'::text,'Der Handtuchschwan soll vom Zimmermädchen in dreißig Sekunden gefaltet worden sein! Absolut unglaublich!'::text),
(367090,40788,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кажуть, лебідь із рушників ... покоївкою за тридцять секунд! Абсолютно неймовірно!'::text,'був складений'::text,'складати'::text,'складаючи'::text,'Кажуть, лебідь із рушників був складений покоївкою за тридцять секунд! Абсолютно неймовірно!'::text),
(367089,40788,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Dicen que el cisne de toallas ... por la camarera de piso en treinta segundos! ¡Absolutamente increíble!'::text,'fue doblado'::text,'doblar'::text,'doblando'::text,'¡Dicen que el cisne de toallas fue doblado por la camarera de piso en treinta segundos! ¡Absolutamente increíble!'::text),
(367088,40788,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On dit que le cygne en serviettes ... par la femme de chambre en trente secondes ! Absolument incroyable !'::text,'a été plié'::text,'plier'::text,'pliant'::text,'On dit que le cygne en serviettes a été plié par la femme de chambre en trente secondes ! Absolument incroyable !'::text),
(367091,40788,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Havlu kuğunun oda görevlisi tarafından otuz saniyede ... söyleniyor! Kesinlikle inanılmaz!'::text,'katlandığı'::text,'katlamak'::text,'katlayarak'::text,'Havlu kuğunun oda görevlisi tarafından otuz saniyede katlandığı söyleniyor! Kesinlikle inanılmaz!'::text),
(367092,40788,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondják, a törölközőhattyút a szobalány harminc másodperc alatt ...! Hihetetlen!'::text,'hajtogatta össze'::text,'összehajtogatni'::text,'összehajtogatva'::text,'Azt mondják, a törölközőhattyút a szobalány harminc másodperc alatt hajtogatta össze! Hihetetlen!'::text),
(367095,40789,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Gast warf dem Zimmermädchen vor, seine Handtücher in einen Schwan ...! Der absolute Albtraum!'::text,'verwandelt zu haben'::text,'zu verwandeln'::text,'verwandelte'::text,'Der Gast warf dem Zimmermädchen vor, seine Handtücher in einen Schwan verwandelt zu haben! Der absolute Albtraum!'::text),
(367099,40789,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гість звинуватив покоївку в тому, що вона ... його рушники на лебедя! Абсолютний кошмар!'::text,'перетворила'::text,'перетворити'::text,'перетворила'::text,'Гість звинуватив покоївку в тому, що вона перетворила його рушники на лебедя! Абсолютний кошмар!'::text),
(367098,40789,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El huésped acusó a la camarera de piso de ... sus toallas en un cisne! ¡Una auténtica pesadilla!'::text,'convertir'::text,'convertir'::text,'convirtió'::text,'¡El huésped acusó a la camarera de piso de convertir sus toallas en un cisne! ¡Una auténtica pesadilla!'::text),
(367097,40789,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le client a accusé la femme de chambre de ... ses serviettes en cygne ! Le cauchemar absolu !'::text,'transformer'::text,'transformer'::text,'a transformé'::text,'Le client a accusé la femme de chambre de transformer ses serviettes en cygne ! Le cauchemar absolu !'::text),
(367100,40789,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Misafir, oda görevlisini havlularını kuğuya ... suçladı! Tam bir kâbus!'::text,'dönüştürmekle'::text,'dönüştürmek'::text,'dönüştürdü'::text,'Misafir, oda görevlisini havlularını kuğuya dönüştürmekle suçladı! Tam bir kâbus!'::text),
(367101,40789,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vendég azzal vádolta a szobalányt, hogy hattyúvá ... a törölközőit! Totális rémálom!'::text,'hajtogatta'::text,'hajtogatni'::text,'hajtogatta'::text,'A vendég azzal vádolta a szobalányt, hogy hattyúvá hajtogatta a törölközőit! Totális rémálom!'::text),
(367104,40790,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, das Zimmermädchen ... angeblich Stunden an diesem Handtuchschwan gesessen haben, er ist perfekt.'::text,'muss'::text,'sollte'::text,'kann nicht'::text,'Hör mal, das Zimmermädchen muss angeblich Stunden an diesem Handtuchschwan gesessen haben, er ist perfekt.'::text),
(367108,40790,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, покоївка ... години на того лебедя з рушників, він ідеальний.'::text,'напевно витратила'::text,'мала витратити'::text,'не могла витратити'::text,'Слухай, кажуть, покоївка напевно витратила години на того лебедя з рушників, він ідеальний.'::text),
(367107,40790,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer la camarera de piso ... horas con ese cisne de toallas, es perfecto.'::text,'debió de pasar'::text,'debería haber pasado'::text,'no pudo haber pasado'::text,'Oye, al parecer la camarera de piso debió de pasar horas con ese cisne de toallas, es perfecto.'::text),
(367106,40790,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment la femme de chambre ... des heures sur ce cygne en serviettes, il est parfait.'::text,'a dû passer'::text,'aurait dû passer'::text,'n''a pas pu passer'::text,'Écoute, apparemment la femme de chambre a dû passer des heures sur ce cygne en serviettes, il est parfait.'::text),
(367109,40790,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duyduğuma göre oda görevlisi o havlu kuğuya saatlerini ..., kusursuz olmuş.'::text,'vermiş olmalı'::text,'vermeliydi'::text,'vermiş olamaz'::text,'Dinle, duyduğuma göre oda görevlisi o havlu kuğuya saatlerini vermiş olmalı, kusursuz olmuş.'::text),
(367110,40790,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, a szobalány állítólag órákat ... azzal a törölközőhattyúval, tökéletes lett.'::text,'biztos eltöltött'::text,'el kellett volna töltenie'::text,'nem tölthetett el'::text,'Figyelj, a szobalány állítólag órákat biztos eltöltött azzal a törölközőhattyúval, tökéletes lett.'::text),
(367113,40791,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Hotel lässt das Zimmermädchen jedes Bett ..., bevor neue Gäste ankommen.'::text,'machen'::text,'machen'::text,'gemacht'::text,'Das Hotel lässt das Zimmermädchen jedes Bett machen, bevor neue Gäste ankommen.'::text),
(367117,40791,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Готель доручає покоївці ... кожне ліжко, перш ніж приїдуть нові гості.'::text,'застелити'::text,'застелити'::text,'застелила'::text,'Готель доручає покоївці застелити кожне ліжко, перш ніж приїдуть нові гості.'::text),
(367116,40791,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hotel hace que la camarera de piso ... todas las camas antes de que lleguen nuevos huéspedes.'::text,'haga'::text,'haga'::text,'hizo'::text,'El hotel hace que la camarera de piso haga todas las camas antes de que lleguen nuevos huéspedes.'::text),
(367115,40791,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''hôtel fait ... chaque lit à la femme de chambre avant l''arrivée des nouveaux clients.'::text,'faire'::text,'faire'::text,'fait'::text,'L''hôtel fait faire chaque lit à la femme de chambre avant l''arrivée des nouveaux clients.'::text),
(367118,40791,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Otel, yeni misafirler gelmeden önce oda görevlisine her yatağı ...'::text,'yaptırıyor'::text,'yaptırıyor'::text,'yaptı'::text,'Otel, yeni misafirler gelmeden önce oda görevlisine her yatağı yaptırıyor.'::text),
(367119,40791,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szálloda minden ágyat ... a szobalánnyal, mielőtt megérkeznek az új vendégek.'::text,'megvetet'::text,'megvetet'::text,'megvetett'::text,'A szálloda minden ágyat megvetet a szobalánnyal, mielőtt megérkeznek az új vendégek.'::text),
(367122,40792,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Zimmermädchen, ... Wagen in der Tür steht, legt dem Schwan eine Blume dazu.'::text,'dessen'::text,'das'::text,'welches'::text,'Das Zimmermädchen, dessen Wagen in der Tür steht, legt dem Schwan eine Blume dazu.'::text),
(367126,40792,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Покоївка, ... візок стоїть у дверях, додає до лебедя квітку.'::text,'чий'::text,'яка'::text,'який'::text,'Покоївка, чий візок стоїть у дверях, додає до лебедя квітку.'::text),
(367125,40792,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La camarera de piso, ... carrito está en la puerta, añade una flor al cisne.'::text,'cuyo'::text,'que'::text,'la cual'::text,'La camarera de piso, cuyo carrito está en la puerta, añade una flor al cisne.'::text),
(367124,40792,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme de chambre, ... le chariot est dans l''embrasure de la porte, ajoute une fleur au cygne.'::text,'dont'::text,'qui'::text,'laquelle'::text,'La femme de chambre, dont le chariot est dans l''embrasure de la porte, ajoute une fleur au cygne.'::text),
(367127,40792,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arabası kapı eşiğinde ... oda görevlisi, kuğuya bir çiçek ekliyor.'::text,'duran'::text,'duran'::text,'duran'::text,'Arabası kapı eşiğinde duran oda görevlisi, kuğuya bir çiçek ekliyor.'::text),
(367128,40792,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szobalány, ... kocsija az ajtóban áll, egy virágot tesz a hattyúhoz.'::text,'akinek a'::text,'aki'::text,'amely'::text,'A szobalány, akinek a kocsija az ajtóban áll, egy virágot tesz a hattyúhoz.'::text),
(367131,40793,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie arbeitet seit drei Jahren als ... in diesem Strandhotel.'::text,'Zimmermädchen'::text,'das Zimmermädchen'::text,'Zimmermädchen'::text,'Sie arbeitet seit drei Jahren als Zimmermädchen in diesem Strandhotel.'::text),
(367135,40793,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона вже три роки працює ... в цьому пляжному готелі.'::text,'покоївкою'::text,'покоївкою'::text,'покоївкою'::text,'Вона вже три роки працює покоївкою в цьому пляжному готелі.'::text),
(367134,40793,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lleva tres años trabajando como ... en este hotel de playa.'::text,'camarera de piso'::text,'la camarera de piso'::text,'camarera de piso'::text,'Lleva tres años trabajando como camarera de piso en este hotel de playa.'::text),
(367133,40793,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle travaille comme ... dans cet hôtel de plage depuis trois ans.'::text,'femme de chambre'::text,'la femme de chambre'::text,'femme de chambre'::text,'Elle travaille comme femme de chambre dans cet hôtel de plage depuis trois ans.'::text),
(367136,40793,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Üç yıldır bu sahil otelinde ... olarak çalışıyor.'::text,'oda görevlisi'::text,'oda görevlisi'::text,'oda görevlisi'::text,'Üç yıldır bu sahil otelinde oda görevlisi olarak çalışıyor.'::text),
(367137,40793,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Három éve dolgozik ... ebben a tengerparti szállodában.'::text,'szobalányként'::text,'a szobalányként'::text,'szobalányként'::text,'Három éve dolgozik szobalányként ebben a tengerparti szállodában.'::text),
(367140,40794,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ihrer Müdigkeit am Ende der Schicht faltet das Zimmermädchen einen perfekten Schwan.'::text,'Trotz'::text,'Obwohl'::text,'Aufgrund'::text,'Trotz ihrer Müdigkeit am Ende der Schicht faltet das Zimmermädchen einen perfekten Schwan.'::text),
(367144,40794,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... втому наприкінці зміни, покоївка складає ідеального лебедя.'::text,'Попри'::text,'Хоча'::text,'Через'::text,'Попри втому наприкінці зміни, покоївка складає ідеального лебедя.'::text),
(367143,40794,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... estar cansada al final de su turno, la camarera de piso dobla un cisne perfecto.'::text,'A pesar de'::text,'Aunque'::text,'Debido a'::text,'A pesar de estar cansada al final de su turno, la camarera de piso dobla un cisne perfecto.'::text),
(367142,40794,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la fatigue de fin de service, la femme de chambre plie un cygne parfait.'::text,'Malgré'::text,'Bien que'::text,'En raison de'::text,'Malgré la fatigue de fin de service, la femme de chambre plie un cygne parfait.'::text),
(367145,40794,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vardiyasının sonunda yorgun olmasına ..., oda görevlisi kusursuz bir kuğu katlıyor.'::text,'rağmen'::text,'karşın'::text,'dolayı'::text,'Vardiyasının sonunda yorgun olmasına rağmen, oda görevlisi kusursuz bir kuğu katlıyor.'::text),
(367146,40794,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Műszakja végén érzett fáradtsága ... a szobalány tökéletes hattyút hajtogat.'::text,'ellenére'::text,'bár'::text,'miatt'::text,'Műszakja végén érzett fáradtsága ellenére a szobalány tökéletes hattyút hajtogat.'::text),
(367149,40795,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als Zimmermädchen wusstest du, dass die Gäste den Schwan ..., und ehrlich, so war''s.'::text,'lieben würden'::text,'lieben werden'::text,'liebten'::text,'Als Zimmermädchen wusstest du, dass die Gäste den Schwan lieben würden, und ehrlich, so war''s.'::text),
(367153,40795,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Як покоївка, ти знала, що гостям ... той лебідь, і чесно, так і було.'::text,'сподобається'::text,'сподобається'::text,'сподобався'::text,'Як покоївка, ти знала, що гостям сподобається той лебідь, і чесно, так і було.'::text),
(367152,40795,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Como camarera de piso, sabías que a los huéspedes les ... ese cisne, y la verdad, así fue.'::text,'encantaría'::text,'encantará'::text,'encantó'::text,'Como camarera de piso, sabías que a los huéspedes les encantaría ese cisne, y la verdad, así fue.'::text),
(367151,40795,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En tant que femme de chambre, tu savais que les clients ... ce cygne, et franchement, c''était le cas.'::text,'adoreraient'::text,'adoreront'::text,'ont adoré'::text,'En tant que femme de chambre, tu savais que les clients adoreraient ce cygne, et franchement, c''était le cas.'::text),
(367154,40795,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oda görevlisi olarak misafirlerin o kuğuya ... biliyordun, ve açıkçası bayıldılar.'::text,'bayılacağını'::text,'bayılacağını'::text,'bayıldığını'::text,'Oda görevlisi olarak misafirlerin o kuğuya bayılacağını biliyordun, ve açıkçası bayıldılar.'::text),
(367155,40795,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szobalányként tudtad, hogy a vendégek ... azt a hattyút, és őszintén, így is lett.'::text,'imádni fogják'::text,'imádni fogják'::text,'imádták'::text,'Szobalányként tudtad, hogy a vendégek imádni fogják azt a hattyút, és őszintén, így is lett.'::text),
(367167,40797,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nachdem das Zimmermädchen das Bett ..., faltete es einen makellosen Schwan. Nichts zu meckern.'::text,'gemacht hatte'::text,'gerade machte'::text,'gemacht hat'::text,'Nachdem das Zimmermädchen das Bett gemacht hatte, faltete es einen makellosen Schwan. Nichts zu meckern.'::text),
(367171,40797,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Після того як покоївка ... ліжко, вона склала бездоганного лебедя. Без зауважень.'::text,'застелила'::text,'застеляла'::text,'застелила'::text,'Після того як покоївка застелила ліжко, вона склала бездоганного лебедя. Без зауважень.'::text),
(367170,40797,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Después de que la camarera de piso ... la cama, dobló un cisne impecable. Sin comentarios.'::text,'hubiera hecho'::text,'estaba haciendo'::text,'ha hecho'::text,'Después de que la camarera de piso hubiera hecho la cama, dobló un cisne impecable. Sin comentarios.'::text),
(367169,40797,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Après que la femme de chambre ... le lit, elle a plié un cygne impeccable. Rien à redire.'::text,'avait fait'::text,'faisait'::text,'a fait'::text,'Après que la femme de chambre avait fait le lit, elle a plié un cygne impeccable. Rien à redire.'::text),
(367172,40797,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oda görevlisi yatağı ... sonra kusursuz bir kuğu katladı. Diyecek yok.'::text,'yaptıktan'::text,'yaparken'::text,'yaptı'::text,'Oda görevlisi yatağı yaptıktan sonra kusursuz bir kuğu katladı. Diyecek yok.'::text),
(367173,40797,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miután a szobalány ... az ágyat, hibátlan hattyút hajtogatott. Nincs mit hozzáfűzni.'::text,'megvetette'::text,'vetette'::text,'megvetette'::text,'Miután a szobalány megvetette az ágyat, hibátlan hattyút hajtogatott. Nincs mit hozzáfűzni.'::text),
(367338,40816,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein junger Mann ... gerade Klimmzüge, als sich die Kamera zu ihm drehte.'::text,'machte'::text,'machte'::text,'hat gemacht'::text,'Ein junger Mann machte gerade Klimmzüge, als sich die Kamera zu ihm drehte.'::text),
(367342,40816,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Молодий чоловік ... підтягування, коли камера повернулася до нього.'::text,'робив'::text,'зробив'::text,'зробив'::text,'Молодий чоловік робив підтягування, коли камера повернулася до нього.'::text),
(367341,40816,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un hombre joven ... dominadas cuando la cámara se giró hacia él.'::text,'estaba haciendo'::text,'hizo'::text,'ha hecho'::text,'Un hombre joven estaba haciendo dominadas cuando la cámara se giró hacia él.'::text),
(367340,40816,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un jeune homme ... des tractions quand la caméra s''est tournée vers lui.'::text,'faisait'::text,'a fait'::text,'a fait'::text,'Un jeune homme faisait des tractions quand la caméra s''est tournée vers lui.'::text),
(367343,40816,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kamera ona döndüğünde genç bir erkek barfiks ...'::text,'çekiyordu'::text,'çekti'::text,'çekmiş'::text,'Kamera ona döndüğünde genç bir erkek barfiks çekiyordu.'::text),
(367344,40816,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy fiatal férfi épp ..., amikor a kamera ráfordult.'::text,'húzódzkodott'::text,'húzódzkodott'::text,'húzódzkodott'::text,'Egy fiatal férfi épp húzódzkodott, amikor a kamera ráfordult.'::text),
(367347,40817,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der junge Mann ... schon seit einer Stunde Klimmzüge im Park.'::text,'macht'::text,'macht'::text,'macht'::text,'Der junge Mann macht schon seit einer Stunde Klimmzüge im Park.'::text),
(367351,40817,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Той молодий чоловік ... підтягування в парку вже годину.'::text,'робить'::text,'робить'::text,'робить'::text,'Той молодий чоловік робить підтягування в парку вже годину.'::text),
(367350,40817,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ese chico ... dominadas en el parque desde hace una hora.'::text,'hace'::text,'está haciendo'::text,'hace'::text,'Ese chico hace dominadas en el parque desde hace una hora.'::text),
(367349,40817,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce jeune homme ... des tractions dans le parc depuis une heure.'::text,'fait'::text,'fait'::text,'fait'::text,'Ce jeune homme fait des tractions dans le parc depuis une heure.'::text),
(367352,40817,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O genç erkek bir saattir parkta barfiks ...'::text,'çekiyor'::text,'çekiyor'::text,'çeker'::text,'O genç erkek bir saattir parkta barfiks çekiyor.'::text),
(367353,40817,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az a fiatal férfi már egy órája ... a parkban.'::text,'húzódzkodik'::text,'húzódzkodik'::text,'húzódzkodik'::text,'Az a fiatal férfi már egy órája húzódzkodik a parkban.'::text),
(367356,40818,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Opa sah die Kamera und ... ihr zu, wie jeder Mann im Clip.'::text,'winkte'::text,'winkte gerade'::text,'hat gewinkt'::text,'Der Opa sah die Kamera und winkte ihr zu, wie jeder Mann im Clip.'::text),
(367360,40818,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дідусь побачив камеру і ... в неї, як кожен чоловік у ролику.'::text,'помахав'::text,'махав'::text,'помахав'::text,'Дідусь побачив камеру і помахав в неї, як кожен чоловік у ролику.'::text),
(367359,40818,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El abuelo vio la cámara y la ..., como todos los hombres del vídeo.'::text,'saludó'::text,'estaba saludando'::text,'ha saludado'::text,'El abuelo vio la cámara y la saludó, como todos los hombres del vídeo.'::text),
(367358,40818,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le grand-père a vu la caméra et lui ... signe, comme chaque homme de la vidéo.'::text,'a fait'::text,'faisait'::text,'a fait'::text,'Le grand-père a vu la caméra et lui a fait signe, comme chaque homme de la vidéo.'::text),
(367361,40818,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dede kamerayı gördü ve videodaki her erkek gibi ona el ...'::text,'salladı'::text,'sallıyordu'::text,'sallamış'::text,'Dede kamerayı gördü ve videodaki her erkek gibi ona el salladı.'::text),
(367362,40818,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nagypapa meglátta a kamerát, és ... neki, mint minden férfi a videóban.'::text,'integetett'::text,'integetett'::text,'integetett'::text,'A nagypapa meglátta a kamerát, és integetett neki, mint minden férfi a videóban.'::text),
(367365,40819,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, der Typ ... angeblich heute schon fünfzig Klimmzüge gemacht.'::text,'hat'::text,'hat'::text,'macht'::text,'Hör mal, der Typ hat angeblich heute schon fünfzig Klimmzüge gemacht.'::text),
(367369,40819,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, той чувак сьогодні вже ... п''ятдесят підтягувань.'::text,'зробив'::text,'робить'::text,'робить'::text,'Слухай, кажуть, той чувак сьогодні вже зробив п''ятдесят підтягувань.'::text),
(367368,40819,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer ese tío ya ... cincuenta dominadas hoy.'::text,'ha hecho'::text,'ha estado haciendo'::text,'está haciendo'::text,'Oye, al parecer ese tío ya ha hecho cincuenta dominadas hoy.'::text),
(367367,40819,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment ce mec ... déjà cinquante tractions aujourd''hui.'::text,'a fait'::text,'a fait'::text,'fait'::text,'Écoute, apparemment ce mec a fait déjà cinquante tractions aujourd''hui.'::text),
(367370,40819,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duyduğuma göre o adam bugün şimdiden elli barfiks ...'::text,'çekmiş'::text,'çekiyormuş'::text,'çekiyor'::text,'Dinle, duyduğuma göre o adam bugün şimdiden elli barfiks çekmiş.'::text),
(367371,40819,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, az a srác állítólag ma már ötven húzódzkodást ...'::text,'csinált'::text,'csinálgat'::text,'csinál'::text,'Figyelj, az a srác állítólag ma már ötven húzódzkodást csinált.'::text),
(367374,40820,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also angeblich ... jeder Mann in der Familie schon in die Kamera gewunken, bis wir ankamen.'::text,'hatte'::text,'hat'::text,'winkt'::text,'Okay, also angeblich hatte jeder Mann in der Familie schon in die Kamera gewunken, bis wir ankamen.'::text),
(367378,40820,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Отже, кажуть, поки ми приїхали, кожен чоловік у родині вже ... в камеру.'::text,'помахав'::text,'помахав'::text,'махає'::text,'Отже, кажуть, поки ми приїхали, кожен чоловік у родині вже помахав в камеру.'::text),
(367377,40820,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues al parecer, para cuando llegamos, todos los hombres de la familia ya ... a la cámara.'::text,'habían saludado'::text,'han saludado'::text,'saludan'::text,'Vale, pues al parecer, para cuando llegamos, todos los hombres de la familia ya habían saludado a la cámara.'::text),
(367376,40820,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok, donc apparemment, quand on est arrivés, chaque homme de la famille ... déjà fait coucou à la caméra.'::text,'avait'::text,'a'::text,'fait'::text,'Ok, donc apparemment, quand on est arrivés, chaque homme de la famille avait déjà fait coucou à la caméra.'::text),
(367379,40820,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, duyduğuma göre biz vardığımızda ailedeki her erkek kameraya çoktan el ...'::text,'sallamıştı'::text,'salladı'::text,'sallıyor'::text,'Tamam, duyduğuma göre biz vardığımızda ailedeki her erkek kameraya çoktan el sallamıştı.'::text),
(367380,40820,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval állítólag mire odaértünk, a családban minden férfi ... már a kamerának.'::text,'integetett'::text,'integetett'::text,'integet'::text,'Oké, szóval állítólag mire odaértünk, a családban minden férfi integetett már a kamerának.'::text),
(367383,40821,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der junge Mann seine Klimmzüge fertig hat, ... er für die Kamera.'::text,'posiert'::text,'posierte'::text,'posierte'::text,'Wenn der junge Mann seine Klimmzüge fertig hat, posiert er für die Kamera.'::text),
(367387,40821,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо молодий чоловік закінчить підтягування, він ... для камери.'::text,'позуватиме'::text,'позував би'::text,'позував'::text,'Якщо молодий чоловік закінчить підтягування, він позуватиме для камери.'::text),
(367386,40821,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el chico termina sus dominadas, ... para la cámara.'::text,'posará'::text,'posaría'::text,'posó'::text,'Si el chico termina sus dominadas, posará para la cámara.'::text),
(367385,40821,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le jeune homme finit ses tractions, il ... pour la caméra.'::text,'posera'::text,'poserait'::text,'a posé'::text,'Si le jeune homme finit ses tractions, il posera pour la caméra.'::text),
(367388,40821,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genç erkek barfikslerini bitirirse, kamera için poz ...'::text,'verecek'::text,'verirdi'::text,'verdi'::text,'Genç erkek barfikslerini bitirirse, kamera için poz verecek.'::text),
(367389,40821,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a fiatal férfi befejezi a húzódzkodást, ... a kamerának.'::text,'pózolni fog'::text,'pózolna'::text,'pózolt'::text,'Ha a fiatal férfi befejezi a húzódzkodást, pózolni fog a kamerának.'::text),
(367392,40822,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn jeder Mann im Park gleichzeitig Klimmzüge ..., würde die Stange natürlich brechen.'::text,'machte'::text,'macht'::text,'machen würde'::text,'Wenn jeder Mann im Park gleichzeitig Klimmzüge machte, würde die Stange natürlich brechen.'::text),
(367396,40822,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби кожен чоловік у парку ... підтягування одночасно, турнік, звісно, зламався б.'::text,'робив'::text,'робить'::text,'робив би'::text,'Якби кожен чоловік у парку робив підтягування одночасно, турнік, звісно, зламався б.'::text),
(367395,40822,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si todos los hombres del parque ... dominadas a la vez, la barra obviamente se rompería.'::text,'hicieran'::text,'hacen'::text,'harían'::text,'Si todos los hombres del parque hicieran dominadas a la vez, la barra obviamente se rompería.'::text),
(367394,40822,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si chaque homme du parc ... des tractions en même temps, la barre casserait évidemment.'::text,'faisait'::text,'fait'::text,'ferait'::text,'Si chaque homme du parc faisait des tractions en même temps, la barre casserait évidemment.'::text),
(367397,40822,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Parktaki her erkek aynı anda barfiks ..., bar tabii ki kırılırdı.'::text,'çekseydi'::text,'çekiyor'::text,'çekerdi'::text,'Parktaki her erkek aynı anda barfiks çekseydi, bar tabii ki kırılırdı.'::text),
(367398,40822,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a parkban minden férfi egyszerre ..., a rúd nyilván eltörne.'::text,'húzódzkodna'::text,'húzódzkodik'::text,'húzódzkodna'::text,'Ha a parkban minden férfi egyszerre húzódzkodna, a rúd nyilván eltörne.'::text),
(367410,40824,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Vater ... seinen kleinen Sohn auf die Schultern, und der älteste Mann winkte.'::text,'hob'::text,'wurde gehoben'::text,'hebend'::text,'Der Vater hob seinen kleinen Sohn auf die Schultern, und der älteste Mann winkte.'::text),
(367414,40824,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тато ... маленького сина собі на плечі, а найстарший чоловік помахав.'::text,'підняв'::text,'був піднятий'::text,'піднімаючи'::text,'Тато підняв маленького сина собі на плечі, а найстарший чоловік помахав.'::text),
(367413,40824,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El padre ... a su hijo pequeño a hombros, y el hombre más mayor saludó.'::text,'subió'::text,'fue subido'::text,'subiendo'::text,'El padre subió a su hijo pequeño a hombros, y el hombre más mayor saludó.'::text),
(367412,40824,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le père ... son petit garçon sur ses épaules, et l''homme le plus âgé a fait signe.'::text,'a hissé'::text,'a été hissé'::text,'hissant'::text,'Le père a hissé son petit garçon sur ses épaules, et l''homme le plus âgé a fait signe.'::text),
(367415,40824,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Baba küçük oğlunu omuzlarına ..., en yaşlı erkek de el salladı.'::text,'kaldırdı'::text,'kaldırıldı'::text,'kaldırarak'::text,'Baba küçük oğlunu omuzlarına kaldırdı, en yaşlı erkek de el salladı.'::text),
(367416,40824,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az apa a vállára ... a kisfiát, a legidősebb férfi pedig integetett.'::text,'emelte'::text,'emelve lett'::text,'emelve'::text,'Az apa a vállára emelte a kisfiát, a legidősebb férfi pedig integetett.'::text),
(367419,40825,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Typ ... nach all den Klimmzügen fertig sein, kein Witz, Bro.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Der Typ muss nach all den Klimmzügen fertig sein, kein Witz, Bro.'::text),
(367423,40825,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Той чувак ... бути втомленим після всіх тих підтягувань, без жартів, бро.'::text,'має'::text,'не може'::text,'мав би'::text,'Той чувак має бути втомленим після всіх тих підтягувань, без жартів, бро.'::text),
(367422,40825,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ese tío ... estar reventado después de tantas dominadas, sin mentir, bro.'::text,'debe de'::text,'no puede'::text,'debería'::text,'Ese tío debe de estar reventado después de tantas dominadas, sin mentir, bro.'::text),
(367421,40825,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce mec ... être crevé après toutes ces tractions, sans mentir, frérot.'::text,'doit'::text,'peut pas'::text,'devrait'::text,'Ce mec doit être crevé après toutes ces tractions, sans mentir, frérot.'::text),
(367424,40825,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O adam bunca barfiksten sonra yorgun ..., yemin ederim kanka.'::text,'olmalı'::text,'olamaz'::text,'olmalı'::text,'O adam bunca barfiksten sonra yorgun olmalı, yemin ederim kanka.'::text),
(367425,40825,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az a csávó ... fáradt lesz ennyi húzódzkodás után, komolyan, tesó.'::text,'biztos'::text,'kizárt, hogy'::text,'kéne, hogy'::text,'Az a csávó biztos fáradt lesz ennyi húzódzkodás után, komolyan, tesó.'::text),
(331104,36790,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er starrte ewig aufs Aquarium, also ... er noch nie so nah Haie gesehen haben.'::text,'muss'::text,'sollte'::text,'kann'::text,'Er starrte ewig aufs Aquarium, also muss er noch nie so nah Haie gesehen haben.'::text),
(331108,36790,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він цілу вічність дивився на акваріум, тож він ... ніколи раніше не бачив акул так близько.'::text,'напевно'::text,'мав би'::text,'не міг би'::text,'Він цілу вічність дивився на акваріум, тож він напевно ніколи раніше не бачив акул так близько.'::text),
(331107,36790,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se quedó mirando el acuario una eternidad, así que ... no haber visto nunca tiburones tan de cerca.'::text,'debía de'::text,'debería'::text,'no podía'::text,'Se quedó mirando el acuario una eternidad, así que debía de no haber visto nunca tiburones tan de cerca.'::text),
(331106,36790,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a fixé l''aquarium pendant des lustres, donc il ... de requins d''aussi près avant.'::text,'n''avait sûrement jamais vu'::text,'n''aurait jamais dû voir'::text,'ne peut pas avoir vu'::text,'Il a fixé l''aquarium pendant des lustres, donc il n''avait sûrement jamais vu de requins d''aussi près avant.'::text),
(331109,36790,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Akvaryuma uzun uzun baktı, yani daha önce köpekbalıklarını hiç bu kadar yakından ...'::text,'görmemiş olmalı'::text,'görmemeliydi'::text,'görmemiş olamaz'::text,'Akvaryuma uzun uzun baktı, yani daha önce köpekbalıklarını hiç bu kadar yakından görmemiş olmalı.'::text),
(331110,36790,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy örökkévalóságig bámulta az akváriumot, szóval ... még sosem látott ilyen közelről cápákat.'::text,'biztos'::text,'kellett volna'::text,'kizárt, hogy'::text,'Egy örökkévalóságig bámulta az akváriumot, szóval biztos még sosem látott ilyen közelről cápákat.'::text),
(331113,36791,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Selten ... ein so großes Aquarium in einem Einkaufszentrum.'::text,'sieht man'::text,'man sieht'::text,'sieht man'::text,'Selten sieht man ein so großes Aquarium in einem Einkaufszentrum.'::text),
(331117,36791,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Рідко ... такий великий акваріум у торговому центрі.'::text,'побачиш'::text,'побачиш'::text,'побачиш'::text,'Рідко побачиш такий великий акваріум у торговому центрі.'::text),
(331116,36791,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rara vez ... un acuario tan grande dentro de un centro comercial.'::text,'se ve'::text,'uno ve'::text,'ve uno'::text,'Rara vez se ve un acuario tan grande dentro de un centro comercial.'::text),
(331115,36791,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rarement ... un aquarium aussi grand dans un centre commercial.'::text,'voit-on'::text,'on voit'::text,'voit-on'::text,'Rarement voit-on un aquarium aussi grand dans un centre commercial.'::text),
(331118,36791,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir alışveriş merkezinde bu kadar büyük bir akvaryum nadiren ...'::text,'görülür'::text,'görülür'::text,'görülür'::text,'Bir alışveriş merkezinde bu kadar büyük bir akvaryum nadiren görülür.'::text),
(331119,36791,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ritkán ... ilyen nagy akváriumot egy bevásárlóközpontban.'::text,'látni'::text,'látni'::text,'látni'::text,'Ritkán látni ilyen nagy akváriumot egy bevásárlóközpontban.'::text),
(331122,36792,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Einkaufszentrum lässt Taucher jede Woche das riesige Aquarium ..., sonst Katastrophe!'::text,'putzen'::text,'putzen'::text,'putzend'::text,'Das Einkaufszentrum lässt Taucher jede Woche das riesige Aquarium putzen, sonst Katastrophe!'::text),
(331126,36792,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Торговий центр щотижня змушує дайверів ... гігантський акваріум, інакше катастрофа!'::text,'чистити'::text,'чистити'::text,'чистячи'::text,'Торговий центр щотижня змушує дайверів чистити гігантський акваріум, інакше катастрофа!'::text),
(331125,36792,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El centro comercial hace que los buzos ... el acuario gigante cada semana, o desastre!'::text,'limpien'::text,'limpien'::text,'limpiando'::text,'¡El centro comercial hace que los buzos limpien el acuario gigante cada semana, o desastre!'::text),
(331124,36792,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le centre commercial fait ... l''aquarium géant par des plongeurs chaque semaine, sinon c''est la catastrophe !'::text,'nettoyer'::text,'nettoyer'::text,'nettoyant'::text,'Le centre commercial fait nettoyer l''aquarium géant par des plongeurs chaque semaine, sinon c''est la catastrophe !'::text),
(331127,36792,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'AVM her hafta dev akvaryumu dalgıçlara ..., yoksa felaket!'::text,'temizletiyor'::text,'temizletiyor'::text,'temizleterek'::text,'AVM her hafta dev akvaryumu dalgıçlara temizletiyor, yoksa felaket!'::text),
(331128,36792,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A pláza minden héten ... búvárokkal az óriási akváriumot, különben katasztrófa!'::text,'kitakaríttatja'::text,'kitakaríttatja'::text,'takarítva'::text,'A pláza minden héten kitakaríttatja búvárokkal az óriási akváriumot, különben katasztrófa!'::text),
(331140,36794,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, angeblich hat das Aquarium, ... Haie über einem Tunnel schwimmen, Millionen gekostet.'::text,'dessen'::text,'das'::text,'das'::text,'Mädel, angeblich hat das Aquarium, dessen Haie über einem Tunnel schwimmen, Millionen gekostet.'::text),
(331144,36794,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, акваріум, ... акули плавають над тунелем, коштував мільйони.'::text,'чиї'::text,'який'::text,'що'::text,'Подруго, кажуть, акваріум, чиї акули плавають над тунелем, коштував мільйони.'::text),
(331143,36794,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer el acuario, ... tiburones nadan sobre un túnel, costó millones.'::text,'cuyos'::text,'el cual'::text,'que'::text,'Tía, al parecer el acuario, cuyos tiburones nadan sobre un túnel, costó millones.'::text),
(331142,36794,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment l''aquarium, ... les requins nagent au-dessus d''un tunnel, a coûté des millions.'::text,'dont'::text,'lequel'::text,'que'::text,'Meuf, apparemment l''aquarium, dont les requins nagent au-dessus d''un tunnel, a coûté des millions.'::text),
(331145,36794,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre köpekbalıklarının bir tünelin üzerinde ... akvaryum milyonlara mal olmuş.'::text,'yüzdüğü'::text,'yüzen'::text,'yüzen'::text,'Kızım, duyduğuma göre köpekbalıklarının bir tünelin üzerinde yüzdüğü akvaryum milyonlara mal olmuş.'::text),
(331146,36794,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag az akvárium, ... cápái egy alagút fölött úsznak, milliókba került.'::text,'amelynek a'::text,'amely'::text,'ami'::text,'Csajszi, állítólag az akvárium, amelynek a cápái egy alagút fölött úsznak, milliókba került.'::text),
(331149,36795,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, er hat mir erzählt, ... in dem Einkaufszentrum ist größer als sein ganzes Haus.'::text,'das Aquarium'::text,'ein Aquarium'::text,'Aquarium'::text,'Bestie, er hat mir erzählt, das Aquarium in dem Einkaufszentrum ist größer als sein ganzes Haus.'::text),
(331153,36795,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він сказав мені, що ... в тому торговому центрі більший за весь його будинок.'::text,'акваріум'::text,'акваріум'::text,'акваріум'::text,'Подруго, він сказав мені, що акваріум в тому торговому центрі більший за весь його будинок.'::text),
(331152,36795,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, me dijo que ... de ese centro comercial es más grande que toda su casa.'::text,'el acuario'::text,'un acuario'::text,'acuario'::text,'Amiga, me dijo que el acuario de ese centro comercial es más grande que toda su casa.'::text),
(331151,36795,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, il m''a dit que ... de ce centre commercial est plus grand que toute sa maison.'::text,'l''aquarium'::text,'un aquarium'::text,'aquarium'::text,'Ma belle, il m''a dit que l''aquarium de ce centre commercial est plus grand que toute sa maison.'::text),
(331154,36795,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bana o AVM''deki ... bütün evinden daha büyük olduğunu söyledi.'::text,'akvaryumun'::text,'bir akvaryumun'::text,'akvaryumun'::text,'Kanka, bana o AVM''deki akvaryumun bütün evinden daha büyük olduğunu söyledi.'::text),
(331155,36795,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy ... abban a plázában nagyobb, mint az egész háza.'::text,'az akvárium'::text,'egy akvárium'::text,'akvárium'::text,'Csajszi, azt mondta, hogy az akvárium abban a plázában nagyobb, mint az egész háza.'::text),
(331158,36796,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann starrte auf das Aquarium ... auf die Schlittschuhläufer auf dem Eis unten.'::text,'statt'::text,'stattdessen'::text,'trotz'::text,'Der Mann starrte auf das Aquarium statt auf die Schlittschuhläufer auf dem Eis unten.'::text),
(331162,36796,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік дивився на акваріум, ... на ковзанярів на льоду внизу.'::text,'а не'::text,'замість'::text,'попри'::text,'Чоловік дивився на акваріум, а не на ковзанярів на льоду внизу.'::text),
(331161,36796,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre miraba el acuario ... a los patinadores en el hielo de abajo.'::text,'en lugar de'::text,'en cambio'::text,'a pesar de'::text,'El hombre miraba el acuario en lugar de a los patinadores en el hielo de abajo.'::text),
(331160,36796,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme fixait l''aquarium ... les patineurs sur la glace en bas.'::text,'plutôt que'::text,'au lieu'::text,'malgré'::text,'L''homme fixait l''aquarium plutôt que les patineurs sur la glace en bas.'::text),
(331163,36796,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam aşağıdaki buzda kayanlara bakmak ... akvaryuma bakıyordu.'::text,'yerine'::text,'onun yerine'::text,'rağmen'::text,'Adam aşağıdaki buzda kayanlara bakmak yerine akvaryuma bakıyordu.'::text),
(331164,36796,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi az akváriumot bámulta a lenti jégen korcsolyázók ...'::text,'helyett'::text,'helyette'::text,'ellenére'::text,'A férfi az akváriumot bámulta a lenti jégen korcsolyázók helyett.'::text),
(331167,36797,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, er wusste nicht, dass im Aquarium echte Haie ..., kein Witz.'::text,'sein würden'::text,'sein werden'::text,'sind'::text,'Bro, er wusste nicht, dass im Aquarium echte Haie sein würden, kein Witz.'::text),
(331171,36797,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він не знав, що в акваріумі ... справжні акули, без жартів.'::text,'будуть'::text,'будуть'::text,'є'::text,'Бро, він не знав, що в акваріумі будуть справжні акули, без жартів.'::text),
(331170,36797,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, no sabía que el acuario ... tiburones de verdad, sin mentir.'::text,'tendría'::text,'tendrá'::text,'tiene'::text,'Bro, no sabía que el acuario tendría tiburones de verdad, sin mentir.'::text),
(331169,36797,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, il savait pas que l''aquarium ... de vrais requins dedans, sans mentir.'::text,'aurait'::text,'aura'::text,'a'::text,'Frérot, il savait pas que l''aquarium aurait de vrais requins dedans, sans mentir.'::text),
(331172,36797,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, akvaryumda gerçek köpekbalıkları ... bilmiyordu, yemin ederim.'::text,'olacağını'::text,'olacağını'::text,'olduğunu'::text,'Kanka, akvaryumda gerçek köpekbalıkları olacağını bilmiyordu, yemin ederim.'::text),
(331173,36797,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, nem tudta, hogy az akváriumban igazi cápák ..., komolyan.'::text,'lesznek'::text,'lesznek'::text,'vannak'::text,'Tesó, nem tudta, hogy az akváriumban igazi cápák lesznek, komolyan.'::text),
(331176,36798,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jeden Tag ... das Aquarium rund 3.000 Besucher an, die Haupteinnahmequelle des Einkaufszentrums.'::text,'zieht'::text,'zieht gerade'::text,'hat angezogen'::text,'Jeden Tag zieht das Aquarium rund 3.000 Besucher an, die Haupteinnahmequelle des Einkaufszentrums.'::text),
(331180,36798,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Щодня акваріум ... близько 3 000 відвідувачів — головне джерело доходу торгового центру.'::text,'приваблює'::text,'приваблює'::text,'привабив'::text,'Щодня акваріум приваблює близько 3 000 відвідувачів — головне джерело доходу торгового центру.'::text),
(331179,36798,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cada día, el acuario ... unos 3.000 visitantes, la principal fuente de ingresos del centro comercial.'::text,'atrae'::text,'está atrayendo'::text,'ha atraído'::text,'Cada día, el acuario atrae unos 3.000 visitantes, la principal fuente de ingresos del centro comercial.'::text),
(331178,36798,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque jour, l''aquarium ... environ 3 000 visiteurs, la principale source de revenus du centre commercial.'::text,'attire'::text,'attire'::text,'a attiré'::text,'Chaque jour, l''aquarium attire environ 3 000 visiteurs, la principale source de revenus du centre commercial.'::text),
(331181,36798,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Akvaryum her gün yaklaşık 3.000 ziyaretçi ..., bu da AVM''nin ana gelir kaynağı.'::text,'çekiyor'::text,'çekmekte'::text,'çekti'::text,'Akvaryum her gün yaklaşık 3.000 ziyaretçi çekiyor, bu da AVM''nin ana gelir kaynağı.'::text),
(331182,36798,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az akvárium naponta körülbelül 3000 látogatót ..., ez a pláza fő bevételi forrása.'::text,'vonz'::text,'vonz'::text,'vonzott'::text,'Az akvárium naponta körülbelül 3000 látogatót vonz, ez a pláza fő bevételi forrása.'::text),
(331185,36799,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... eine Stunde lang durch das Einkaufszentrum gelaufen, bevor er das Aquarium fand.'::text,'war'::text,'ist'::text,'läuft'::text,'Er war eine Stunde lang durch das Einkaufszentrum gelaufen, bevor er das Aquarium fand.'::text),
(331189,36799,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... торговим центром цілу годину, поки знайшов акваріум.'::text,'ходив'::text,'ходить'::text,'ходить'::text,'Він ходив торговим центром цілу годину, поки знайшов акваріум.'::text),
(331188,36799,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... por el centro comercial durante una hora antes de encontrar el acuario.'::text,'había estado caminando'::text,'ha estado caminando'::text,'camina'::text,'Él había estado caminando por el centro comercial durante una hora antes de encontrar el acuario.'::text),
(331187,36799,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... dans le centre commercial pendant une heure avant de trouver l''aquarium.'::text,'avait marché'::text,'a marché'::text,'marche'::text,'Il avait marché dans le centre commercial pendant une heure avant de trouver l''aquarium.'::text),
(331190,36799,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Akvaryumu bulmadan önce bir saat boyunca AVM''de ...'::text,'dolaşıyordu'::text,'dolaşıyor'::text,'dolaşır'::text,'Akvaryumu bulmadan önce bir saat boyunca AVM''de dolaşıyordu.'::text),
(331191,36799,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy órán át ... a plázában, mielőtt megtalálta az akváriumot.'::text,'mászkált'::text,'mászkál'::text,'mászkál'::text,'Egy órán át mászkált a plázában, mielőtt megtalálta az akváriumot.'::text),
(331194,36800,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis er geht, ... er jeden Hai im Aquarium gesehen haben.'::text,'wird'::text,'wird'::text,'sieht'::text,'Bis er geht, wird er jeden Hai im Aquarium gesehen haben.'::text),
(331198,36800,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки він піде, він ... кожну акулу в акваріумі.'::text,'побачить'::text,'побачить'::text,'бачить'::text,'Поки він піде, він побачить кожну акулу в акваріумі.'::text),
(331197,36800,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando se vaya, ... todos los tiburones del acuario.'::text,'habrá visto'::text,'verá'::text,'ve'::text,'Para cuando se vaya, habrá visto todos los tiburones del acuario.'::text),
(331196,36800,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici à ce qu''il parte, il ... chaque requin de l''aquarium.'::text,'aura vu'::text,'verra'::text,'voit'::text,'D''ici à ce qu''il parte, il aura vu chaque requin de l''aquarium.'::text),
(331199,36800,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gidene kadar akvaryumdaki her köpekbalığını ...'::text,'görmüş olacak'::text,'görecek'::text,'görüyor'::text,'Gidene kadar akvaryumdaki her köpekbalığını görmüş olacak.'::text),
(331200,36800,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire elmegy, ... az akvárium összes cápáját.'::text,'már látta'::text,'látni fogja'::text,'látja'::text,'Mire elmegy, már látta az akvárium összes cápáját.'::text),
(398883,44321,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, während die Band auf ihren Trompeten ..., hat die Menge wie verrückt Fahnen geschwenkt.'::text,'spielte'::text,'spielte'::text,'gespielt hat'::text,'Yo, während die Band auf ihren Trompeten spielte, hat die Menge wie verrückt Fahnen geschwenkt.'::text),
(398887,44321,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йоу, поки оркестр ... на трубах, натовп шалено махав прапорами.'::text,'грав'::text,'зіграв'::text,'зіграв'::text,'Йоу, поки оркестр грав на трубах, натовп шалено махав прапорами.'::text),
(398886,44321,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, mientras la banda ... sus trompetas, la gente agitaba banderas como loca.'::text,'tocaba'::text,'tocó'::text,'ha tocado'::text,'Oye, mientras la banda tocaba sus trompetas, la gente agitaba banderas como loca.'::text),
(398885,44321,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, pendant que la fanfare ... de la trompette, la foule agitait des drapeaux comme des fous.'::text,'jouait'::text,'a joué'::text,'a joué'::text,'Yo, pendant que la fanfare jouait de la trompette, la foule agitait des drapeaux comme des fous.'::text),
(398888,44321,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, bando trompetlerini ... kalabalık deli gibi bayrak sallıyordu.'::text,'çalarken'::text,'çaldığında'::text,'çalmışken'::text,'Yo, bando trompetlerini çalarken kalabalık deli gibi bayrak sallıyordu.'::text),
(398889,44321,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, amíg a zenekar ... a trombitákon, a tömeg őrülten lengette a zászlókat.'::text,'játszott'::text,'eljátszott'::text,'játszott'::text,'Figyu, amíg a zenekar játszott a trombitákon, a tömeg őrülten lengette a zászlókat.'::text),
(398892,44322,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, die Typen ... schon seit ungefähr ''ner Stunde auf der Straße in ihre Trompeten, kein Witz.'::text,'blasen'::text,'blasen'::text,'blasen'::text,'Alter, die Typen blasen schon seit ungefähr ''ner Stunde auf der Straße in ihre Trompeten, kein Witz.'::text),
(398896,44322,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, ці хлопці ... в труби на цій вулиці вже десь годину, без жартів.'::text,'дмуть'::text,'дмуть'::text,'дмуть'::text,'Чувак, ці хлопці дмуть в труби на цій вулиці вже десь годину, без жартів.'::text),
(398895,44322,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, estos chicos ... las trompetas por esta calle desde hace como una hora, sin mentir.'::text,'tocan'::text,'están tocando'::text,'tocan'::text,'Tío, estos chicos tocan las trompetas por esta calle desde hace como una hora, sin mentir.'::text),
(398894,44322,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, ces gars ... dans leurs trompettes dans cette rue depuis genre une heure, sans mentir.'::text,'soufflent'::text,'soufflent'::text,'soufflent'::text,'Mec, ces gars soufflent dans leurs trompettes dans cette rue depuis genre une heure, sans mentir.'::text),
(398897,44322,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu adamlar bu caddede bir saattir falan trompet ..., yemin ederim.'::text,'öttürüyor'::text,'öttürüyor'::text,'öttürür'::text,'Kanka, bu adamlar bu caddede bir saattir falan trompet öttürüyor, yemin ederim.'::text),
(398898,44322,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csávó, ezek a srácok már vagy egy órája ... a trombitájukat ezen az utcán, komolyan.'::text,'fújják'::text,'fújják'::text,'fújják'::text,'Csávó, ezek a srácok már vagy egy órája fújják a trombitájukat ezen az utcán, komolyan.'::text),
(398901,44323,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während 60 Musiker auf der Allee ihre Trompeten ..., blieb die Parade im Zeitplan.'::text,'bliesen'::text,'bliesen'::text,'geblasen haben'::text,'Während 60 Musiker auf der Allee ihre Trompeten bliesen, blieb die Parade im Zeitplan.'::text),
(398905,44323,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки 60 музикантів ... у труби на проспекті, парад ішов за графіком.'::text,'дули'::text,'дмухнули'::text,'дмухнули'::text,'Поки 60 музикантів дули у труби на проспекті, парад ішов за графіком.'::text),
(398904,44323,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras 60 músicos ... sus trompetas por la avenida, el desfile cumplió el cronograma.'::text,'tocaban'::text,'tocaron'::text,'han tocado'::text,'Mientras 60 músicos tocaban sus trompetas por la avenida, el desfile cumplió el cronograma.'::text),
(398903,44323,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant que 60 musiciens ... de la trompette sur l''avenue, le défilé a respecté son planning.'::text,'jouaient'::text,'ont joué'::text,'ont joué'::text,'Pendant que 60 musiciens jouaient de la trompette sur l''avenue, le défilé a respecté son planning.'::text),
(398906,44323,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'60 müzisyen caddede trompetlerini ..., geçit töreni zaman çizelgesine uydu.'::text,'çalarken'::text,'çaldığında'::text,'çalmışken'::text,'60 müzisyen caddede trompetlerini çalarken, geçit töreni zaman çizelgesine uydu.'::text),
(398907,44323,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amíg 60 zenész ... a trombitáját a sugárúton, a felvonulás tartotta az ütemtervet.'::text,'fújta'::text,'elfújta'::text,'fújta'::text,'Amíg 60 zenész fújta a trombitáját a sugárúton, a felvonulás tartotta az ütemtervet.'::text),
(398919,44325,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wie beobachtet, ... Trompeter bis zum Zurückfahren der Kamera den Großteil der Allee gefüllt.'::text,'hatten'::text,'haben'::text,'füllen'::text,'Wie beobachtet, hatten Trompeter bis zum Zurückfahren der Kamera den Großteil der Allee gefüllt.'::text),
(398923,44325,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Як спостерігалося, поки камера віддалилася, трубачі вже ... більшу частину проспекту.'::text,'заповнили'::text,'заповнили'::text,'заповнюють'::text,'Як спостерігалося, поки камера віддалилася, трубачі вже заповнили більшу частину проспекту.'::text),
(398922,44325,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Según lo observado, para cuando la cámara se alejó, los trompetistas ... casi toda la avenida.'::text,'habían llenado'::text,'han llenado'::text,'llenan'::text,'Según lo observado, para cuando la cámara se alejó, los trompetistas habían llenado casi toda la avenida.'::text),
(398921,44325,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Comme observé, quand la caméra a reculé, les trompettistes ... la majeure partie de l''avenue.'::text,'avaient rempli'::text,'ont rempli'::text,'remplissent'::text,'Comme observé, quand la caméra a reculé, les trompettistes avaient rempli la majeure partie de l''avenue.'::text),
(398924,44325,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gözlemlendiği üzere, kamera geri çekildiğinde trompetçiler caddenin çoğunu çoktan ...'::text,'doldurmuştu'::text,'doldurdu'::text,'dolduruyor'::text,'Gözlemlendiği üzere, kamera geri çekildiğinde trompetçiler caddenin çoğunu çoktan doldurmuştu.'::text),
(398925,44325,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A megfigyelés szerint mire a kamera hátrébb húzódott, a trombitások már ... a sugárút nagy részét.'::text,'megtöltötték'::text,'megtöltötték'::text,'megtöltik'::text,'A megfigyelés szerint mire a kamera hátrébb húzódott, a trombitások már megtöltötték a sugárút nagy részét.'::text),
(398928,44326,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen im Morgengrauen werden diese Trompeten vor meinem Fenster ..., und ich werde nie wieder schlafen!'::text,'dröhnen'::text,'dröhnen'::text,'dröhnen'::text,'Morgen im Morgengrauen werden diese Trompeten vor meinem Fenster dröhnen, und ich werde nie wieder schlafen!'::text),
(398932,44326,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра на світанку ці труби ... під моїм вікном, і я більше ніколи не засну!'::text,'ревітимуть'::text,'заревуть'::text,'ревуть'::text,'Завтра на світанку ці труби ревітимуть під моїм вікном, і я більше ніколи не засну!'::text),
(398931,44326,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Mañana al amanecer esas trompetas ... bajo mi ventana y no volveré a dormir nunca!'::text,'estarán sonando'::text,'sonarán'::text,'suenan'::text,'¡Mañana al amanecer esas trompetas estarán sonando bajo mi ventana y no volveré a dormir nunca!'::text),
(398930,44326,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à l''aube, ces trompettes ... sous ma fenêtre, et je ne dormirai plus jamais !'::text,'seront en train de hurler'::text,'hurleront'::text,'hurlent'::text,'Demain à l''aube, ces trompettes seront en train de hurler sous ma fenêtre, et je ne dormirai plus jamais !'::text),
(398933,44326,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın şafakta o trompetler penceremin önünde ... ve ben bir daha asla uyuyamayacağım!'::text,'ötüyor olacak'::text,'ötecek'::text,'ötüyor'::text,'Yarın şafakta o trompetler penceremin önünde ötüyor olacak ve ben bir daha asla uyuyamayacağım!'::text),
(398934,44326,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap hajnalban azok a trombiták ... az ablakom alatt, és soha többé nem fogok aludni!'::text,'harsogni fognak'::text,'harsognak majd'::text,'harsognak'::text,'Holnap hajnalban azok a trombiták harsogni fognak az ablakom alatt, és soha többé nem fogok aludni!'::text),
(398937,44327,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Nachbarin schrie, die Trompeten ... ihr den ganzen Morgen ruiniert!'::text,'hätten'::text,'haben'::text,'ruinieren'::text,'Die Nachbarin schrie, die Trompeten hätten ihr den ganzen Morgen ruiniert!'::text),
(398941,44327,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сусідка кричала, що труби ... їй увесь ранок!'::text,'зіпсували'::text,'зіпсували'::text,'псують'::text,'Сусідка кричала, що труби зіпсували їй увесь ранок!'::text),
(398940,44327,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La vecina gritó que las trompetas le ... toda la mañana!'::text,'habían arruinado'::text,'han arruinado'::text,'arruinan'::text,'¡La vecina gritó que las trompetas le habían arruinado toda la mañana!'::text),
(398939,44327,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La voisine a hurlé que les trompettes ... toute sa matinée !'::text,'avaient gâché'::text,'ont gâché'::text,'gâchent'::text,'La voisine a hurlé que les trompettes avaient gâché toute sa matinée !'::text),
(398942,44327,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Komşu kadın, trompetlerin bütün sabahını ... bağırdı!'::text,'mahvettiğini'::text,'mahvettiğini'::text,'mahvettiğini'::text,'Komşu kadın, trompetlerin bütün sabahını mahvettiğini bağırdı!'::text),
(398943,44327,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szomszéd azt kiabálta, hogy a trombiták ... az egész délelőttjét!'::text,'tönkretették'::text,'tönkretették'::text,'tönkreteszik'::text,'A szomszéd azt kiabálta, hogy a trombiták tönkretették az egész délelőttjét!'::text),
(398946,44328,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als Junge ... er jeden Abend im Garten Trompete.'::text,'übte'::text,'übte'::text,'war gewohnt zu üben'::text,'Als Junge übte er jeden Abend im Garten Trompete.'::text),
(398950,44328,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хлопчиком він ... щовечора в саду на трубі.'::text,'вправлявся'::text,'вправлявся'::text,'звик вправлятися'::text,'Хлопчиком він вправлявся щовечора в саду на трубі.'::text),
(398949,44328,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De niño, ... la trompeta en el jardín todas las tardes.'::text,'practicaba'::text,'solía practicar'::text,'estaba acostumbrado a practicar'::text,'De niño, practicaba la trompeta en el jardín todas las tardes.'::text),
(398948,44328,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Enfant, il ... la trompette dans le jardin tous les soirs.'::text,'travaillait'::text,'travaillait'::text,'avait l''habitude de travailler'::text,'Enfant, il travaillait la trompette dans le jardin tous les soirs.'::text),
(398951,44328,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocukken her akşam bahçede trompet ...'::text,'çalışırdı'::text,'çalışırdı'::text,'çalışmaya alışkındı'::text,'Çocukken her akşam bahçede trompet çalışırdı.'::text),
(398952,44328,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kisfiúként minden este ... trombitán a kertben.'::text,'gyakorolt'::text,'gyakorolt'::text,'hozzá volt szokva, hogy gyakoroljon'::text,'Kisfiúként minden este gyakorolt trombitán a kertben.'::text),
(398955,44329,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Musiker hören nicht auf, ihre Trompeten zu ..., während sie die Straße entlanggehen.'::text,'spielen'::text,'spielen'::text,'spielen'::text,'Die Musiker hören nicht auf, ihre Trompeten zu spielen, während sie die Straße entlanggehen.'::text),
(398959,44329,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Музиканти продовжують ... на трубах, поки йдуть вулицею.'::text,'грати'::text,'грати'::text,'грати'::text,'Музиканти продовжують грати на трубах, поки йдуть вулицею.'::text),
(398958,44329,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los músicos siguen ... sus trompetas mientras recorren la calle.'::text,'tocando'::text,'tocar'::text,'tocar'::text,'Los músicos siguen tocando sus trompetas mientras recorren la calle.'::text),
(398957,44329,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les musiciens continuent de ... de la trompette en descendant la rue.'::text,'jouer'::text,'jouer'::text,'jouer'::text,'Les musiciens continuent de jouer de la trompette en descendant la rue.'::text),
(398960,44329,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Müzisyenler caddede yürürken trompetlerini ... devam ediyor.'::text,'çalmaya'::text,'çalmak'::text,'çal'::text,'Müzisyenler caddede yürürken trompetlerini çalmaya devam ediyor.'::text),
(398961,44329,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A zenészek tovább ... a trombitájukon, miközben végigvonulnak az utcán.'::text,'játszanak'::text,'játszani'::text,'játszanak'::text,'A zenészek tovább játszanak a trombitájukon, miközben végigvonulnak az utcán.'::text),
(398973,44331,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Band ... drei Stunden lang in ihre Trompeten geblasen, bevor die Parade endete. Klar, nur ein Warm-up.'::text,'hatte'::text,'blies'::text,'hat'::text,'Die Band hatte drei Stunden lang in ihre Trompeten geblasen, bevor die Parade endete. Klar, nur ein Warm-up.'::text),
(398977,44331,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Оркестр ... у труби три години, поки парад не скінчився. Явно просто розминка.'::text,'дув'::text,'дув'::text,'дме'::text,'Оркестр дув у труби три години, поки парад не скінчився. Явно просто розминка.'::text),
(398976,44331,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La banda ... las trompetas durante tres horas antes de que acabara el desfile. Claramente un calentamiento.'::text,'había estado tocando'::text,'estaba tocando'::text,'ha estado tocando'::text,'La banda había estado tocando las trompetas durante tres horas antes de que acabara el desfile. Claramente un calentamiento.'::text),
(398975,44331,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La fanfare ... de la trompette pendant trois heures avant la fin du défilé. Clairement un échauffement.'::text,'avait joué'::text,'jouait'::text,'a joué'::text,'La fanfare avait joué de la trompette pendant trois heures avant la fin du défilé. Clairement un échauffement.'::text),
(398978,44331,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Geçit töreni bitmeden önce bando üç saat boyunca trompetlerini ..., belli ki sadece ısınma turuydu.'::text,'çalıyordu'::text,'çalıyordu'::text,'çalıyor'::text,'Geçit töreni bitmeden önce bando üç saat boyunca trompetlerini çalıyordu, belli ki sadece ısınma turuydu.'::text),
(398979,44331,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A zenekar három órán át ... a trombitákat, mielőtt véget ért a felvonulás. Nyilván csak bemelegítés.'::text,'fújta'::text,'fújta'::text,'fújja'::text,'A zenekar három órán át fújta a trombitákat, mielőtt véget ért a felvonulás. Nyilván csak bemelegítés.'::text),
(329700,36634,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... gerade durch den Gewürzgang, als seine Erinnerung an das Meeting um 15 Uhr summte.'::text,'ging'::text,'ging'::text,'ist gegangen'::text,'Er ging gerade durch den Gewürzgang, als seine Erinnerung an das Meeting um 15 Uhr summte.'::text),
(329704,36634,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... проходом зі спеціями, коли завібрувало нагадування про зустріч о 15:00.'::text,'ішов'::text,'пройшов'::text,'пройшов'::text,'Він ішов проходом зі спеціями, коли завібрувало нагадування про зустріч о 15:00.'::text),
(329703,36634,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... por el pasillo de las especias cuando sonó el recordatorio de su reunión de las 15:00.'::text,'iba'::text,'fue'::text,'ha ido'::text,'Él iba por el pasillo de las especias cuando sonó el recordatorio de su reunión de las 15:00.'::text),
(329702,36634,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... dans l''allée des épices quand le rappel de sa réunion de 15 h a vibré.'::text,'marchait'::text,'a marché'::text,'a marché'::text,'Il marchait dans l''allée des épices quand le rappel de sa réunion de 15 h a vibré.'::text),
(329705,36634,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saat 15:00 toplantı hatırlatıcısı titrediğinde baharat koridorunda ...'::text,'yürüyordu'::text,'yürüdü'::text,'yürümüş'::text,'Saat 15:00 toplantı hatırlatıcısı titrediğinde baharat koridorunda yürüyordu.'::text),
(329706,36634,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp a fűszersoron ..., amikor megrezgett a 15:00-s megbeszélés emlékeztetője.'::text,'sétált'::text,'végigsétált'::text,'végigsétált'::text,'Épp a fűszersoron sétált, amikor megrezgett a 15:00-s megbeszélés emlékeztetője.'::text),
(329709,36635,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... seit zehn Minuten diesen Gang entlang, also ist er noch im Gang.'::text,'geht'::text,'geht'::text,'geht'::text,'Er geht seit zehn Minuten diesen Gang entlang, also ist er noch im Gang.'::text),
(329713,36635,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... цим проходом уже десять хвилин, тож він досі в проході.'::text,'іде'::text,'іде'::text,'ходить'::text,'Він іде цим проходом уже десять хвилин, тож він досі в проході.'::text),
(329712,36635,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... por este pasillo desde hace diez minutos, así que todavía está en el pasillo.'::text,'camina'::text,'está caminando'::text,'camina'::text,'Él camina por este pasillo desde hace diez minutos, así que todavía está en el pasillo.'::text),
(329711,36635,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... dans cette allée depuis dix minutes, donc il est encore dans l''allée.'::text,'marche'::text,'marche'::text,'marche'::text,'Il marche dans cette allée depuis dix minutes, donc il est encore dans l''allée.'::text),
(329714,36635,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On dakikadır bu koridorda ..., yani hâlâ koridorda.'::text,'yürüyor'::text,'yürüyor'::text,'yürür'::text,'On dakikadır bu koridorda yürüyor, yani hâlâ koridorda.'::text),
(329715,36635,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tíz perce ... ezen a soron, tehát még mindig a soron van.'::text,'sétál'::text,'sétál'::text,'sétál'::text,'Tíz perce sétál ezen a soron, tehát még mindig a soron van.'::text),
(329718,36636,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während er den Gang ..., wurde auf beiden Seiten eine Vielzahl an Gewürzen beobachtet.'::text,'entlangging'::text,'entlangging'::text,'entlanggegangen ist'::text,'Während er den Gang entlangging, wurde auf beiden Seiten eine Vielzahl an Gewürzen beobachtet.'::text),
(329722,36636,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки він ... проходом, з обох боків спостерігалося розмаїття спецій.'::text,'ішов'::text,'пройшов'::text,'пройшов'::text,'Поки він ішов проходом, з обох боків спостерігалося розмаїття спецій.'::text),
(329721,36636,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras ... por el pasillo, se observó una variedad de especias a ambos lados.'::text,'caminaba'::text,'caminó'::text,'ha caminado'::text,'Mientras caminaba por el pasillo, se observó una variedad de especias a ambos lados.'::text),
(329720,36636,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant qu''il ... l''allée, une variété d''épices a été observée des deux côtés.'::text,'descendait'::text,'a descendu'::text,'a descendu'::text,'Pendant qu''il descendait l''allée, une variété d''épices a été observée des deux côtés.'::text),
(329723,36636,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O koridorda ... her iki tarafta çeşitli baharatlar gözlemlendi.'::text,'yürürken'::text,'yürüdüğünde'::text,'yürümüşken'::text,'O koridorda yürürken her iki tarafta çeşitli baharatlar gözlemlendi.'::text),
(329724,36636,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben ... a soron, mindkét oldalon sokféle fűszer volt megfigyelhető.'::text,'végigsétált'::text,'végigsétált'::text,'végigsétált'::text,'Miközben végigsétált a soron, mindkét oldalon sokféle fűszer volt megfigyelhető.'::text),
(329727,36637,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... schon dreimal durch diesen Gang gelaufen und filmst ihn immer noch wie ein Profi.'::text,'bist'::text,'bist'::text,'läufst'::text,'Ehrlich, du bist schon dreimal durch diesen Gang gelaufen und filmst ihn immer noch wie ein Profi.'::text),
(329731,36637,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти вже тричі ... цим проходом і досі знімаєш його як профі.'::text,'пройшов'::text,'проходив'::text,'проходиш'::text,'Чесно, ти вже тричі пройшов цим проходом і досі знімаєш його як профі.'::text),
(329730,36637,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En serio, ya ... por este pasillo tres veces y aún lo grabas como un pro.'::text,'has pasado'::text,'has estado pasando'::text,'pasas'::text,'En serio, ya has pasado por este pasillo tres veces y aún lo grabas como un pro.'::text),
(329729,36637,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... trois fois cette allée et tu la filmes encore comme un pro.'::text,'as déjà parcouru'::text,'as déjà parcouru'::text,'parcours'::text,'Franchement, tu as déjà parcouru trois fois cette allée et tu la filmes encore comme un pro.'::text),
(329732,36637,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, bu koridordan üç kez ... ve hâlâ bir profesyonel gibi çekiyorsun.'::text,'geçtin'::text,'geçip duruyorsun'::text,'geçiyorsun'::text,'Açıkçası, bu koridordan üç kez geçtin ve hâlâ bir profesyonel gibi çekiyorsun.'::text),
(329733,36637,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, már háromszor ... végig ezen a soron, és még mindig úgy veszed fel, mint egy profi.'::text,'sétáltál'::text,'sétálgattál'::text,'sétálsz'::text,'Őszintén, már háromszor sétáltál végig ezen a soron, és még mindig úgy veszed fel, mint egy profi.'::text),
(329736,36638,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis du beim Gewürzgang warst, ... du schon eine ganze Tüte Orangen gekauft. Respekt.'::text,'hattest'::text,'hast'::text,'kaufst'::text,'Bis du beim Gewürzgang warst, hattest du schon eine ganze Tüte Orangen gekauft. Respekt.'::text),
(329740,36638,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки ти дійшов до проходу зі спеціями, ти вже ... цілу сітку апельсинів. Повага.'::text,'купив'::text,'купив'::text,'купуєш'::text,'Поки ти дійшов до проходу зі спеціями, ти вже купив цілу сітку апельсинів. Повага.'::text),
(329739,36638,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando llegaste al pasillo de las especias, ya ... una bolsa entera de naranjas. Respeto.'::text,'habías comprado'::text,'has comprado'::text,'compras'::text,'Para cuando llegaste al pasillo de las especias, ya habías comprado una bolsa entera de naranjas. Respeto.'::text),
(329738,36638,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand t''es arrivé à l''allée des épices, tu ... un sac entier d''oranges. Respect.'::text,'avais déjà acheté'::text,'as acheté'::text,'achètes'::text,'Quand t''es arrivé à l''allée des épices, tu avais déjà acheté un sac entier d''oranges. Respect.'::text),
(329741,36638,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Helal: baharat koridoruna vardığında bir file dolusu portakalı çoktan ...'::text,'almıştın'::text,'aldın'::text,'alıyorsun'::text,'Helal: baharat koridoruna vardığında bir file dolusu portakalı çoktan almıştın.'::text),
(329742,36638,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a fűszersorhoz értél, már ... egy egész zacskó narancsot. Respekt.'::text,'vettél'::text,'vettél'::text,'veszel'::text,'Mire a fűszersorhoz értél, már vettél egy egész zacskó narancsot. Respekt.'::text),
(329745,36639,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn du noch einen Gang filmst, ... ich mir jedes Video an, das du postest, ganz ehrlich.'::text,'schaue'::text,'schaute'::text,'schaute'::text,'Wenn du noch einen Gang filmst, schaue ich mir jedes Video an, das du postest, ganz ehrlich.'::text),
(329749,36639,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо ти знімеш ще один прохід, я ... кожне відео, яке ти викладеш, не буду брехати.'::text,'дивитимусь'::text,'дивився б'::text,'дивився'::text,'Якщо ти знімеш ще один прохід, я дивитимусь кожне відео, яке ти викладеш, не буду брехати.'::text),
(329748,36639,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si grabas un pasillo más, ... todos los vídeos que subas, no voy a mentir.'::text,'veré'::text,'vería'::text,'vi'::text,'Si grabas un pasillo más, veré todos los vídeos que subas, no voy a mentir.'::text),
(329747,36639,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tu filmes encore une allée, je ... toutes les vidéos que tu postes, je vais pas mentir.'::text,'regarderai'::text,'regarderais'::text,'ai regardé'::text,'Si tu filmes encore une allée, je regarderai toutes les vidéos que tu postes, je vais pas mentir.'::text),
(329750,36639,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir koridor daha çekersen paylaştığın her videoyu ..., yalan yok.'::text,'izleyeceğim'::text,'izlerdim'::text,'izledim'::text,'Bir koridor daha çekersen paylaştığın her videoyu izleyeceğim, yalan yok.'::text),
(329751,36639,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha még egy sort felveszel, ... minden videódat, amit posztolsz, nem fogok hazudni.'::text,'megnézem'::text,'megnézném'::text,'megnéztem'::text,'Ha még egy sort felveszel, megnézem minden videódat, amit posztolsz, nem fogok hazudni.'::text),
(329754,36640,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Gang breiter wäre, ... die Stände mehr Platz für Gewürze.'::text,'hätten'::text,'haben'::text,'haben'::text,'Wenn der Gang breiter wäre, hätten die Stände mehr Platz für Gewürze.'::text),
(329758,36640,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби прохід був ширшим, у ятках ... більше місця для спецій.'::text,'було б'::text,'буде'::text,'є'::text,'Якби прохід був ширшим, у ятках було б більше місця для спецій.'::text),
(329757,36640,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el pasillo fuera más ancho, los puestos ... más espacio para las especias.'::text,'tendrían'::text,'tendrán'::text,'tienen'::text,'Si el pasillo fuera más ancho, los puestos tendrían más espacio para las especias.'::text),
(329756,36640,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''allée était plus large, les stands ... plus de place pour les épices.'::text,'auraient'::text,'auront'::text,'ont'::text,'Si l''allée était plus large, les stands auraient plus de place pour les épices.'::text),
(329759,36640,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Koridor daha geniş olsaydı, tezgâhların baharatlar için daha fazla yeri ...'::text,'olurdu'::text,'olacak'::text,'var'::text,'Koridor daha geniş olsaydı, tezgâhların baharatlar için daha fazla yeri olurdu.'::text),
(329760,36640,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha szélesebb lenne a sor, a standoknak több helyük ... a fűszereknek.'::text,'lenne'::text,'lesz'::text,'van'::text,'Ha szélesebb lenne a sor, a standoknak több helyük lenne a fűszereknek.'::text),
(329763,36641,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Gewürzgang ... vor Hunderten von Jahren unter einem Steindach gebaut.'::text,'wurde'::text,'wird'::text,'baute'::text,'Der Gewürzgang wurde vor Hunderten von Jahren unter einem Steindach gebaut.'::text),
(329767,36641,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Прохід зі спеціями ... під кам''яним дахом сотні років тому.'::text,'був збудований'::text,'будується'::text,'збудував'::text,'Прохід зі спеціями був збудований під кам''яним дахом сотні років тому.'::text),
(329766,36641,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El pasillo de las especias ... bajo un techo de piedra hace cientos de años.'::text,'fue construido'::text,'es construido'::text,'construyó'::text,'El pasillo de las especias fue construido bajo un techo de piedra hace cientos de años.'::text),
(329765,36641,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''allée des épices ... sous un toit de pierre il y a des centaines d''années.'::text,'a été construite'::text,'est construite'::text,'a construit'::text,'L''allée des épices a été construite sous un toit de pierre il y a des centaines d''années.'::text),
(329768,36641,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Baharat koridoru yüzlerce yıl önce taş bir çatının altına ...'::text,'inşa edildi'::text,'inşa ediliyor'::text,'inşa etti'::text,'Baharat koridoru yüzlerce yıl önce taş bir çatının altına inşa edildi.'::text),
(329769,36641,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fűszersort több száz évvel ezelőtt ... egy kőtető alá.'::text,'építették'::text,'építik'::text,'építette'::text,'A fűszersort több száz évvel ezelőtt építették egy kőtető alá.'::text),
(329772,36642,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Gang ... auf beiden Seiten von Reihen von Gewürzständen gesäumt.'::text,'wird'::text,'säumt'::text,'säumend'::text,'Der Gang wird auf beiden Seiten von Reihen von Gewürzständen gesäumt.'::text),
(329776,36642,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Прохід з обох боків ... рядами яток зі спеціями.'::text,'обрамлений'::text,'обрамлює'::text,'обрамлюючи'::text,'Прохід з обох боків обрамлений рядами яток зі спеціями.'::text),
(329775,36642,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El pasillo ... a ambos lados por hileras de puestos de especias.'::text,'está flanqueado'::text,'flanquea'::text,'flanqueando'::text,'El pasillo está flanqueado a ambos lados por hileras de puestos de especias.'::text),
(329774,36642,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''allée ... des deux côtés de rangées d''étals d''épices.'::text,'est bordée'::text,'borde'::text,'bordant'::text,'L''allée est bordée des deux côtés de rangées d''étals d''épices.'::text),
(329777,36642,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Koridor her iki yandan sıra sıra baharat tezgâhlarıyla ...'::text,'çevrili'::text,'çeviriyor'::text,'çevirerek'::text,'Koridor her iki yandan sıra sıra baharat tezgâhlarıyla çevrili.'::text),
(329778,36642,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sort mindkét oldalon fűszerstandok sorai ...'::text,'szegélyezik'::text,'szegélyezi'::text,'szegélyezve'::text,'A sort mindkét oldalon fűszerstandok sorai szegélyezik.'::text),
(329781,36643,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, dieser Gewürzgang ... krass riechen, kein Witz.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Bro, dieser Gewürzgang muss krass riechen, kein Witz.'::text),
(329785,36643,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, цей прохід зі спеціями ... пахнути шалено, без жартів.'::text,'має'::text,'не може'::text,'мав би'::text,'Бро, цей прохід зі спеціями має пахнути шалено, без жартів.'::text),
(329784,36643,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, este pasillo de especias ... oler brutal, sin mentir.'::text,'debe de'::text,'no puede'::text,'debería'::text,'Bro, este pasillo de especias debe de oler brutal, sin mentir.'::text),
(329783,36643,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, cette allée d''épices ... sentir de ouf, sans mentir.'::text,'doit'::text,'peut pas'::text,'devrait'::text,'Frérot, cette allée d''épices doit sentir de ouf, sans mentir.'::text),
(329786,36643,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu baharat koridoru acayip kokuyor ..., yemin ederim.'::text,'olmalı'::text,'olamaz'::text,'olmalı'::text,'Kanka, bu baharat koridoru acayip kokuyor olmalı, yemin ederim.'::text),
(329787,36643,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ez a fűszersor ... durva illatú, komolyan.'::text,'biztos'::text,'kizárt, hogy'::text,'elvileg'::text,'Tesó, ez a fűszersor biztos durva illatú, komolyan.'::text),
(367977,40887,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Ehe, ... mit einem Kuss unter einem Blumenbogen begann, wurde von jedem Gast bejubelt.'::text,'die'::text,'die'::text,'wer'::text,'Ihre Ehe, die mit einem Kuss unter einem Blumenbogen begann, wurde von jedem Gast bejubelt.'::text),
(367981,40887,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Їхній шлюб, ... почався з поцілунку під квітковою аркою, вітав кожен гість.'::text,'який'::text,'що'::text,'хто'::text,'Їхній шлюб, який почався з поцілунку під квітковою аркою, вітав кожен гість.'::text),
(367980,40887,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su matrimonio, ... empezó con un beso bajo un arco de flores, fue aclamado por todos los invitados.'::text,'que'::text,'que'::text,'quien'::text,'Su matrimonio, que empezó con un beso bajo un arco de flores, fue aclamado por todos los invitados.'::text),
(367979,40887,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Leur mariage, ... a commencé par un baiser sous une arche de fleurs, a été acclamé par tous les invités.'::text,'qui'::text,'qui'::text,'qui'::text,'Leur mariage, qui a commencé par un baiser sous une arche de fleurs, a été acclamé par tous les invités.'::text),
(367982,40887,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çiçekli bir kemerin altında bir öpücükle ... evlilikleri, her misafir tarafından alkışlandı.'::text,'başlayan'::text,'başlayan'::text,'başlayan'::text,'Çiçekli bir kemerin altında bir öpücükle başlayan evlilikleri, her misafir tarafından alkışlandı.'::text),
(367983,40887,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A házasságukat, ... egy virágív alatti csókkal kezdődött, minden vendég megéljenezte.'::text,'amely'::text,'ami'::text,'aki'::text,'A házasságukat, amely egy virágív alatti csókkal kezdődött, minden vendég megéljenezte.'::text),
(368121,40903,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... ich gerade auf dieser schrecklichen Matratze, und mein Rücken wird zerstört sein!'::text,'schlafe'::text,'schlafe'::text,'schlafe'::text,'Morgen um diese Zeit schlafe ich gerade auf dieser schrecklichen Matratze, und mein Rücken wird zerstört sein!'::text),
(368125,40903,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час я ... на цьому жахливому матраці, і моя спина буде знищена!'::text,'спатиму'::text,'спатиму'::text,'сплю'::text,'Завтра в цей час я спатиму на цьому жахливому матраці, і моя спина буде знищена!'::text),
(368124,40903,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Mañana a esta hora ... en este colchón horrible y mi espalda quedará destrozada!'::text,'estaré durmiendo'::text,'dormiré'::text,'duermo'::text,'¡Mañana a esta hora estaré durmiendo en este colchón horrible y mi espalda quedará destrozada!'::text),
(368123,40903,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à cette heure-ci, je ... sur cet horrible matelas, et mon dos sera détruit !'::text,'serai en train de dormir'::text,'dormirai'::text,'dors'::text,'Demain à cette heure-ci, je serai en train de dormir sur cet horrible matelas, et mon dos sera détruit !'::text),
(368126,40903,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte bu berbat yatakta ... ve sırtım mahvolacak!'::text,'uyuyor olacağım'::text,'uyuyacağım'::text,'uyuyorum'::text,'Yarın bu saatte bu berbat yatakta uyuyor olacağım ve sırtım mahvolacak!'::text),
(368127,40903,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor ezen a borzalmas matracon ..., és a hátam tönkre lesz téve!'::text,'fogok aludni'::text,'alszom majd'::text,'alszom'::text,'Holnap ilyenkor ezen a borzalmas matracon fogok aludni, és a hátam tönkre lesz téve!'::text),
(368139,40905,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn eine Matratze zu hart ..., schlafen die Leute schlecht darauf.'::text,'ist'::text,'sein wird'::text,'wäre'::text,'Wenn eine Matratze zu hart ist, schlafen die Leute schlecht darauf.'::text),
(368143,40905,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо матрац ... надто твердий, люди погано на ньому сплять.'::text,''::text,'буде'::text,'був би'::text,'Якщо матрац надто твердий, люди погано на ньому сплять.'::text),
(368142,40905,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un colchón ... demasiado duro, la gente duerme mal en él.'::text,'es'::text,'será'::text,'sería'::text,'Si un colchón es demasiado duro, la gente duerme mal en él.'::text),
(368141,40905,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un matelas ... trop dur, les gens dorment mal dessus.'::text,'est'::text,'sera'::text,'serait'::text,'Si un matelas est trop dur, les gens dorment mal dessus.'::text),
(368144,40905,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir yatak çok sert ..., insanlar üzerinde kötü uyur.'::text,'olursa'::text,'olacaksa'::text,'olsaydı'::text,'Bir yatak çok sert olursa, insanlar üzerinde kötü uyur.'::text),
(368145,40905,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy matrac túl kemény ..., az emberek rosszul alszanak rajta.'::text,''::text,'lesz'::text,'lenne'::text,'Ha egy matrac túl kemény, az emberek rosszul alszanak rajta.'::text),
(368148,40906,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Matratze, ... sie sich am Ende fallen lässt, ist die größte im Laden.'::text,'auf die'::text,'auf die'::text,'wo'::text,'Die Matratze, auf die sie sich am Ende fallen lässt, ist die größte im Laden.'::text),
(368152,40906,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Матрац, ... вона плюхається наприкінці, найбільший у магазині.'::text,'на який'::text,'на кого'::text,'де'::text,'Матрац, на який вона плюхається наприкінці, найбільший у магазині.'::text),
(368151,40906,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El colchón ... se deja caer al final es el más grande de la tienda.'::text,'sobre el que'::text,'sobre quien'::text,'donde'::text,'El colchón sobre el que se deja caer al final es el más grande de la tienda.'::text),
(368150,40906,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le matelas ... elle se jette à la fin est le plus grand du magasin.'::text,'sur lequel'::text,'sur qui'::text,'où'::text,'Le matelas sur lequel elle se jette à la fin est le plus grand du magasin.'::text),
(368153,40906,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sonunda kendini üstüne ... yatak, mağazadaki en büyük yatak.'::text,'attığı'::text,'attığı'::text,'attığı yerdeki'::text,'Sonunda kendini üstüne attığı yatak, mağazadaki en büyük yatak.'::text),
(368154,40906,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A matrac, ... a végén rávetődik, a legnagyobb a boltban.'::text,'amelyre'::text,'akire'::text,'ahol'::text,'A matrac, amelyre a végén rávetődik, a legnagyobb a boltban.'::text),
(368157,40907,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast gesagt, du ... die große Matratze am nächsten Tag kaufen. Ehrlich, guter Geschmack.'::text,'würdest'::text,'wirst'::text,'kaufst'::text,'Du hast gesagt, du würdest die große Matratze am nächsten Tag kaufen. Ehrlich, guter Geschmack.'::text),
(368161,40907,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти сказала, що ... той великий матрац наступного дня. Чесно, класний смак.'::text,'купиш'::text,'купиш'::text,'купуєш'::text,'Ти сказала, що купиш той великий матрац наступного дня. Чесно, класний смак.'::text),
(368160,40907,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijiste que ... el colchón grande al día siguiente. En serio, qué buen gusto.'::text,'comprarías'::text,'comprarás'::text,'compras'::text,'Dijiste que comprarías el colchón grande al día siguiente. En serio, qué buen gusto.'::text),
(368159,40907,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu as dit que tu ... le grand matelas le lendemain. Franchement, t''as du goût.'::text,'achèterais'::text,'achèteras'::text,'achètes'::text,'Tu as dit que tu achèterais le grand matelas le lendemain. Franchement, t''as du goût.'::text),
(368162,40907,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Büyük yatağı ertesi gün ... söyledin. Açıkçası, zevkin harika.'::text,'alacağını'::text,'alacağını'::text,'aldığını'::text,'Büyük yatağı ertesi gün alacağını söyledin. Açıkçası, zevkin harika.'::text),
(368163,40907,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondtad, hogy másnap ... a nagy matracot. Őszintén, szuper ízlés.'::text,'megveszed'::text,'megveszed'::text,'megveszed'::text,'Azt mondtad, hogy másnap megveszed a nagy matracot. Őszintén, szuper ízlés.'::text),
(368166,40908,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... auf einer harten Matratze, aber dein neuer Geschmack ist viel besser. Respekt.'::text,'schliefst früher'::text,'bist gewohnt zu schlafen'::text,'schliefst früher'::text,'Du schliefst früher auf einer harten Matratze, aber dein neuer Geschmack ist viel besser. Respekt.'::text),
(368170,40908,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Раніше ти ... на твердому матраці, але твій новий смак набагато кращий. Повага.'::text,'спала'::text,'звикла спати'::text,'спала'::text,'Раніше ти спала на твердому матраці, але твій новий смак набагато кращий. Повага.'::text),
(368169,40908,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú ... dormir en un colchón duro, pero tu nuevo gusto es mucho mejor. Respeto.'::text,'solías'::text,'estás acostumbrada a'::text,'solías'::text,'Tú solías dormir en un colchón duro, pero tu nuevo gusto es mucho mejor. Respeto.'::text),
(368168,40908,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant, tu ... sur un matelas dur, mais ton nouveau goût est bien meilleur. Respect.'::text,'dormais'::text,'as l''habitude de dormir'::text,'dormais'::text,'Avant, tu dormais sur un matelas dur, mais ton nouveau goût est bien meilleur. Respect.'::text),
(368171,40908,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eskiden sert bir yatakta ..., ama yeni zevkin çok daha iyi. Saygı.'::text,'uyurdun'::text,'uyumaya alışkınsın'::text,'uyurdun'::text,'Eskiden sert bir yatakta uyurdun, ama yeni zevkin çok daha iyi. Saygı.'::text),
(368172,40908,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Régen kemény matracon ..., de az új ízlésed sokkal jobb. Respekt.'::text,'aludtál'::text,'szoktál aludni'::text,'aludtál'::text,'Régen kemény matracon aludtál, de az új ízlésed sokkal jobb. Respekt.'::text),
(368175,40909,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... dich ständig auf jede Matratze in diesem Showroom fallen.'::text,'lässt'::text,'lässt'::text,'lässt'::text,'Ehrlich, du lässt dich ständig auf jede Matratze in diesem Showroom fallen.'::text),
(368179,40909,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти раз у раз ... на кожен матрац у цьому шоурумі.'::text,'плюхаєшся'::text,'плюхаєшся'::text,'плюхаєшся'::text,'Чесно, ти раз у раз плюхаєшся на кожен матрац у цьому шоурумі.'::text),
(368178,40909,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En serio, no paras de ... en todos los colchones de esta tienda.'::text,'tirarte'::text,'tirarte'::text,'tirarte'::text,'En serio, no paras de tirarte en todos los colchones de esta tienda.'::text),
(368177,40909,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu n''arrêtes pas de te ... sur chaque matelas de ce showroom.'::text,'jeter'::text,'jeter'::text,'jeter'::text,'Franchement, tu n''arrêtes pas de te jeter sur chaque matelas de ce showroom.'::text),
(368180,40909,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, bu showroomdaki her yatağa kendini ... duruyorsun.'::text,'atıp'::text,'atıp'::text,'atıp'::text,'Açıkçası, bu showroomdaki her yatağa kendini atıp duruyorsun.'::text),
(368181,40909,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, folyton ... minden matracra ebben a bemutatóteremben.'::text,'rávetődsz'::text,'rávetődsz'::text,'rávetődsz'::text,'Őszintén, folyton rávetődsz minden matracra ebben a bemutatóteremben.'::text),
(368184,40910,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die erste Matratze war eindeutig makellos, ... Schau dir ihr Gesicht an.'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Die erste Matratze war eindeutig makellos, oder? Schau dir ihr Gesicht an.'::text),
(368188,40910,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Той перший матрац був явно бездоганний, ... Подивись на її обличчя.'::text,'так?'::text,'так?'::text,'так?'::text,'Той перший матрац був явно бездоганний, так? Подивись на її обличчя.'::text),
(368187,40910,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ese primer colchón era claramente impecable, ¿... Mírale la cara.'::text,'verdad?'::text,'verdad?'::text,'verdad?'::text,'Ese primer colchón era claramente impecable, ¿verdad? Mírale la cara.'::text),
(368186,40910,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce premier matelas était clairement parfait, ... Regarde sa tête.'::text,'pas vrai ?'::text,'pas vrai ?'::text,'pas vrai ?'::text,'Ce premier matelas était clairement parfait, pas vrai ? Regarde sa tête.'::text),
(368189,40910,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O ilk yatak besbelli kusursuzdu, ... Yüzüne bak.'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'O ilk yatak besbelli kusursuzdu, değil mi? Yüzüne bak.'::text),
(368190,40910,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az első matrac egyértelműen hibátlan volt, ... Nézd az arcát.'::text,'ugye?'::text,'ugye?'::text,'ugye?'::text,'Az első matrac egyértelműen hibátlan volt, ugye? Nézd az arcát.'::text),
(368193,40911,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die erste Matratze war nicht bequem, und ... die zweite. Super gemacht, Laden.'::text,'auch nicht'::text,'auch'::text,'auch nicht'::text,'Die erste Matratze war nicht bequem, und auch nicht die zweite. Super gemacht, Laden.'::text),
(368197,40911,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перший матрац був незручний, і ... другий. Чудова робота, магазин.'::text,'так само й'::text,'так само й'::text,'так само й'::text,'Перший матрац був незручний, і так само й другий. Чудова робота, магазин.'::text),
(368196,40911,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El primer colchón no era cómodo, y ... el segundo. Buen trabajo, tienda.'::text,'tampoco'::text,'también'::text,'tampoco'::text,'El primer colchón no era cómodo, y tampoco el segundo. Buen trabajo, tienda.'::text),
(368195,40911,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le premier matelas n''était pas confortable, et le deuxième ... ! Bravo, le magasin.'::text,'non plus'::text,'aussi'::text,'non plus'::text,'Le premier matelas n''était pas confortable, et le deuxième non plus ! Bravo, le magasin.'::text),
(368198,40911,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İlk yatak rahat değildi, ... ikincisi. Harika iş, mağaza.'::text,'ne de'::text,'ve'::text,'ne de'::text,'İlk yatak rahat değildi, ne de ikincisi. Harika iş, mağaza.'::text),
(368199,40911,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az első matrac nem volt kényelmes, és ... a második. Szép munka, bolt.'::text,'nem volt az'::text,'az volt'::text,'nem volt az'::text,'Az első matrac nem volt kényelmes, és nem volt az a második. Szép munka, bolt.'::text),
(368202,40912,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Offensichtlich sehr beschäftigt: Sie ... den ganzen Vormittag auf Matratzen.'::text,'liegt schon'::text,'liegt'::text,'liegt gerade'::text,'Offensichtlich sehr beschäftigt: Sie liegt schon den ganzen Vormittag auf Matratzen.'::text),
(368206,40912,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Явно дуже зайнята: вона ... на матрацах увесь ранок.'::text,'лежить'::text,'лежить'::text,'лежить'::text,'Явно дуже зайнята: вона лежить на матрацах увесь ранок.'::text),
(368205,40912,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Obviamente muy ocupada: ... en colchones toda la mañana.'::text,'ha estado tumbada'::text,'se tumba'::text,'está tumbada'::text,'Obviamente muy ocupada: ha estado tumbada en colchones toda la mañana.'::text),
(368204,40912,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Évidemment très occupée : elle ... sur des matelas toute la matinée.'::text,'est allongée'::text,'s''allonge'::text,'est allongée'::text,'Évidemment très occupée : elle est allongée sur des matelas toute la matinée.'::text),
(368207,40912,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki çok meşgul: bütün sabah yataklarda ...'::text,'yatıyor'::text,'yatar'::text,'yatıyor'::text,'Belli ki çok meşgul: bütün sabah yataklarda yatıyor.'::text),
(368208,40912,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván nagyon elfoglalt: egész délelőtt matracokon ...'::text,'fekszik'::text,'fekszik'::text,'fekszik'::text,'Nyilván nagyon elfoglalt: egész délelőtt matracokon fekszik.'::text),
(385050,42784,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mechaniker verspricht, dass er das Auto bis fünf Uhr ...'::text,'wartet'::text,'gerade warten wird'::text,'gerade wartet'::text,'Der Mechaniker verspricht, dass er das Auto bis fünf Uhr wartet.'::text),
(385054,42784,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Механік обіцяє, що ... техобслуговування авто до п''ятої.'::text,'зробить'::text,'робитиме'::text,'робить'::text,'Механік обіцяє, що зробить техобслуговування авто до п''ятої.'::text),
(385053,42784,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El mecánico promete que ... la revisión del coche para las cinco.'::text,'hará'::text,'estará haciendo'::text,'está haciendo'::text,'El mecánico promete que hará la revisión del coche para las cinco.'::text),
(385052,42784,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le mécanicien promet qu''il ... la voiture d''ici cinq heures.'::text,'révisera'::text,'sera en train de réviser'::text,'révise'::text,'Le mécanicien promet qu''il révisera la voiture d''ici cinq heures.'::text),
(385055,42784,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamirci arabanın bakımını saat beşe kadar ... söz veriyor.'::text,'yapacağına'::text,'yapıyor olacağına'::text,'yaptığına'::text,'Tamirci arabanın bakımını saat beşe kadar yapacağına söz veriyor.'::text),
(385056,42784,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szerelő megígéri, hogy ötre ... az autót.'::text,'megszervizeli'::text,'épp szervizelni fogja'::text,'épp szervizeli'::text,'A szerelő megígéri, hogy ötre megszervizeli az autót.'::text),
(385068,42786,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er das Auto heute wartet, ... der Besitzer es morgen ab.'::text,'holt'::text,'holte'::text,'holte'::text,'Wenn er das Auto heute wartet, holt der Besitzer es morgen ab.'::text),
(385072,42786,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він сьогодні обслужить авто, власник ... його завтра.'::text,'забере'::text,'забрав би'::text,'забрав'::text,'Якщо він сьогодні обслужить авто, власник забере його завтра.'::text),
(385071,42786,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si hoy le hace la revisión al coche, el dueño lo ... mañana.'::text,'recogerá'::text,'recogería'::text,'recogió'::text,'Si hoy le hace la revisión al coche, el dueño lo recogerá mañana.'::text),
(385070,42786,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il révise la voiture aujourd''hui, le propriétaire la ... demain.'::text,'récupérera'::text,'récupérerait'::text,'a récupérée'::text,'S''il révise la voiture aujourd''hui, le propriétaire la récupérera demain.'::text),
(385073,42786,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arabanın bakımını bugün yaparsa, sahibi onu yarın ...'::text,'alacak'::text,'alırdı'::text,'aldı'::text,'Arabanın bakımını bugün yaparsa, sahibi onu yarın alacak.'::text),
(385074,42786,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ma megszervizeli az autót, a tulajdonos holnap ...'::text,'elviszi'::text,'elvinné'::text,'elvitte'::text,'Ha ma megszervizeli az autót, a tulajdonos holnap elviszi.'::text),
(385077,42787,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, wenn du mein Auto ..., würde ich ihm für immer vertrauen.'::text,'warten würdest'::text,'wartest'::text,'warten würdest'::text,'Ehrlich, wenn du mein Auto warten würdest, würde ich ihm für immer vertrauen.'::text),
(385081,42787,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, якби ти ... мою машину, я б довіряла їй назавжди.'::text,'обслужив'::text,'обслуговуєш'::text,'обслужив би'::text,'Чесно, якби ти обслужив мою машину, я б довіряла їй назавжди.'::text),
(385080,42787,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En serio, si tú ... mi coche, confiaría en él para siempre.'::text,'revisaras'::text,'revisas'::text,'revisarías'::text,'En serio, si tú revisaras mi coche, confiaría en él para siempre.'::text),
(385079,42787,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, si tu ... ma voiture, je lui ferais confiance pour toujours.'::text,'révisais'::text,'révises'::text,'réviserais'::text,'Franchement, si tu révisais ma voiture, je lui ferais confiance pour toujours.'::text),
(385082,42787,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, arabamın bakımını sen ..., ona sonsuza dek güvenirdim.'::text,'yapsaydın'::text,'yapıyorsun'::text,'yapardın'::text,'Açıkçası, arabamın bakımını sen yapsaydın, ona sonsuza dek güvenirdim.'::text),
(385083,42787,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ha te ... az autómat, örökre megbíznék benne.'::text,'szervizelnéd'::text,'szervizeled'::text,'szervizelnéd'::text,'Őszintén, ha te szervizelnéd az autómat, örökre megbíznék benne.'::text),
(385086,42788,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das silberne Auto ... gestern in einer vollen Werkstatt gewartet.'::text,'wurde'::text,'wartete'::text,'wird'::text,'Das silberne Auto wurde gestern in einer vollen Werkstatt gewartet.'::text),
(385090,42788,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сріблясту машину ... вчора в завантаженій автомайстерні.'::text,'обслужили'::text,'обслужила'::text,'обслуговують'::text,'Сріблясту машину обслужили вчора в завантаженій автомайстерні.'::text),
(385089,42788,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El coche plateado ... ayer en un taller muy concurrido.'::text,'fue revisado'::text,'revisó'::text,'es revisado'::text,'El coche plateado fue revisado ayer en un taller muy concurrido.'::text),
(385088,42788,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La voiture argentée ... hier dans un garage bondé.'::text,'a été révisée'::text,'a révisé'::text,'est révisée'::text,'La voiture argentée a été révisée hier dans un garage bondé.'::text),
(385091,42788,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gümüş renkli arabanın bakımı dün kalabalık bir tamirhanede ...'::text,'yapıldı'::text,'yaptı'::text,'yapılıyor'::text,'Gümüş renkli arabanın bakımı dün kalabalık bir tamirhanede yapıldı.'::text),
(385092,42788,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ezüst autót tegnap egy forgalmas szervizben ...'::text,'szervizelték'::text,'szervizelte'::text,'szervizelik'::text,'Az ezüst autót tegnap egy forgalmas szervizben szervizelték.'::text),
(385095,42789,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mechaniker ... das ganze Auto an einem Nachmittag. Klar, ein ruhiger Tag.'::text,'wartete'::text,'wurde gewartet'::text,'wartend'::text,'Der Mechaniker wartete das ganze Auto an einem Nachmittag. Klar, ein ruhiger Tag.'::text),
(385099,42789,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Механік ... всю машину за одне пообіддя. Явно спокійний день.'::text,'обслужив'::text,'був обслужений'::text,'обслуговуючи'::text,'Механік обслужив всю машину за одне пообіддя. Явно спокійний день.'::text),
(385098,42789,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El mecánico ... el coche entero en una tarde. Claramente un día tranquilo.'::text,'revisó'::text,'fue revisado'::text,'revisando'::text,'El mecánico revisó el coche entero en una tarde. Claramente un día tranquilo.'::text),
(385097,42789,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le mécanicien ... toute la voiture en un après-midi. Clairement une journée tranquille.'::text,'a révisé'::text,'a été révisé'::text,'révisant'::text,'Le mécanicien a révisé toute la voiture en un après-midi. Clairement une journée tranquille.'::text),
(385100,42789,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki sakin bir gündü: tamirci bütün arabanın bakımını tek bir öğleden sonrada ...'::text,'yaptı'::text,'yapıldı'::text,'yaparak'::text,'Belli ki sakin bir gündü: tamirci bütün arabanın bakımını tek bir öğleden sonrada yaptı.'::text),
(385101,42789,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szerelő egyetlen délután alatt ... az egész autót. Nyilván nyugis nap volt.'::text,'megszervizelte'::text,'meg lett szervizelve'::text,'szervizelve'::text,'A szerelő egyetlen délután alatt megszervizelte az egész autót. Nyilván nyugis nap volt.'::text),
(385104,42790,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er sieht zufrieden aus, also ... er mit dem Service am Auto fertig sein. Makellose Schlussfolgerung.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Er sieht zufrieden aus, also muss er mit dem Service am Auto fertig sein. Makellose Schlussfolgerung.'::text),
(385108,42790,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він виглядає задоволеним, тож він ... закінчив обслуговувати машину. Бездоганна дедукція.'::text,'напевно'::text,'не міг'::text,'мав би'::text,'Він виглядає задоволеним, тож він напевно закінчив обслуговувати машину. Бездоганна дедукція.'::text),
(385107,42790,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Parece satisfecho, así que ... haber terminado la revisión del coche. Deducción impecable.'::text,'debe de'::text,'no puede'::text,'debería'::text,'Parece satisfecho, así que debe de haber terminado la revisión del coche. Deducción impecable.'::text),
(385106,42790,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a l''air satisfait, donc il ... avoir fini de réviser la voiture. Déduction impeccable.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Il a l''air satisfait, donc il doit avoir fini de réviser la voiture. Déduction impeccable.'::text),
(385109,42790,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Memnun görünüyor, yani arabanın bakımını bitirmiş ..., kusursuz bir çıkarım.'::text,'olmalı'::text,'olamaz'::text,'olmalı'::text,'Memnun görünüyor, yani arabanın bakımını bitirmiş olmalı, kusursuz bir çıkarım.'::text),
(385110,42790,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elégedettnek tűnik, szóval ... befejezte az autó szervizelését. Hibátlan következtetés.'::text,'biztosan'::text,'kizárt, hogy'::text,'elvileg'::text,'Elégedettnek tűnik, szóval biztosan befejezte az autó szervizelését. Hibátlan következtetés.'::text),
(385113,42791,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mechaniker, ... das Auto gewartet hat, schließt die Motorhaube wie ein echter Held. Offensichtlich.'::text,'der'::text,'das'::text,'dessen'::text,'Der Mechaniker, der das Auto gewartet hat, schließt die Motorhaube wie ein echter Held. Offensichtlich.'::text),
(385117,42791,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Механік, ... обслужив машину, закриває капот, як справжній герой. Очевидно.'::text,'який'::text,'яке'::text,'чий'::text,'Механік, який обслужив машину, закриває капот, як справжній герой. Очевидно.'::text),
(385116,42791,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El mecánico ... revisó el coche cierra el capó como un auténtico héroe. Obviamente.'::text,'que'::text,'el cual'::text,'cuyo'::text,'El mecánico que revisó el coche cierra el capó como un auténtico héroe. Obviamente.'::text),
(385115,42791,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le mécanicien ... a révisé la voiture referme le capot comme un vrai héros. Évidemment.'::text,'qui'::text,'lequel'::text,'dont'::text,'Le mécanicien qui a révisé la voiture referme le capot comme un vrai héros. Évidemment.'::text),
(385118,42791,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arabanın bakımını ... tamirci, kaputu gerçek bir kahraman gibi kapatıyor. Tabii ki.'::text,'yapan'::text,'yaptığı'::text,'yapanın'::text,'Arabanın bakımını yapan tamirci, kaputu gerçek bir kahraman gibi kapatıyor. Tabii ki.'::text),
(385119,42791,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szerelő, ... megszervizelte az autót, úgy csukja le a motorháztetőt, mint egy igazi hős. Nyilván.'::text,'aki'::text,'ami'::text,'akinek'::text,'A szerelő, aki megszervizelte az autót, úgy csukja le a motorháztetőt, mint egy igazi hős. Nyilván.'::text),
(385122,42792,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mechaniker schwor, er ... dieses Auto zum allerletzten Mal!'::text,'warte'::text,'wartet'::text,'wartet'::text,'Der Mechaniker schwor, er warte dieses Auto zum allerletzten Mal!'::text),
(385126,42792,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Механік поклявся, що ... цю машину востаннє, назавжди!'::text,'обслуговує'::text,'обслуговує'::text,'обслуговує'::text,'Механік поклявся, що обслуговує цю машину востаннє, назавжди!'::text),
(385125,42792,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El mecánico juró que ... este coche por última vez, para siempre!'::text,'estaba revisando'::text,'está revisando'::text,'revisa'::text,'¡El mecánico juró que estaba revisando este coche por última vez, para siempre!'::text),
(385124,42792,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le mécanicien a juré qu''il ... cette voiture pour la dernière fois, à jamais !'::text,'révisait'::text,'révise'::text,'révise'::text,'Le mécanicien a juré qu''il révisait cette voiture pour la dernière fois, à jamais !'::text),
